import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qa-1","status":"entwurf","clusterId":"A","werkstueckRef":"A.1.1","stufe":1,"question":"Welche Frage hilft dir am besten, die drei Vorschläge zu vergleichen, wenn keiner sofort widerlegt werden kann?","scenario":"Du kommst nach Hause und findest auf dem Küchentisch einen zerbrochenen Keks. Du lebst allein, die Wohnung ist abgeschlossen, nichts fehlt. Drei Leute haben Vorschläge: Eine Freundin vermutet eine leichte Erschütterung von der Straße, ein Bekannter einen heimlichen Besuch mit Zweitschlüssel, eine Kollegin ein Wesen, das durch ein Wurmloch kam.","options":["Welcher Vorschlag stammt von der Person, die dich und deine Wohnung am besten kennt?","Welcher der drei Vorschläge kommt mit den wenigsten neuen, unbewiesenen Annahmen aus?","Welcher der drei Vorschläge hätte für dich die ernstesten Folgen, etwa ein fremder Besuch?","Welchem der drei Vorschläge stimmen die meisten Bekannten zu, wenn du ihnen den Keks zeigst?"],"correctIndex":1,"explanation":"Wenn mehrere Erklärungen den Befund erklären und keine widerlegt ist, ist die sparsamste die bessere Ausgangsbasis: die mit den wenigsten neuen, unbewiesenen Annahmen. Die Erschütterung braucht nur Bekanntes: Straße, Verkehr, Schwerkraft. Der heimliche Besuch braucht zusätzlich eine weitere Person, die hereinkommt, ein Motiv und einen Zweitschlüssel – lauter Annahmen, die du erst belegen müsstest. Das Wurmloch-Wesen braucht eine ganze Kaskade neuer Dinge, deren Existenz niemand belegt hat. Das Rasiermesser beweist dabei nicht, dass die sparsame Erklärung stimmt; es sagt nur, womit man die Prüfung sinnvoll beginnt. Wer dich und deine Wohnung am besten kennt, klingt nach gutem Urteil, war aber beim zerbrochenen Keks genauso wenig dabei wie die anderen und hat keine zusätzlichen Belege. Die Frage nach den ernstesten Folgen klingt vorsichtig, bestimmt aber nur, wie sorgfältig du nachsiehst, nicht, wie wahrscheinlich ein Besuch mit Zweitschlüssel ist. Die Zustimmung der Bekannten klingt nach Rückhalt, doch auch sie kennen nur den Keks und haben keine Belege, die du nicht hättest.","coreRule":"⚡ Sparsamkeitsprinzip: Bei gleich gut passenden Erklärungen beginne mit der, die die wenigsten unbewiesenen Annahmen braucht.","quote":"Welche neuen Welten muss ich erfinden, damit diese Erklärung wahr ist?","quoteLabel":"Prüffrage","beleg":"Werkstück A.1.1 Ockhams Rasiermesser, Abschnitte „Kernidee“, „Kontext & Tiefe“, „Anti-Denkmuster“ (Aktivierungs-Frage); Fußnote ga-ockham betrifft nur die Herkunft der Formel","kurz":"Wenn keiner der Vorschläge widerlegt ist, beginnst du mit dem, der die wenigsten neuen, unbewiesenen Annahmen braucht. Das beweist nicht, dass er stimmt; ein bloßer Eindruck von Kompetenz, Gefahr oder Rückhalt ersetzt aber keinen Beleg.","prueffrage":"Welche der drei Ursachen hast du selbst schon einmal erlebt oder beobachtet, und welche kennst du nur aus Geschichten?","rueckmeldung":[{"option":0,"text":"Wer dich und deine Wohnung gut kennt, mag Vertrautes besser einordnen. Beim zerbrochenen Keks war aber auch diese Person nicht dabei und hat keine zusätzlichen Belege, sodass die Vorschläge damit nicht besser verglichen sind."},{"option":2,"text":"Ernste Folgen sind ein guter Grund, gründlicher nachzusehen. Wie wahrscheinlich ein Besuch mit Zweitschlüssel ist, sagt das aber nicht: Es bestimmt nur den Aufwand der Prüfung, nicht den Vergleich der Erklärungen."},{"option":3,"text":"Viel Zustimmung wirkt wie Rückhalt. Auch deine Bekannten sehen aber nur den Keks und haben keine Belege, die du nicht ohnehin hättest. Die Zahl der Zustimmenden macht einen Vorschlag nicht wahrscheinlicher."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 1–2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Thorburn, W. M. (1918): The Myth of Occam's Razor. Mind 27(3), 345–353","oeffentlich":false,"doi":"10.1093/mind/XXVII.3.345"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"8a3471bf6a02118d"}},{"id":"qa-2","status":"entwurf","clusterId":"A","werkstueckRef":"A.1.2","stufe":1,"question":"Was ist die vernünftigste Reaktion?","scenario":"Du schickst deiner Chefin am Vorabend der großen Präsentation einen Bericht, in den du viele Stunden investiert hast. Am Morgen ist dein Posteingang leer, und in der Präsentation fällt der Bericht mit keinem Wort. Eine Kollegin sagt: „Die ignoriert dich mit Absicht. Das ist Sabotage.“","options":["Den leeren Posteingang als Zustimmung werten, denn bei Mängeln hätte die Chefin vor der Präsentation geantwortet.","Der Kollegin folgen, denn wer einen Bericht in der Präsentation verschweigt, will damit die eigene Wirkung vergrößern.","Den Bericht für schwach halten, denn gute Arbeit nach so vielen Stunden würde die Chefin in der Präsentation erwähnen.","Zuerst eine harmlose Erklärung prüfen, etwa dass die Chefin den Bericht übersehen hat, bevor du Absicht unterstellst."],"correctIndex":3,"explanation":"Für Sabotage müssten gleich mehrere Dinge zusammenkommen: böse Absicht, geschickte Verstellung, ein aktiver Plan und die Bereitschaft, den Erfolg der Firma dafür zu riskieren. Für eine Panne genügt eine einzige, allgemein bekannte Annahme: Systeme fallen aus, und Menschen sind überlastet oder vergesslich. Da Chaos und Zufall im Alltag weit häufiger sind als kalkulierte Intrigen, ist die banale Erklärung die bessere Ausgangshypothese. Das ist keine Garantie, sondern ein Startpunkt: Ein kurzes Nachfragen oder Nachsehen klärt es meist schnell. Den leeren Posteingang als Zustimmung zu lesen, klingt wohlwollend, wäre aber nur sinnvoll, wenn eine Rückmeldung bei Mängeln ausdrücklich verabredet wäre; hier bleibt der Bericht schlicht unerwähnt. Der Kollegin zu folgen, klingt nach Menschenkenntnis, setzt aber eine Absicht voraus, die erst eine von vielen möglichen Deutungen ist und nicht schon als Tatsache gelten darf. Den Bericht für schwach zu halten, klingt selbstkritisch, folgt aus dem Schweigen aber nicht, denn auch gute Arbeit wird im Trubel übergangen.","coreRule":"⚡ Schreibe nicht der Bosheit zu, was Dummheit, Fahrlässigkeit oder Zufall hinreichend erklären.","quote":"Was wäre die unbösartigste, chaotischste oder dümmste mögliche Erklärung für dieses Ereignis?","quoteLabel":"Prüffrage:","beleg":"Werkstück A.1.2, Abschnitte „Der E-Mail-Affront“ und „Kontext & Tiefe“ (Hypothese A vs. B); Fußnote ga-hanlon betrifft nur die Herkunft des Namens.","kurz":"Für eine Panne reicht eine einzige alltägliche Annahme, etwa dass der Bericht übersehen wurde. Für Sabotage müssten Absicht, Verstellung und Plan zusammenkommen. Deshalb ist die banale Erklärung der bessere Startpunkt, und ein kurzes Nachfragen klärt es meist.","prueffrage":"Was alles kann zwischen dem Abschicken am Vorabend und der Präsentation am Morgen schiefgegangen sein?","rueckmeldung":[{"option":0,"text":"Wohlwollend zu denken wirkt entspannt. Das hielte aber nur, wenn bei Mängeln eine Rückmeldung verabredet wäre. Hier ist nur bekannt, dass der Bericht unerwähnt blieb; Zustimmung ist eine Deutung ohne Beleg."},{"option":1,"text":"Dass der Bericht ausgelassen wurde, ist real. Die Absicht dahinter bleibt aber eine Deutung unter mehreren und ist noch keine Tatsache. Sabotage setzt zudem mehrere Dinge zugleich voraus, ein Versehen kommt mit einem aus."},{"option":2,"text":"Selbstkritik ist grundsätzlich gesund. Hier fehlt ihr aber der Anlass: Aus dem Schweigen lässt sich nicht auf die Qualität schließen, denn auch gute Arbeit geht im Trubel einer Präsentation leicht unter."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"83c3a4c9f2a37eff"}},{"id":"qa-3","status":"entwurf","clusterId":"A","werkstueckRef":"A.3","stufe":2,"question":"Nach dem Gespräch mit einem Nachbarn bist du verblüfft: Du hast jeden Test vorgeschlagen, den du dir ausdenken konntest, und jedes Mal hat er eine neue Bedingung ergänzt. Was ist an seiner Behauptung am grundsätzlichsten problematisch?","options":["Sie ist äußerst unwahrscheinlich, denn schwebende, körperlose Drachen mit hitzefreiem Feuer kennt man aus der Natur nicht.","Ihr fehlt ein Beleg, denn sie stützt sich nur auf sein eigenes Wort, und schon ein Foto oder ein Zeuge könnte die Frage klären.","Sie widerspricht sich selbst, denn ein Feuer ohne Hitze und ein Drache ohne Körper sind in sich unstimmige Vorstellungen.","Keine denkbare Beobachtung könnte sie widerlegen, denn er wehrt Test um Test mit einer nachgeschobenen Zusatzbedingung ab."],"correctIndex":3,"explanation":"Eine Aussage ist nur dann wissenschaftlich oder rational wertvoll, wenn es eine denkbare Beobachtung gibt, die sie widerlegen könnte. Hier wird jeder Test durch eine nachgeschobene Bedingung entwertet, und am Ende ist die Behauptung von der Aussage „da ist gar kein Drache“ durch keine Messung mehr zu unterscheiden. Das ist etwas anderes als Falschsein: Eine falsche Aussage kann widerlegt werden, eine immunisierte Aussage sagt dagegen nichts über die Welt aus, weil sie nichts verbietet. Entscheidend ist also nicht, wie unwahrscheinlich eine Behauptung klingt, sondern ob sie ein echtes Risiko des Scheiterns trägt. Einsteins Vorhersage der Lichtablenkung an der Sonne (Sonnenfinsternis 1919) hätte scheitern können; genau das machte sie überprüfbar.","coreRule":"⚡ Prüfbar ist nur, was scheitern könnte: Frag immer, welche Beobachtung die Behauptung widerlegen würde.","quote":"„Now, what's the difference between an invisible, incorporeal, floating dragon who spits heatless fire and no dragon at all?“ Frei übersetzt: Was unterscheidet einen unsichtbaren, unkörperlichen, schwebenden Drachen, der Feuer ohne Hitze speit, von gar keinem Drachen?","quoteLabel":"Carl Sagan, The Demon-Haunted World, Kap. 10, S. 161 (Original):","scenario":"Ein Nachbar behauptet: „In meiner Garage lebt ein unsichtbarer, unhörbarer Drache, der hitzefreies Feuer speit.“ Du schlägst vor, Mehl auf den Boden zu streuen, um Fußspuren zu sehen. Er antwortet: „Der Drache schwebt.“ Du willst eine Infrarotkamera einsetzen. Er sagt: „Sein Feuer ist hitzefrei.“ Du willst Farbe versprühen, um die Umrisse zu zeigen. Er meint: „Er ist körperlos, die Farbe geht einfach durch ihn hindurch.“","beleg":"Szene frei nach Sagan, C. (1995/1996): The Demon-Haunted World, Kap. 10 „The Dragon in My Garage“ (Headline-Ausgabe 1997, S. 160–161); das Zitat steht dort wörtlich auf S. 161 (geprüft im Volltext, Calibre buecher-sachbuecher:9271, PDF-S. 173); die deutsche Fassung ist eine eigene Übersetzung. Werkstück A.3, Fußnoten ga-drache und ga-popper.","kurz":"Die Behauptung trägt kein Risiko zu scheitern: Jede Beobachtung wird durch eine neue Bedingung entwertet, bis sie von „da ist kein Drache“ nicht mehr zu unterscheiden ist. Sie ist nicht nur falsch, sondern sagt nichts über die Welt.","prueffrage":"Wie viele Eigenschaften hatte der Drache zu Beginn, und wie viele kamen nach deinen Vorschlägen hinzu?","rueckmeldung":[{"option":0,"text":"Dass es so etwas in der Natur nicht gibt, spricht tatsächlich gegen den Drachen. Unwahrscheinlichkeit lässt sich aber mit Beobachtungen prüfen und ist nicht das Hauptproblem; das liegt darin, dass hier keine Beobachtung mehr zählt."},{"option":1,"text":"Fehlende Belege sind ein berechtigter Einwand. Das Foto oder der Zeuge würde hier aber nichts klären, weil der Nachbar auch dagegen eine passende Zusatzbedingung fände. Das Problem liegt tiefer als der Mangel an Belegen."},{"option":2,"text":"Hitzefreies Feuer und ein Drache ohne Körper klingen seltsam. Dass sie sich logisch ausschließen, ist damit aber nicht gezeigt. Ein Widerspruch wäre zudem ein Fall von Falschsein; hier geht es darum, dass die Behauptung nie scheitern kann."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House, Kap. 10 „The Dragon in My Garage“","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"861280dd09ab71e8"}},{"id":"qa-4","status":"entwurf","clusterId":"A","werkstueckRef":"A.4","stufe":1,"question":"Ein Kollege erzählt dir ernsthaft, in seiner Garage lebe ein unsichtbarer, lautloser und nicht messbarer Drache. Auf deine Skepsis antwortet er: „Dann beweis mir doch, dass es ihn nicht gibt!“ Was ist an dieser Forderung das eigentliche Problem?","options":["Er verlangt von dir den Nachweis einer Nicht-Existenz, obwohl er die Behauptung aufstellt und ihre Belege liefern müsste.","Er verlangt einen Gegenbeweis, obwohl ihr beide nichts beweisen könnt und die Frage deshalb schlicht unentscheidbar bleibt.","Er verlangt einen Gegenbeweis, obwohl er erst genauer sagen müsste, was ein nicht messbarer Drache überhaupt sein soll.","Er weicht deiner Skepsis aus, obwohl er auf deine Zweifel eingehen und sie mit eigenen Gründen entkräften müsste."],"correctIndex":0,"explanation":"Wer etwas behauptet, muss es belegen; der Zweifler muss das Gegenteil nicht beweisen. Die Nicht-Existenz solcher Dinge lässt sich ohnehin nicht nachweisen: Der unsichtbare Drache in der Garage und Russells Teekanne zwischen Erde und Mars sind Beispiele dafür. Würde die Beweislast beim Zweifler liegen, müsste man unendlich viele fantastische Behauptungen widerlegen, was unmöglich ist. Dass etwas nicht widerlegt wurde, ist kein Beleg dafür, dass es stimmt. Je außergewöhnlicher die Behauptung, desto stärker müssen die Belege sein.","coreRule":"⚡ Wer behauptet, muss belegen: Was ohne Beweis behauptet werden kann, kann auch ohne Beweis verworfen werden.","quote":"Außergewöhnliche Behauptungen erfordern außergewöhnliche Beweise.","quoteLabel":"Carl Sagan (nach Marcello Truzzi), frei übersetzt:","scenario":"","beleg":"Werkstück A.4: Kernidee, Kontext & Tiefe (Beweislast, Hitchens’ Rasiermesser, außergewöhnliche Behauptungen), Red Flags („Kannst du das Gegenteil beweisen?“). Der Satz „Extraordinary claims require extraordinary evidence“ wird Carl Sagan zugeschrieben, ähnlich Marcello Truzzi („extraordinary proof“); nachgewiesen in Prothero (2017), UFOs, Chemtrails, and Aliens, und Loxton/Prothero (2013), Abominable Science!, jeweils als Sagans bekannter Satz nach Truzzi (Volltext Calibre buecher-sachbuecher:8727 und :8869); die deutsche Fassung ist eine eigene Übersetzung.","kurz":"Wer etwas behauptet, muss es belegen. Der Zweifler muss das Gegenteil nicht beweisen, und die Nicht-Existenz eines unsichtbaren Drachen lässt sich ohnehin nicht nachweisen. Aus „nicht widerlegt“ folgt nicht „stimmt“.","prueffrage":"Wie viele andere unsichtbare Wesen in anderen Garagen müsstest du nach dieser Forderung ebenfalls widerlegen?","rueckmeldung":[{"option":1,"text":"Dass sich hier nichts beweisen lässt, stimmt für die Nicht-Existenz. Beide Seiten stehen deshalb aber nicht gleich da: Die Belege schuldet, wer behauptet. Eine Behauptung ohne Beleg ist keine offene Frage auf Augenhöhe."},{"option":2,"text":"Eine Behauptung, die jede Messung ausschließt, ist tatsächlich dürftig, und Nachfragen wären sinnvoll. Die Forderung kippt aber nicht erst durch fehlende Klarheit: Selbst ein genau beschriebener Drache entbindet den Behauptenden nicht von der Beweislast."},{"option":3,"text":"Dass er auf deine Zweifel nicht eingeht, ist richtig beobachtet. Das ist aber nur das Auffällige an der Oberfläche. Das eigentliche Problem liegt tiefer: Er schiebt dir die Beweislast zu, für einen Beweis, der sich gar nicht führen lässt."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House, Kap. 10 „The Dragon in My Garage“","oeffentlich":false},{"typ":"literatur","kurz":"Russell, B. (1952): Is There a God? In: Collected Papers of Bertrand Russell, Bd. 11. London: Routledge 1997, 543–548","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"696f6e573bfdcd2c"}},{"id":"qa-5","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"0bb818433c6751d2","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"clusterId":"A","werkstueckRef":"A.7","stufe":3,"question":"Wie schätzt du die Wahrscheinlichkeit ein, dass du tatsächlich krank bist?","options":["Etwa 99 %: Der Test erkennt 99 von 100 Kranken, also stammt ein positives Ergebnis wie deines fast immer von einem tatsächlich Kranken.","Etwa 50 %: Kranke und Gesunde werden gleich oft richtig erkannt, also sind echte Treffer und Fehlalarme unter den Positiven gleich häufig.","Knapp 1 %: Von 1 Million Menschen testen 99 Kranke und rund 10.000 Gesunde positiv, also ist nur etwa jedes hundertste Positive echt.","Etwa 0,01 %: Nur 1 von 10.000 Menschen ist krank, und ein einzelnes positives Ergebnis ändert an dieser Ausgangslage so gut wie nichts."],"correctIndex":2,"explanation":"Rechne mit natürlichen Häufigkeiten: Bei 1 Million Menschen sind 100 krank, davon testen 99 positiv. Von den 999.900 Gesunden testen 1 % falsch positiv, das sind 9.999 Menschen. Unter den 10.098 positiven Ergebnissen sind also nur 99 echte Fälle, das sind etwa 0,98 %. Entscheidend ist die niedrige Basisrate der Krankheit: Sie lässt die Fehlalarme die echten Fälle weit überwiegen. Die 99 % des Freundes beziehen sich auf die Kranken, gefragt ist aber der Anteil echter Fälle unter den Positiven. Die 50 % übersehen, dass die 1 % Fehlalarme von einer rund zehntausendmal größeren Gruppe stammen. Und die 0,01 % lassen den Test ganz weg, obwohl das positive Ergebnis die Wahrscheinlichkeit von 1 zu 10.000 auf knapp 1 zu 100 hebt.","coreRule":"⚡ Verwechsle nie die Genauigkeit eines Tests mit der Wahrscheinlichkeit, dass du betroffen bist: Ohne die Ausgangshäufigkeit (Basisrate) lässt sich ein positives Ergebnis nicht deuten.","quote":"","quoteLabel":"","scenario":"Bei einer Routineuntersuchung wirst du auf eine seltene Krankheit getestet, von der 1 von 10.000 Menschen betroffen ist. Der Test erkennt 99 % der Kranken und 99 % der Gesunden korrekt. Dein Ergebnis ist positiv, Symptome hast du keine. Ein Freund sagt: „Der Test ist zu 99 % genau, also bist du zu 99 % krank.“","beleg":"Werkstück A.7 „Probabilistisches Denken“, Abschnitt „Kontext & Tiefe“ (Der Test des Arztes, Berechnung mit natürlichen Häufigkeiten)","kurz":"Unter den positiven Ergebnissen sind nur etwa 99 von 10.098 echte Fälle, denn die wenigen Kranken werden von den vielen Gesunden mit Fehlalarm weit übertroffen. Der Fehler: Die 99 % gelten für die Kranken, nicht für die Positiven.","prueffrage":"Wie viele Menschen testen unter einer Million positiv, die gesund sind, im Vergleich zu denen, die wirklich krank sind?","rueckmeldung":[{"option":0,"text":"Die 99 % stimmen, aber sie beschreiben, wie viele Kranke der Test findet, nicht wie viele Positive krank sind. Da die Gesunden in der Überzahl sind, stammen die meisten positiven Ergebnisse von Gesunden."},{"option":1,"text":"Beide Gruppen werden zwar gleich zuverlässig erkannt, aber sie sind sehr verschieden groß. Ein Prozent von rund einer Million Gesunden sind etwa 9.999 Fehlalarme, ein Prozent Fehler bei 100 Kranken fast keiner. Gleiche Quoten heißen also nicht gleich viele Fälle."},{"option":3,"text":"Die niedrige Ausgangslage von 1 zu 10.000 ist wichtig, aber sie ist nur der Startpunkt. Ein positives Ergebnis ist ein Befund, der die Wahrscheinlichkeit deutlich anhebt, hier auf knapp 1 zu 100. Wer ihn ignoriert, unterschätzt das Risiko um das Hundertfache."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Gigerenzer, G. u. a. (2007): Helping Doctors and Patients Make Sense of Health Statistics. Psychological Science in the Public Interest 8(2), 53–96","oeffentlich":true,"doi":"10.1111/j.1539-6053.2008.00033.x","url":"https://kops.uni-konstanz.de/entities/publication/1c820f2d-aeed-4bfd-b65b-0e3f86803750/full","abruf":"2026-10-12"},{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"0bb818433c6751d2"}},{"id":"qa-6","status":"entwurf","clusterId":"A","werkstueckRef":"A.8","stufe":2,"question":"Eine Stadtverwaltung will die Zahl der Tauben in der Innenstadt senken und zahlt 2 Euro für jede abgelieferte tote Taube. In den ersten Wochen werden Hunderte Tauben abgegeben. Dann stellt die Verwaltung fest, dass einzelne Bürger Tauben extra züchten, und stoppt das Programm. Welches der folgenden Beispiele zeigt dasselbe Muster eines Fehlanreizes?","options":["Eine Regierung zahlte Geld für jede abgelieferte tote Kobra; manche Bürger begannen, Kobras zu züchten, und setzten die Tiere frei, als das Programm endete.","Eine Regierung zahlte Geld für jede abgelieferte tote Kobra; die Zahl der Schlangen sank, dafür vermehrten sich die Nagetiere, die sie bisher gejagt hatten.","Eine Regierung verteilte kostenlose Schutzstiefel gegen Schlangenbisse; die Zahl der Bisse sank, doch manche Menschen gingen mehr Risiken ein.","Eine Regierung zahlte Geld für jede abgelieferte tote Ratte; die Zahl der Ratten sank zunächst, stieg aber wieder, weil die Nachbarregion kein Programm hatte."],"correctIndex":0,"explanation":"Der Taubenfall zeigt eine Kette: Die Prämie soll den Bestand senken, lockt aber dazu, Tiere eigens zu züchten, und nach dem Programmstopp bleibt die Frage, was mit den nun wertlosen Tieren geschieht. Genau diese Abfolge zeigt die bekannte Kobra-Lehrgeschichte aus dem kolonialen Indien: Kopfgeld, Zucht, Programmende, Freilassung, am Ende mehr Tiere als vorher. Im Tauben- wie im Kobrafall vergrößert der Fehlanreiz das Problem selbst: Eine Belohnung für das Messbare (abgelieferte Tiere) untergräbt das Ziel (weniger Tiere). Sinkende Schlangenzahlen mit mehr Nagetieren klingen nach einer Prämie mit Folgen, sind aber eine ökologische Nebenwirkung, bei der niemand die Prämie ausnutzt. Kostenlose Schutzstiefel mit mehr Risikobereitschaft klingen nach einem Fehlschlag der Maßnahme, beruhen aber auf einem anderen Mechanismus und haben nichts mit Belohnungen für abgelieferte Tiere zu tun. Eine Rattenprämie, die wirkt und nur in der Nachbarregion verpufft, klingt nach einem ähnlichen Rückschlag, lässt aber keine neuen Tiere entstehen. Hinweis zur Sachlage: Das bekannte Lehrbeispiel mit den Kobras im kolonialen Indien ist historisch nicht belegt (die Friends of Snakes Society fand 2025 keine zeitgenössischen Belege für Kobra-Zuchtbetriebe), der Mechanismus selbst aber ist real und an anderen Fällen dokumentiert.","coreRule":"⚡ Denke in höheren Ordnungen: Frage immer „Und was dann? Und wie reagiert das System?“","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück A.8, Fußnote ga-kobra (Kobra-Effekt, Mechanismus real, Anekdote historisch dünn); Anmerkung anm-ga-kobra","kurz":"Entscheidend ist, dass die Prämie selbst dazu verleitet, das Problem herzustellen: Wer für abgelieferte Tiere zahlt, belohnt Zucht. Tauben und Kobras zeigen dieselbe Kette aus Prämie, Zucht, Programmende und mehr Tieren als zuvor.","prueffrage":"Woher stammen die Tiere, für die bezahlt wird, und gab es sie alle schon vor der Prämie?","rueckmeldung":[{"option":1,"text":"Hier wirkt die Prämie sogar: Die Schlangen werden weniger, und die Nagetiere nehmen als ökologische Nebenwirkung zu. Niemand nutzt die Belohnung aus, es entstehen auch keine zusätzlichen Schlangen. Das ist ein anderes Muster als im Taubenfall."},{"option":2,"text":"Mehr Risikobereitschaft trotz Schutzstiefeln ist ein bekannter Verhaltenseffekt von Schutzmaßnahmen. Es gibt aber keine Belohnung für abgelieferte Tiere und niemanden, der das Problem selbst herstellt. Der Mechanismus ist ein anderer."},{"option":3,"text":"Auch hier verpufft das Programm teilweise, aber von außen: Aus der Nachbarregion kommen Ratten nach. Niemand nutzt die Prämie aus, um neue Tiere zu erzeugen. Im Taubenfall entsteht das Problem dagegen durch die Prämie selbst."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Friends of Snakes Society (2025, aktualisiert 16.09.2026): The Cobra Effect: Colonial Misinformation Masquerading as Economic Theory","oeffentlich":true,"url":"https://friendsofsnakes.org.in/cobra-effect/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, M. J.: Interview mit Michael G. Vann zur Rattenjagd in Hanoi 1902. World History Connected 15.2","oeffentlich":true,"url":"https://worldhistoryconnected.press.uillinois.edu/15.2/vann_interview.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Siebert, H. (2001): Der Kobra-Effekt","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3960336d29a8f958"}},{"id":"qa-7","status":"entwurf","clusterId":"A","werkstueckRef":"A.10","stufe":2,"question":"Wie reagierst du am besten, bevor du einen Einwand gegen Saras Vorschlag vorbringst?","options":["Du fasst Saras Vorschlag in seiner überzeugendsten Form zusammen, lässt dir bestätigen, dass du ihn richtig erfasst hast, und nennst erst dann deinen Einwand.","Du sammelst Zahlen von Betrieben mit Vier-Tage-Woche, wertest sie aus und nennst erst danach deinen Einwand, gestützt auf die Daten aus diesen Betrieben.","Du sagst, dass Toms Zuspitzung unfair war, nennst deinen Einwand gegen die Vier-Tage-Woche und lädst Sara ein, darauf zu antworten.","Du nennst zuerst deinen Einwand gegen die Vier-Tage-Woche und fasst danach Saras Vorschlag knapp zusammen, damit klar wird, worauf er zielt."],"correctIndex":0,"explanation":"Wer eine Gegenposition erst in ihrer stärksten und plausibelsten Form wiedergibt und sich bestätigen lässt, dass er sie richtig verstanden hat, schafft zwei Vorteile. Erstens zwingt es ihn, die Position wirklich zu verstehen, statt gegen eine Vermutung zu argumentieren. Zweitens zählt der Einwand mehr: Wer die stärkste Version einer Idee widerlegt, hat sie wirklich widerlegt, wer nur eine Karikatur besiegt, hat nichts erreicht. Dazu kommt, dass sich ein verstandener Gegner eher auf Kritik einlässt als jemand, der sich verzerrt dargestellt fühlt. Toms Antwort ist das Gegenbeispiel: Er greift eine abwertende Verkürzung an, nicht Saras tatsächliches Anliegen.","coreRule":"⚡ Erst die Gegenposition so stark und fair wiedergeben, dass der andere zustimmt – dann kritisieren.","quote":"","quoteLabel":"","scenario":"In der Teamsitzung schlägt Sara vor, die Vier-Tage-Woche einzuführen. Du hältst das für falsch. Tom antwortet sofort: „Ihr wollt also einfach weniger arbeiten und trotzdem volles Gehalt kassieren?“ Du willst es besser machen als Tom und deinen Einwand wirksam vorbringen.","beleg":"Werkstück A.10, Kernidee und Rapoports Regeln (Fußnote ga-rapoport), Abschnitt „Kontext & Tiefe“","kurz":"Wer Saras Vorschlag zuerst in seiner stärksten Form wiedergibt und sich bestätigen lässt, versteht ihn wirklich und widerlegt keine Karikatur. Toms Fehler: Er griff eine abwertende Verkürzung an, nicht Saras tatsächliches Anliegen.","prueffrage":"Was genau hat Sara vorgeschlagen, und was davon ist in Toms Antwort noch zu erkennen?","rueckmeldung":[{"option":1,"text":"Zahlen können einen Einwand später stützen und wirken gründlich. Sie prüfen aber die Sache, nicht ob du Saras Vorschlag richtig erfasst hast, und Sara hat noch nichts bestätigt."},{"option":2,"text":"Toms Zuspitzung war tatsächlich unfair, und das anzusprechen wirkt anständig. Es zeigt aber nur deinen guten Willen, nicht dass du Saras Anliegen erfasst hast, und dein Einwand käme ohne ihre Bestätigung."},{"option":3,"text":"Eine kurze Zusammenfassung ist hilfreich, doch hier kommt sie zu spät. Du widersprichst, bevor Sara bestätigt hat, dass du ihren Vorschlag richtig erfasst hast, und lässt sie so mit deinem Einwand allein."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rapoport, A. (1960): Fights, Games, and Debates","oeffentlich":false},{"typ":"literatur","kurz":"Dennett, D. C. (2013): Intuition Pumps and Other Tools for Thinking","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"be980aae37bcaf96"}},{"id":"qa-8","status":"entwurf","clusterId":"A","werkstueckRef":"A.14","stufe":1,"question":"Welche Frage hilft dir am besten, die Entscheidung über die Mitgliedschaft nüchtern zu treffen?","scenario":"Seit drei Jahren zahlst du 50 € im Monat für ein Fitnessstudio, warst aber seit einem Jahr kein einziges Mal mehr dort. Beim Blick auf den Kontoauszug denkst du: „Ich habe schon so viel Geld hineingesteckt, jetzt kann ich nicht einfach kündigen.“ Eine Freundin sagt: „Dann mach doch einen Realitätscheck.“","options":["„Würde ich die Mitgliedschaft heute, mit allem, was ich jetzt weiß, noch einmal abschließen?“","„Wie viele Besuche müsste ich noch schaffen, damit sich meine bisherigen 1.800 Euro rechnerisch lohnen?“","„Was habe ich beim Abschluss vor drei Jahren falsch eingeschätzt, und wie vermeide ich das künftig?“","„Wie hoch liegen meine Kosten pro Besuch, wenn ich alle bisherigen Zahlungen auf meine Besuche umlege?“"],"correctIndex":0,"explanation":"Die bisher gezahlten 1.800 Euro sind weg, egal ob du kündigst oder weitermachst. Sie dürfen deshalb nicht in die Entscheidung einfließen. Entscheidend ist nur, was ab jetzt zu erwarten ist: Kosten und Nutzen der kommenden Monate. Die Probe dafür ist ein gedanklicher Neustart: Würdest du heute, ohne Vorgeschichte, mit deinem jetzigen Wissen einen Vertrag über 50 Euro im Monat unterschreiben? Lautet die Antwort „Nein“, ist das ein starkes Signal, nur aus Trägheit und wegen versunkener Kosten festzuhalten.","coreRule":"⚡ Ignoriere versunkene Kosten: Frag dich, ob du heute neu damit anfangen würdest. Wenn nicht, beende es.","quote":"Unabhängig von dem, was ich bisher investiert habe: Wenn ich nicht schon dabei wäre, würde ich heute damit anfangen?","quoteLabel":"Prüffrage:","beleg":"Werkstück A.14, Kernidee und Aktivierungs-Frage (Null-Basis-Check); Bezug zur Versunkene-Kosten-Falle (B.6). Keine Fußnoten.","kurz":"Die 1.800 Euro sind weg, egal was du tust. Entscheidend ist, ob du den Vertrag heute noch einmal abschließen würdest. Der Fehler ist, Geld, das nicht zurückkommt, in die Entscheidung einzurechnen.","prueffrage":"Welche Zahlungen und welchen Nutzen kannst du mit deiner Entscheidung heute überhaupt noch verändern?","rueckmeldung":[{"option":1,"text":"Die Frage klingt nach vorn gerichtet, weil es um künftige Besuche geht. Als Maßstab dient aber der Betrag von 1.800 Euro, den du nicht zurückbekommst, also bestimmt das Vergangene weiter, wie du das Künftige bewertest."},{"option":2,"text":"Die Frage nach dem Fehler beim Abschluss kann dir bei künftigen Verträgen wirklich helfen. Über die jetzige Mitgliedschaft entscheidet sie aber nicht, denn dafür zählt nur, was die kommenden Monate kosten und bringen."},{"option":3,"text":"Kosten pro Besuch ergeben eine konkrete, scheinbar nüchterne Zahl. Sie verteilt aber nur das schon Bezahlte auf deine Besuche und sagt nichts darüber, ob sich die nächsten Monate für dich lohnen."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124–125","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"452f9bbb383180f8"}},{"id":"qa-9","status":"entwurf","clusterId":"A","werkstueckRef":"A.24","stufe":4,"question":"Welche Schlussfolgerung ist aus dieser Lage gerechtfertigt – und welche nicht?","options":["Die wahre Erfolgsquote liegt vermutlich zwischen beiden Werten, denn offenbar haben beide Quellen ihre eigenen Lücken.","Die zwölf Medikamente wirken offenbar kaum, denn nur gut die Hälfte der angemeldeten Studien ging überhaupt positiv aus.","Viele gedruckte Studien enthalten vermutlich gefälschte Daten, denn sonst lägen 94 % und 51 % kaum so weit auseinander.","Die gedruckte Literatur zeichnet ein verzerrtes Bild, denn offenbar wurden vor allem die positiven Studien veröffentlicht."],"correctIndex":3,"explanation":"Die Lücke zwischen 94 % und 51 % entsteht durch Auswahl: Die FDA-Akten erfassten jede Studie schon vor Beginn, ob sie später gedruckt wurde oder nicht. In der Literatur fehlten dagegen die negativen Studien: Von den 36 negativen oder fragwürdigen waren 22 nie erschienen, und 11 weitere waren so umgeschrieben worden, dass sie dort als Erfolge dastanden. Das Umschreiben ist eine Verzerrung der Darstellung, kein Beleg für gefälschte Daten. Auch sonst mussten die einzelnen Studien nicht gefälscht sein: Jede konnte eine saubere Kontrollgruppe, eine korrekte Verblindung und eine ordentliche Statistik haben. Der Fehler liegt im Überlebendenverzeichnis, nicht in der einzelnen Studie. Wer nur las, was gedruckt war, überschätzte die Wirkung der Medikamente um rund ein Drittel.","coreRule":"⚡ Was wurde nicht veröffentlicht? Wer nur das Gedruckte liest, sieht eine ausgewählte Stichprobe. Frag nach dem Studienregister: Wie viele angemeldete Studien erschienen nie?","quote":"Die Täuschung lag nicht in den Studien. Sie lag in der Schublade, in der die anderen verschwunden waren.","quoteLabel":"Publikationsbias","scenario":"Ein Forscher vergleicht zwei Bilder desselben Gegenstands. Bild 1: die veröffentlichte Fachliteratur zu zwölf Antidepressiva. Dort melden 94 % der Studien einen Erfolg. Bild 2: die Akten der Arzneimittelbehörde FDA, bei der jede Studie vor Beginn angemeldet werden musste, ob sie später gedruckt wurde oder nicht. Dort stehen 74 Studien, von denen nur 51 % positiv ausgingen.","beleg":"Werkstück A.24, Abschnitt „Die Schublade“ (Zitat), Fußnote ga-publikationsbias (Turner et al. 2008, NEJM 358(3): 74 FDA-Studien, 94 % vs. 51 % positiv, Überschätzung um ca. 32 %)","kurz":"Der Abstand von 94 % zu 51 % entsteht durch Auswahl: Die FDA-Akten erfassen jede angemeldete Studie, in der Literatur fehlen viele negative. Wer nur das Gedruckte liest, sieht ein geschöntes Bild, ohne dass einzelne Studien fehlerhaft sein müssen.","prueffrage":"Was unterscheidet die Studien in den Behördenakten von denen in den Fachzeitschriften, abgesehen vom Ergebnis?","rueckmeldung":[{"option":0,"text":"Ein Wert dazwischen klingt nach fairem Ausgleich. Die FDA-Akten haben aber keine Lücke, weil jede Studie vorab angemeldet war; nur die Literatur ist selektiv. Der FDA-Wert ist daher die belastbare Grundlage."},{"option":1,"text":"Dass nur etwa die Hälfte der angemeldeten Studien positiv ausging, stimmt. Daraus folgt aber kein Fehlen der Wirkung: Der Befund zeigt, dass die Wirkung in der Literatur überschätzt wurde, nicht dass sie null ist."},{"option":2,"text":"Eine große Lücke wirkt, als müsse getrickst worden sein. Fälschung ist aber nicht belegt: Negative Studien blieben ungedruckt oder wurden umgedeutet, und die einzelnen Studien konnten sauber sein. Der Fehler liegt in der Auswahl."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Turner, E. H.; Matthews, A. M.; Linardatos, E.; Tell, R. A.; Rosenthal, R. (2008): Selective Publication of Antidepressant Trials and Its Influence on Apparent Efficacy. NEJM 358(3), 252–260 (Abstract)","oeffentlich":true,"doi":"10.1056/NEJMsa065779","url":"https://pubmed.ncbi.nlm.nih.gov/18199864/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rosenthal, R. (1979): The File Drawer Problem and Tolerance for Null Results. Psychological Bulletin 86(3), 638–641","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5eab6907db4f7ebe"}},{"id":"qa-10","status":"entwurf","clusterId":"A","werkstueckRef":"Anhang VII.2","stufe":2,"question":"Ein Sprachmodell liefert dir zu deiner Hypothese eine Studie mit Autor, Jahr und Zeitschrift, die sie scheinbar bestätigt. Was musst du tun, bevor daraus ein Beleg wird?","options":["Du hältst die Angabe für einen Beleg, sobald Autor, Jahr und Zeitschrift plausibel klingen, denn erfundene Quellen wären auffällig.","Du fragst dasselbe Modell noch einmal und wertest die Studie als bestätigt, wenn es sie ein zweites Mal nennt.","Du öffnest die Quelle außerhalb der KI, prüfst DOI oder Fundstelle und liest die Kernaussage im Original.","Du prüfst nur, ob die Zeitschrift existiert, und verlässt dich darauf, dass das Modell den Inhalt zuverlässig zusammenfasst."],"correctIndex":2,"explanation":"Was ein Sprachmodell liefert, ist eine Liste von Kandidaten, keine Quelle. Fünf Fehlerarten treten regelmäßig auf: Die Quelle existiert nicht; sie sagt etwas anderes; sie ist überholt; die Zusammenfassung verdreht das Ergebnis; das Modell stimmt dir zu, weil du ihm deine Hypothese verraten hast. Plausibel klingende Angaben und eine wiederholte Antwort desselben Modells prüfen nichts, denn beides stammt aus derselben Quelle, die du gerade überprüfen willst. Dass eine Zeitschrift existiert, sagt noch nichts darüber, ob der genannte Aufsatz darin steht oder das behauptet, was das Modell ihm zuschreibt. Ein Beispiel: Im Fall Mata v. Avianca (New York, 2023) belegte ChatGPT einen Schriftsatz mit sechs frei erfundenen Gerichtsurteilen; das Gericht verhängte Sanktionen.","coreRule":"⚡ KI-Ergebnis ≠ Beleg: außerhalb der KI öffnen, Fundstelle prüfen, Kernaussage im Original lesen.","quote":"","quoteLabel":"","kurz":"Was das Modell nennt, ist nur ein Kandidat. Erst das Original zeigt, ob die Studie existiert und das aussagt, was behauptet wird. Plausible Angaben oder eine wiederholte Antwort desselben Modells prüfen nichts, denn sie kommen aus derselben Quelle.","prueffrage":"Was wüsstest du über diese Studie, wenn dir niemand außer dieser einen Quelle davon erzählt hätte?","rueckmeldung":[{"option":0,"text":"Autor, Jahr und Zeitschrift wirken wie die Bestandteile einer echten Quelle. Genau solche Angaben erzeugt ein Sprachmodell aber auch frei, etwa die erfundenen Urteile im Fall Mata v. Avianca. Plausibel zu klingen, belegt nichts."},{"option":1,"text":"Eine zweite Nennung derselben Studie fühlt sich wie Bestätigung an. Beide Antworten stammen aber aus derselben Quelle, die du gerade überprüfen willst. Eine Wiederholung ist deshalb keine unabhängige Prüfung."},{"option":3,"text":"Dass die Zeitschrift existiert, ist ein sinnvoller erster Schritt. Er sagt aber nichts darüber, ob der Aufsatz dort steht oder das aussagt, was das Modell behauptet. Auch eine Zusammenfassung kann das Ergebnis verdrehen."}],"familie":"ki-ausgabe-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Mata v. Avianca, Inc., No. 22-cv-1461 (PKC), S.D.N.Y.: Opinion and Order on Sanctions, 22.06.2023 (ECF 54), Richter P. Kevin Castel","oeffentlich":true,"url":"https://storage.courtlistener.com/recap/gov.uscourts.nysd.575368/gov.uscourts.nysd.575368.54.0.pdf","seite":"S. 1","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Mata v. Avianca, Inc., 678 F. Supp. 3d 443 (S.D.N.Y. 2023)","oeffentlich":false,"seite":"S. 456, 466 (laut Belegregister)"}],"thema":"Technik und KI"},{"id":"qb-1","status":"entwurf","clusterId":"B","werkstueckRef":"B.1","stufe":1,"question":"Ein Kollege ist überzeugt, dass die neue Mitarbeiterin schlampig arbeitet. Hat sie ein Detail richtig gemacht, sagt er: „Zufall.“ Unterläuft ihr ein Fehler, sagt er: „Ich wusste es.“ Welche Frage zeigt am besten, ob sein Urteil auf einer fairen Prüfung beruht?","options":["Welche Beobachtung würde ihn dazu bringen, sein Urteil aufzugeben, und hat er auch nach solchen gesucht?","Hat er die drei Fehler selbst gesehen oder nur davon gehört, und stammt sein Wissen aus erster Hand?","Konkurriert er mit der Mitarbeiterin um eine Beförderung, sodass ihm ein schlechtes Bild von ihr nützt?","Sieht seine Vorgesetzte die drei Fehler ebenso, und teilt sie sein Urteil über die Mitarbeiterin?"],"correctIndex":0,"explanation":"Hier wird nicht geprüft, sondern gesammelt: Der Kollege sucht und deutet einseitig, denn Fehler gelten als Beweis, Treffer als Zufall. Das ist genau der Bestätigungsfehler. Die wirksame Gegenfrage lautet: Was wäre der stärkste Beweis gegen meine Position? Dass er Treffer als Zufall abtut und nur Fehler zählt, zeigt die einseitige Auswahl; die bloße Zahl der Fehler belegt daher nichts. Wer jede Beobachtung zur eigenen Vermutung passend deutet, bestätigt sich selbst, ohne etwas zu testen.","coreRule":"Wer nur nach Bestätigung sucht, findet sie immer. Frag dich: Was würde meine Annahme widerlegen, und habe ich danach gesucht?","quote":"","quoteLabel":"","scenario":"Schon in der ersten Woche hat er einen kleinen Tippfehler von ihr bemerkt und sich daraufhin festgelegt: Sie arbeitet schlampig. Seitdem achtet er genau auf ihre Fehler. Ihre korrekt erledigten Aufgaben kommentiert er höchstens mit „Glück gehabt“. Auf Nachfrage nennt er drei Fehler als Beweis.","beleg":"Werkstück B.1, Fußnote gl-b-nickerson (Nickerson 1998, S. 175 f., 178, 211): einseitiges Suchen und Deuten von Belegen zugunsten der vorliegenden Hypothese; Menschen suchen von sich aus kaum nach Widerlegung.","kurz":"Entscheidend ist, ob sein Urteil überhaupt widerlegbar wäre. Er wertet Fehler als Beweis und Treffer als Zufall, deshalb kann ihm nichts widersprechen. Das ist der Bestätigungsfehler: Die Fehlerzahl allein belegt nichts.","prueffrage":"Wie viele ihrer Aufgaben hat sie fehlerfrei erledigt, und wie hat er diese bewertet?","rueckmeldung":[{"option":1,"text":"Nach der Herkunft von Wissen zu fragen, ist grundsätzlich sinnvoll. Hier führt es aber nicht weiter: Selbst wenn er alle Fehler selbst gesehen hat, bleibt offen, warum er nur sie zählt und Treffer als Zufall abtut."},{"option":2,"text":"Ein Eigeninteresse kann Urteile färben, davon steht im Szenario aber nichts. Und selbst dann bliebe entscheidend, wie er mit Belegen umgeht: ob er nur Fehler zählt und Treffer wegdeutet."},{"option":3,"text":"Eine zweite Sicht wirkt wie eine Gegenprobe, doch ihre Zustimmung oder ihr Widerspruch zeigt nicht, ob seine eigene Prüfung fair war. Das Problem liegt darin, wie er Beobachtungen auswählt und deutet."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson (1998), Verlagsfassung APA","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1f24cb99f1ce8721"}},{"id":"qb-2","status":"entwurf","clusterId":"B","werkstueckRef":"B.2","stufe":1,"question":"Welche Erklärung passt am besten zu Marias Verhalten?","options":["Nach drei Wochen hat sie sich auf eine Meinung festgelegt und blendet Widerspruch lieber aus, deshalb wischt sie die Einwände ihres Onkels einfach beiseite.","Nach drei Wochen Videos fehlt ihr das Wissen, um zu erkennen, wie viel sie noch nicht weiß, deshalb wirkt ihr Urteil auf sie überzeugender, als es ist.","Sie traut frisch erworbenem Wissen mehr als langer Berufserfahrung, deshalb hält sie die Strategie ihres Onkels nach 30 Jahren für veraltet.","Sie hat das Wesentliche verstanden und scheitert nur an den Fachbegriffen ihres Onkels, deshalb wirken seine Einwände auf sie unnötig kompliziert."],"correctIndex":1,"explanation":"Was Maria vor allem auszeichnet, ist eine Selbstsicherheit, die ihrem Wissensstand weit vorauseilt. Die Fähigkeiten, die man braucht, um in einem Bereich gut zu sein, sind dieselben, die man braucht, um die eigene Leistung dort einzuschätzen. Wer ein Feld nur oberflächlich kennt, sieht dessen Komplexität nicht und hält seine einfachen Antworten deshalb für ausreichend. Ein extremes Beispiel ist der Bankräuber McArthur Wheeler (1995), der sein Gesicht mit Zitronensaft einrieb, weil er glaubte, das mache ihn für Kameras unsichtbar, und der vom Fehlschlag völlig überrascht war. Zugleich gilt: Aus dem Verhalten allein lässt sich nicht beweisen, dass dieser Mechanismus wirkt. Wie viel davon echte Blindheit für die eigene Inkompetenz ist und wie viel ein statistischer Effekt, ist in der Forschung umstritten.","coreRule":"⚡ Die doppelte Bürde: Wer in einem Feld wenig kann, dem fehlt oft auch das Rüstzeug, die eigene Schwäche zu erkennen. Misstrauen ist angebracht, wenn Gewissheit schnell wächst und Expertenwissen als „unnötig kompliziert“ abgetan wird.","quote":"","quoteLabel":"","scenario":"Maria hat drei Wochen lang Videos über Börsenhandel gesehen. Sie ist überzeugt, den Markt zu durchschauen, und rät ihrem Onkel, der seit 30 Jahren als Vermögensberater arbeitet, seine Strategie sei „völlig veraltet“. Seine Einwände wischt sie als „unnötig kompliziert“ weg. Mit seinen Einwänden kann sie nichts anfangen, weil sie die Fachbegriffe dahinter nicht kennt.","beleg":"Werkstück B.2 (Wheeler-Episode, Dunning-Kruger-Effekt, Hinweis zur Beleglage); Fn. gl-b-wheeler, gl-b-dunning","kurz":"Wer ein Feld erst oberflächlich kennt, sieht dessen Komplexität nicht und hält einfache Antworten für ausreichend. Maria fehlt das Wissen, die eigene Lücke zu erkennen. Ob das echte Blindheit ist oder zum Teil ein statistischer Effekt, ist umstritten.","prueffrage":"Wie lange befasst sich Maria schon mit Börsenhandel, wie lange ihr Onkel, und wie sicher tritt jeder von beiden auf?","rueckmeldung":[{"option":0,"text":"Dass Maria Einwände wegwischt, stimmt, und es sieht nach Sturheit aus. Das Szenario zeigt aber nur das Verhalten, keinen Willen zur Verdrängung. Näher liegt, dass sie die Einwände mangels Wissen gar nicht als bedeutsam erkennt."},{"option":2,"text":"Maria stellt tatsächlich ihr frisches Wissen über seine Erfahrung. Das beschreibt aber nur das Ergebnis. Dass sie Erfahrung grundsätzlich gering schätzt, steht nirgends; ihr fehlt eher der Blick dafür, wie viel hinter seiner Strategie steckt."},{"option":3,"text":"Dass sie seine Einwände nicht einordnen kann, weil ihr die Begriffe fehlen, stimmt. Das ist aber kein bloßes Sprachproblem: Nach drei Wochen kennt sie das Feld nur an der Oberfläche, und die Fachbegriffe stehen für Zusammenhänge, die sie noch nicht sieht."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121","seite":"S. 1121"},{"typ":"doi","kurz":"Magnus, J. R.; Peresetsky, A. A. (2022): A Statistical Explanation of the Dunning–Kruger Effect. Frontiers in Psychology 13","oeffentlich":true,"doi":"10.3389/fpsyg.2022.840180","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"84616961f4af75d4"}},{"id":"qb-3","status":"entwurf","clusterId":"B","werkstueckRef":"B.6","stufe":1,"question":"Was ist an dieser Begründung fehlerhaft, und welche Frage würde die Entscheidung besser tragen?","options":["Der Fehler liegt darin, dass die 25 € ohnehin nicht zurückkommen, ob du bleibst oder gehst. Besser ist die Frage: „Was ist die beste Nutzung der nächsten 90 Minuten?“","Der Fehler liegt darin, dass du nur siehst, was du bezahlt hast, nicht, was dir entgangen ist. Besser ist die Frage: „Was hätten mir die 25 € anderswo gebracht?“","Der Fehler liegt darin, dass du die vollen 25 € anrechnest, obwohl zwanzig Minuten vorbei sind. Besser ist die Frage: „Wie viel von dem Geld entfällt noch auf den Rest?“","Der Fehler liegt darin, dass du nach dem Geld entscheidest statt nach deinem Gefühl. Besser ist die Frage: „Würde ich es später bereuen, wenn ich jetzt gehe?“"],"correctIndex":0,"explanation":"Die 25 € sind in dem Moment weg, in dem du bezahlst. Du bekommst sie nicht zurück, egal ob du den Film zu Ende siehst oder nicht. Das Geld darf deshalb die Entscheidung nicht lenken, nur die Zukunft zählt. Wer bleibt, verliert zusätzlich 90 Minuten Lebenszeit. Die Begründung „Ich habe doch schon so viel bezahlt“ ist ein Warnsignal für die Versunkene-Kosten-Falle: Sie bindet uns an eine Entscheidung, weil wir Geld und Mühe nicht als „verschwendet“ abschreiben wollen (Verlustaversion, Wunsch nach Konsistenz). Die gute Frage lautet: Was ist ab jetzt die beste Nutzung meiner Zeit? Nach Hause gehen und ein gutes Buch lesen ist dabei eine naheliegende Alternative.","coreRule":"⚡ Vergangene Kosten sind vergangen. Entscheide nur nach dem, was künftig Kosten und Nutzen bringt.","quote":"","quoteLabel":"","scenario":"Du sitzt im Kino. Du hast 15 € für die Karte und 10 € für Popcorn und Getränk bezahlt. Nach zwanzig Minuten ist klar: Der Film ist furchtbar. Du sagst dir: „Ich bleibe, schließlich habe ich 25 € für diesen Abend ausgegeben. Wenn ich jetzt gehe, war das Geld verschwendet.“","beleg":"Werkstück B.6, Fußnote gl-b-sunk-cost (Arkes/Blumer 1985, S. 124, 126): Kinofilm-Beispiel, Kernidee und Aktivierungsfrage der Versunkene-Kosten-Falle","kurz":"Die 25 € sind weg, ob du bleibst oder gehst; entscheidend ist nur, was ab jetzt aus deiner Zeit wird. Der Denkfehler besteht darin, Geld als Grund zum Bleiben zu zählen, das du ohnehin nicht zurückbekommst.","prueffrage":"Wie würdest du entscheiden, wenn dir eine Freundin Karte und Popcorn geschenkt hätte?","rueckmeldung":[{"option":1,"text":"Alternativen mitzudenken ist grundsätzlich klug. Hier blickt die Frage aber auf Geld zurück, das längst ausgegeben ist und nirgends mehr etwas brächte. Bei der Entscheidung zählt, was du mit den kommenden 90 Minuten anfangen kannst."},{"option":2,"text":"Dass zwanzig Minuten vorbei sind, stimmt, ändert aber nichts: Die 25 € sind mit dem Kauf vollständig ausgegeben, kein Teil davon wartet noch auf den Rest des Films. Das Aufteilen hält die Entscheidung am Vergangenen fest."},{"option":3,"text":"Gefühle wie Reue und der Wunsch, nichts „verschwendet“ zu haben, spielen tatsächlich mit hinein. Als Entscheidungsfrage hängt „Würde ich es bereuen?“ aber an demselben Geldgedanken und vergleicht nicht, was dir die nächste Zeit bringen kann."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1) (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124, 126","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost, Verlagsfassung","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b7184428435d4da1"}},{"id":"qb-4","status":"entwurf","clusterId":"B","werkstueckRef":"B.10","stufe":2,"question":"Welche Erklärung für die hohe Bewertung passt am besten zu diesem Befund?","options":["Die Auswertung kam von ihrer Dozentin, sodass die Studierenden dem Text vertrauten und ihn für zutreffend hielten, ohne ihn genauer zu prüfen.","Der Text stammte aus einem Astrologiebuch, dessen Beschreibungen offenbar doch treffende Aussagen über die Persönlichkeit enthalten.","Die Sätze sind so vage und schmeichelhaft, dass die meisten Menschen passende Beispiele aus ihrem Leben finden und sie auf sich beziehen.","Die Studierenden bilden eine recht ähnliche Gruppe, sodass ein Text, der auf einen von ihnen passt, auch auf die meisten anderen zutrifft."],"correctIndex":2,"explanation":"Alle bekamen denselben Text, also kann er nicht auf die einzelne Person zugeschnitten gewesen sein. Dass er trotzdem fast jeden überzeugt, liegt an seiner Bauweise: Die Aussagen sind allgemeingültig (fast jeder ist mal extrovertiert, mal introvertiert, fast jeder ist manchmal selbstkritisch), schmeicheln dem Selbstbild und enthalten nur kleine, verzeihliche „Schwächen“. Beim Lesen sucht das Gehirn gezielt nach Situationen, die zur Aussage passen, und übersieht die, die ihr widersprechen. Gruppendruck kann Urteile angleichen, doch davon ist nichts zu lesen, und jede Person bewertete die Treffsicherheit für sich. Psychologische Fachbegriffe könnten Vertrauen wecken, aber die zitierten Sätze sind Alltagssprache, die gerade deshalb auf alle zu passen scheint. Dass man sich nach einer Woche nicht mehr an die eigenen Antworten erinnert, klingt plausibel, erklärt aber nicht, warum ausgerechnet dieser allgemeine Text so hoch bewertet wird, denn er hätte auch bei bester Erinnerung auf fast jeden gepasst. Dieses Muster trägt einen Großteil von Horoskopen, Wahrsagerei und Cold Reading.","coreRule":"⚡ Der schmeichelhafte Spiegel: Wie viele Menschen kenne ich, auf die diese Aussage NICHT zutreffen würde?","quote":"Er hatte allen Studenten exakt denselben Text gegeben.","quoteLabel":"Merksatz:","scenario":"Eine Dozentin lässt ihre Studierenden einen Persönlichkeitstest ausfüllen und verteilt eine Woche später angeblich „individuell auf dich zugeschnittene“ Auswertungen. Darin stehen Sätze wie „Du hast ein großes Bedürfnis nach der Zuneigung und Bewunderung anderer“, „Du neigst dazu, dir selbst gegenüber kritisch zu sein“ und „Manchmal bist du extrovertiert und gesellig, zu anderen Zeiten introvertiert und zurückhaltend“. Die Studierenden bewerten die Treffsicherheit auf einer Skala von 0 bis 5 im Schnitt mit 4,26. Später stellt sich heraus: Alle hatten denselben Text bekommen, größtenteils aus einem Astrologiebuch vom Zeitungskiosk übernommen.","beleg":"Werkstück B.10, Fn. gl-b-forer: Forer (1949), Mittelwert 4,26 auf Skala 0–5; Erklärungsmerkmale (universell, schmeichelhaft, Bestätigungsfehler) im Haupttext.","kurz":"Alle bekamen denselben Text, also war nichts auf sie zugeschnitten. Er überzeugt, weil er vage und schmeichelhaft ist und man beim Lesen gezielt Situationen sucht, die passen, und die übersieht, die widersprechen.","prueffrage":"Würden die Studierenden den Text auch dann für passend halten, wenn sie ihn mit dem ihrer Sitznachbarn vergleichen?","rueckmeldung":[{"option":0,"text":"Eine Dozentin als Absenderin kann Vertrauen wecken, doch der Befund braucht das nicht. Derselbe Text hätte auch von einer unbekannten Quelle fast jeden überzeugt, weil seine Sätze auf fast alle Menschen passen."},{"option":1,"text":"Der Text trifft die Studierenden ja tatsächlich, daher liegt dieser Schluss nahe. Aber ein Text, der allen gleichermaßen passt, sagt nichts über den Einzelnen. Die Quelle liefert eher die allgemeingültigen Formulierungen, keine Belege für Treffsicherheit."},{"option":3,"text":"Eine ähnliche Gruppe würde das Ergebnis tatsächlich begünstigen, im Szenario steht dazu aber nichts. Entscheidend ist der Text: Seine Sätze passen auf fast jeden Menschen, auch in einer bunt gemischten Gruppe."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d79ef1e849591934"}},{"id":"qb-5","status":"entwurf","clusterId":"B","werkstueckRef":"B.15","stufe":3,"question":"Ein Analyst will entscheiden, wo Kampfflugzeuge zusätzlich gepanzert werden sollen. Er wertet dafür nur die Maschinen aus, die von ihren Einsätzen zurückgekehrt sind, und kartiert deren Einschusslöcher. Die meisten Treffer liegen an den Flügelspitzen, am Rumpf und am Heck, am Cockpit und an den Motoren findet er kaum welche. Welche Schlussfolgerung ist am besten begründet?","options":["Flügelspitzen, Rumpf und Heck sollten verstärkt werden, weil dort die meisten Einschüsse liegen und der Gegner dort am häufigsten trifft.","Cockpit und Motoren sollten verstärkt werden, weil Flugzeuge mit Treffern dort vermutlich nicht zurückgekehrt sind und in der Auswertung fehlen.","Zuerst sollten weitere zurückgekehrte Maschinen kartiert werden, weil erst mehr Daten zeigen, ob Cockpit und Motoren wirklich selten getroffen werden.","Auf zusätzliche Panzerung sollte verzichtet werden, weil die Maschinen trotz ihrer Einschüsse heil zurückkamen und Treffer offenbar meist überlebbar sind."],"correctIndex":1,"explanation":"Die Auswertung enthält nur Flugzeuge, die trotz ihrer Treffer zurückgekommen sind. Die sichtbaren Löcher zeigen also, wo ein Flugzeug getroffen werden kann und trotzdem überlebt. Maschinen, die an Cockpit oder Motoren getroffen wurden, sind vermutlich abgestürzt und fehlen in der Stichprobe. Die Stellen ohne Einschusslöcher sind deshalb die verdächtigen. Das ist ein klassischer Überlebensirrtum: Die Stichprobe wurde durch das Überleben vorgefiltert, und die fehlenden Daten wären für die Schlussfolgerung entscheidend. Am bekanntesten ist diese Überlegung vom Mathematiker Abraham Wald, der 1943 für die Statistical Research Group der Columbia University arbeitete. Die oft erzählte Dialogszene dazu ist allerdings zugespitzt, und eine ausdrückliche Panzerungsempfehlung ist in seinen Arbeiten nicht belegt.","coreRule":"⚡ Wo ist der unsichtbare Friedhof der Gescheiterten?","quote":"Die Toten können keine kritischen Blog-Posts schreiben.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück B.15 (Der Überlebensirrtum), Abschnitt „Anwendung & Relevanz“, Pseudomedizin; zur Wald-Szene Fußnote gl-b-wald: Mangel, M.; Samaniego, F. J. (1984): „Abraham Wald’s Work on Aircraft Survivability“. Journal of the American Statistical Association 79(386), S. 259–267","kurz":"Die Auswertung kennt nur Maschinen, die trotz ihrer Treffer zurückkamen. Löcher zeigen also, wo Treffer überlebbar sind; die „sauberen“ Stellen an Cockpit und Motoren sind verdächtig, weil dort getroffene Flugzeuge vermutlich fehlen.","prueffrage":"Woher stammen alle Flugzeuge, deren Einschusslöcher hier gezählt wurden, und was haben sie gemeinsam?","rueckmeldung":[{"option":0,"text":"Wo die meisten Löcher liegen, wirkt wie die Stelle der größten Gefahr. Die Löcher zeigen aber nur Treffer, die eine Maschine überstanden hat; Schutz brauchen eher die Stellen, an denen Treffer nicht überlebt wurden."},{"option":2,"text":"Mehr Daten klingen gründlich und helfen oft weiter. Hier aber wären auch weitere Heimkehrer bereits durch das Überleben vorsortiert; die Verzerrung bliebe, weil die abgestürzten Maschinen weiterhin fehlen."},{"option":3,"text":"Gewicht zu sparen ist ein berechtigtes Anliegen. Dass die Maschinen trotz Einschüssen heimkamen, sagt aber nur etwas über diese Maschinen: Wer abgestürzt ist, steht nicht in den Daten, daher folgt kein Urteil über die Überlebbarkeit von Treffern."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"fffee712641c23be"}},{"id":"qb-6","status":"entwurf","clusterId":"B","werkstueckRef":"B.19","stufe":2,"question":"Welche Rückfrage trifft den Kern des Problems in diesem Fall am besten?","options":["Wurde vorab festgelegt, dass genau diese beiden Werte untersucht werden, oder erst nach Blick auf alle Ergebnisse ausgewählt?","Wurde das Mittel an Menschen aus mehreren Ländern getestet, damit sich das Ergebnis auf die gesamte Bevölkerung übertragen lässt?","Wurden die Probanden zufällig der Gruppe mit dem Mittel zugeteilt, und wussten sie nicht, ob sie das Mittel oder ein Scheinmittel bekamen?","Wurden die Messwerte bei allen Probanden mit demselben Gerät und zur selben Tageszeit erhoben, damit sie vergleichbar sind?"],"correctIndex":0,"explanation":"In einer großen Datenmenge entstehen zwangsläufig zufällige Cluster. Zwei zufällige Treffer unter 50 gemessenen Werten sind deshalb noch kein Beweis. Entscheidend ist die Reihenfolge: Eine Hypothese, die vor der Datenerhebung feststand, wird durch einen Treffer gestützt. Wird sie erst nach dem Blick auf die Daten um die Treffer herum gebaut, ist das so, als würde man erst auf die Scheunenwand schießen und dann die Zielscheibe um die dichteste Stelle malen. Dazu kommt, dass die 48 Werte ohne Effekt verschwiegen werden. Ein solches Muster ist höchstens eine Vermutung, die an neuen, unabhängigen Daten geprüft werden muss. Die anderen Fragen sind für sich sinnvoll, treffen aber nicht den Kern: Mehrere Länder betreffen die Übertragbarkeit, nicht die Frage, ob die zwei Treffer echt sind. Zufällige Zuteilung und Verblindung sichern den Gruppenvergleich, ändern aber nichts daran, dass bei 50 Werten Zufallstreffer zu erwarten sind. Einheitliche Messbedingungen betreffen die Genauigkeit der Werte, nicht die nachträgliche Auswahl der Treffer.","coreRule":"⚡ Erst schießen, dann die Zielscheibe malen gilt nicht: Eine Hypothese muss vor den Daten feststehen, und ein im Nachhinein gefundenes Muster muss an neuen Daten bestätigt werden.","quote":"In jeder ausreichend großen und zufälligen Datenmenge entstehen zwangsläufig Cluster und scheinbar unwahrscheinliche Muster.","quoteLabel":"Merksatz:","scenario":"Ein Hersteller testet ein neues Nahrungsergänzungsmittel und misst bei den Probanden 50 verschiedene Gesundheitswerte. Bei 48 Werten zeigt sich kein Unterschied zur Vergleichsgruppe, bei zwei Werten gibt es eine kleine, „statistisch signifikante“ Verbesserung. In der Werbung heißt es: „Wissenschaftlich bewiesen: verbessert diese beiden Werte!“","kurz":"Zwei Treffer unter 50 Werten sind bei bloßem Zufall zu erwarten. Zählen würden sie nur, wenn sie vorab als Ziel feststanden; wer die Zielscheibe erst nach dem Schuss um die Treffer malt, belegt nichts.","prueffrage":"Wie viele der 50 Werte zeigten keinen Unterschied, und kommt das in der Werbung vor?","rueckmeldung":[{"option":1,"text":"Eine breite Probandengruppe erleichtert es, Ergebnisse zu übertragen, falls sie echt sind. Ob die zwei Verbesserungen überhaupt echt sind oder bei 50 Werten zufällig auftraten, klärt das aber nicht."},{"option":2,"text":"Zufällige Zuteilung und Verblindung machen den Gruppenvergleich fairer, das ist eine gute Frage an jede Studie. Dass bei 50 gemessenen Werten ein paar Zufallstreffer zu erwarten sind, ändern sie jedoch nicht."},{"option":3,"text":"Einheitliche Messbedingungen sorgen dafür, dass die Werte genau und vergleichbar sind. Auch perfekt gemessene Werte liefern bei 50 Versuchen aber ein paar zufällige Treffer, und wie die beiden Treffer ausgewählt wurden, bleibt offen."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR Recommendations and Reports 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 21–22","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kerr, N. L. (1998): HARKing: Hypothesizing After the Results are Known. Personality and Social Psychology Review 2(3), 196–217","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6fade719aaca6129"}},{"id":"qb-7","status":"entwurf","clusterId":"B","werkstueckRef":"B.28","stufe":2,"question":"Zwei Anleger haben jeweils 10.000 € in eine Aktie gesteckt. Am Abend ist Toms Aktie um 500 € gestiegen, Marias um 500 € gefallen. Tom klappt zufrieden den Laptop zu. Maria kann an nichts anderes mehr denken, liest fieberhaft Nachrichten und erwägt, alles zu verkaufen. Was erklärt den Unterschied in der Reaktion am sparsamsten?","options":["Maria gewichtet ihren Verlust von 500 € gegenüber dem Stand vom Morgen stärker als Tom seinen gleich hohen Gewinn (Verlustaversion); sie reagiert deshalb heftiger.","Maria ist von ihrem Wesen her ängstlicher als Tom (Persönlichkeitsunterschied); eine Kursbewegung von 500 € beunruhigt sie deshalb weit stärker als ihn.","Maria hängt an ihrer Aktie, weil sie ihr gehört (Besitztumseffekt); ein Wertverlust von 500 € trifft sie deshalb härter, als Tom sein gleich hoher Gewinn ihn erfreut.","Maria sucht beim fieberhaften Nachrichtenlesen nach Bestätigung für ihre Sorge (Bestätigungsfehler); sie steigert sich deshalb viel stärker hinein als Tom."],"correctIndex":0,"explanation":"Menschen bewerten Veränderungen nicht nach dem absoluten Endstand, sondern relativ zu einem Bezugspunkt, hier dem Stand vom Morgen. Von dort aus wiegt ein Verlust meist schwerer als ein gleich hoher Gewinn. Diese Verlustaversion wurde von Kahneman und Tversky beschrieben. In der klassischen Messung von 1992 wog ein Verlust rund doppelt so schwer, neuere Auswertungen finden je nach Methode ähnliche bis deutlich schwächere Werte; das „doppelt“ ist also eine Faustregel, kein Naturgesetz. Dass Marias Reaktion heftiger ausfällt als Toms, lässt sich damit gut erklären. Der Besitztumseffekt gilt für beide Anleger gleichermaßen und erklärt daher nicht, warum sie verschieden reagieren. Wer die Verlustaversion kennt, kann Marias Impuls prüfen: Sie sollte nicht verkaufen, nur um den Schmerz zu vermeiden, sondern fragen, ob sie die Aktie heute noch kaufen würde (Clean-Slate-Test).","coreRule":"⚡ Verluste wiegen vom Bezugspunkt aus meist schwerer als gleich hohe Gewinne. Prüfe deshalb, ob du entscheidest, um einen Verlust zu vermeiden, oder weil die Sache gut ist.","quote":"","quoteLabel":"","scenario":"Der Betrag der Veränderung ist in beiden Fällen identisch: 500 €. Trotzdem fällt die emotionale Reaktion sehr unterschiedlich aus.","beleg":"Werkstück B.28, Fußnote gl-b-verlust: Tversky, A.; Kahneman, D. (1992): „Advances in Prospect Theory: Cumulative Representation of Uncertainty“. Journal of Risk and Uncertainty 5(4), S. 297–323.","kurz":"Beide erleben denselben Betrag, aber jeweils relativ zum Stand vom Morgen, und von dort wiegt ein Verlust meist schwerer als ein gleich hoher Gewinn. Der naheliegende Fehler ist, nach Eigenheiten der Person zu suchen, obwohl der Unterschied schon in der Bewertung liegt.","prueffrage":"Wenn beide dieselben 500 € bewegen: Woran misst jeder von beiden, ob der Tag gut oder schlecht war?","rueckmeldung":[{"option":1,"text":"Ein ängstlicheres Wesen ist denkbar, aber über Marias Persönlichkeit steht nichts im Szenario. Es braucht diese zusätzliche Annahme nicht, wenn sich der Unterschied schon aus dem Vorzeichen der Veränderung ergibt."},{"option":2,"text":"Der Besitztumseffekt ist real. Er gilt aber für Tom genauso: Auch ihm gehört seine Aktie. Was für beide gleichermaßen gilt, kann nicht erklären, warum sie so verschieden reagieren."},{"option":3,"text":"Beim fieberhaften Lesen kann ein Bestätigungsfehler die Sorge sicher verstärken. Die Sorge muss aber schon da sein, damit er greift. Er setzt voraus, was erst erklärt werden soll: warum der Verlust Maria so stark umtreibt."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv; Zeitschriftenfassung JEL 62(2), 485–516)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1992): Advances in Prospect Theory: Cumulative Representation of Uncertainty. Journal of Risk and Uncertainty 5(4), 297–323","oeffentlich":false,"doi":"10.1007/BF00122574"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5ffe6e2f1defb176"}},{"id":"qc-1","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.2","stufe":1,"question":"Ein Anbieter wirbt: „Unser Magnetmotor läuft ohne Strom und ohne Brennstoff dauerhaft und liefert nebenbei Strom für dein Haus.“ Du sollst die Behauptung prüfen. Welche Frage deckt am schnellsten auf, ob sie physikalisch möglich ist?","options":["Woher stammt die Energie, die der Magnetmotor laufend an das Haus abgibt, und wohin geht sie dabei?","Wie stark sind die Magnete im Läufer, und genügt ihre Anziehung, um den Motor dauerhaft zu drehen?","Wie reibungsarm laufen die Lager des Motors, und hält das ihn auch bei der Stromabgabe dauerhaft in Gang?","Wie viele Kilowattstunden müsste der Motor am Tag liefern, und deckt das den Bedarf eines Haushalts?"],"correctIndex":0,"explanation":"Jede Maschine, die dauerhaft Energie abgibt, muss sie irgendwoher beziehen: Energie wird nur umgewandelt, nie aus dem Nichts erzeugt. Ein Gerät ohne Energiezufuhr, das auch noch Strom liefert, widerspräche also dem Energieerhaltungssatz. Zudem geht bei jeder realen Umwandlung ein Teil als Wärme verloren, etwa durch Reibung, sodass selbst ein Motor, der sich nur dreht, ohne Zufuhr irgendwann stehen bleibt. Die Frage nach Herkunft und Verbleib der Energie prüft genau das. Die Stärke der Magnete klingt nach Physik, sagt aber nichts über eine dauerhafte Energiequelle: Ein Magnetfeld liefert Energie nur beim Übergang in eine neue Lage, für den Rückweg braucht es sie wieder. Auch reibungsarme Lager klingen vernünftig, verringern aber nur die Verluste und liefern keine Energie, die ins Haus abgegeben werden könnte. Die Tagesleistung hilft beim Dimensionieren, setzt aber voraus, dass das Gerät überhaupt Energie erzeugen kann.","coreRule":"⚡ Frag bei jeder Energie-Behauptung: Wo kommt die Energie her, wo geht sie hin, und wie bezahlt das System den Preis der zunehmenden Unordnung?","quote":"","quoteLabel":"","scenario":"Auf einer Webseite wird ein „Magnetmotor“ für 499 Euro beworben. Er soll sich ohne Strom und ohne Brennstoff dauerhaft drehen und zusätzlich einen Haushalt mit Strom versorgen.","kurz":"Wer Strom abgibt, muss ihn irgendwoher beziehen, denn Energie wird nur umgewandelt, nie erzeugt. Gerade Fragen nach Magnetstärke, Lagern oder Leistung klingen nach Physik, setzen aber schon voraus, dass es eine Quelle gibt.","prueffrage":"Was müsste nach einem Jahr Dauerbetrieb im Motor fehlen oder verbraucht sein, wenn er die ganze Zeit ein Haus mit Strom versorgt hat?","rueckmeldung":[{"option":1,"text":"Magnete können tatsächlich einen Läufer in Bewegung setzen, das klingt nach solider Physik. Ein Magnetfeld gibt Energie aber nur beim Übergang in eine neue Lage ab, für den Rückweg braucht es sie wieder. Die Stärke der Magnete ist daher keine dauerhafte Quelle."},{"option":2,"text":"Weniger Reibung ist sinnvoll, denn Reibung macht aus Bewegung Wärme. Bessere Lager verringern aber nur die Verluste und liefern keine Energie, die ins Haus gehen könnte. Sie verzögern das Stehenbleiben, verhindern es aber nicht."},{"option":3,"text":"Den Tagesbedarf zu kennen, hilft beim Dimensionieren, wenn ein Gerät Energie liefert. Genau das ist hier die offene Frage. Die Menge in Kilowattstunden lässt sich erst sinnvoll fragen, wenn geklärt ist, ob eine Quelle existiert."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 2, 3.3 First Law of Thermodynamics","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/3-3-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0f153ccc06967431"}},{"id":"qc-2","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.4","stufe":2,"question":"Eine Kollegin behauptet: „Mars ist riesig. Dass er bei deiner Geburt am Himmel stand, hat dich geprägt, denn die Schwerkraft eines Planeten wirkt auf alles, was auf ihm lebt oder im Einflussbereich liegt.“ Welche Rückfrage prüft die Behauptung am besten?","options":["Wie stark zog der Mars an dem Neugeborenen im Vergleich zu den Menschen im Kreißsaal, die neben ihm standen?","Wer verdient mit Horoskopen sein Geld, und wie neutral können deren Aussagen über den Einfluss des Mars deshalb sein?","Auf welche Quellen stützt sich die Kollegin, und sind das anerkannte Fachleute für die Physik der Planeten?","Seit wie vielen Jahrhunderten wird dem Mars ein Einfluss auf Geburten zugeschrieben, und wie viele Menschen glauben daran?"],"correctIndex":0,"explanation":"Die Schwerkraft wächst mit der Masse, nimmt aber mit dem Quadrat der Entfernung ab: Verdoppelst du den Abstand, bleibt ein Viertel der Kraft, bei zehnfachem Abstand ein Hundertstel. Der Mars ist zwar riesig, aber selbst bei größter Annäherung rund 55 Millionen Kilometer entfernt. Der Geburtshelfer ist winzig, steht aber etwa einen halben Meter vom Neugeborenen entfernt. Rechnet man beides durch, zieht der Geburtshelfer meist um ein Vielfaches stärker am Baby als der Mars, und selbst bei dessen größter Annäherung ist die Kraft des Mars nicht stärker als die des Geburtshelfers. Die Behauptung lässt sich also mit einer einfachen Größenordnungsrechnung prüfen. Wer Masse und Abstand vergleicht, kann die Behauptung testen, statt sie nur zu bestaunen oder abzulehnen.","coreRule":"⚡ Ferne Größe schlägt nahe Kleinheit nicht automatisch: Bei einer behaupteten Fernwirkung zuerst Masse und Abstand vergleichen.","quote":"Die Gravitationskraft, eine der vier fundamentalen Kräfte des Universums, nimmt mit dem Quadrat der Entfernung ab.","quoteLabel":"Merksatz:","scenario":"Du sprichst mit einer Kollegin über Horoskope. Sie sagt, die Anziehungskraft des Mars bei der Geburt erkläre, warum manche Menschen so sind, wie sie sind.","beleg":"Werkstück C.1.4 – Gravitation & das Abstandsgesetz (Rechnung in Band II, Fußnote zur Hebamme)","kurz":"Die Behauptung lässt sich selbst prüfen: Schwerkraft hängt von Masse und Abstand ab. Mars ist zwar riesig, aber Millionen Kilometer fern, während der Geburtshelfer winzig, aber einen halben Meter nah ist. Wer nur auf die Größe schaut, übersieht die Entfernung.","prueffrage":"Wie weit ist der Mars selbst bei seiner größten Annäherung von der Erde entfernt?","rueckmeldung":[{"option":1,"text":"Wer an Horoskopen verdient, hat Interessen, und diese Frage kann anderswo wichtig sein. Über die Kraft, die der Mars tatsächlich auf ein Neugeborenes ausübt, sagt sie jedoch nichts, die lässt sich unabhängig davon nachrechnen."},{"option":2,"text":"Nach den Quellen zu fragen, wirkt gründlich. Hier ist es aber ein Umweg, denn die Behauptung lässt sich direkt prüfen, indem man Masse und Abstand vergleicht. Dafür braucht man keine Fachleute als Zwischeninstanz."},{"option":3,"text":"Dass eine Ansicht alt ist oder viele sie teilen, gibt ihr Gewicht und weckt Respekt. Ob sie stimmt, zeigt das aber nicht; Alter und Verbreitung sind keine Belege für die behauptete Kraft des Mars."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"daten","kurz":"NASA NSSDCA: Mars Fact Sheet","oeffentlich":true,"url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f04f5332f9af1061"}},{"id":"qc-3","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"87e57cfad720f77a","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"clusterId":"C","werkstueckRef":"C.2.1","stufe":2,"question":"Eine Verkäuferin sagt: „Dieses Mittel ist eine C30-Potenz. Es wurde dreißigmal im Verhältnis 1 zu 100 verdünnt, enthält aber noch den vollen Wirkstoff der Ausgangssubstanz, nur eben feiner verteilt.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man rechnet nach, wie viele Moleküle der Ausgangssubstanz bei dieser Verdünnung im Mittel noch übrig sein können, denn Materie besteht aus einzelnen Teilchen und ist nicht unendlich teilbar.","Man klärt, ob die Verkäuferin am Verkauf des Mittels verdient, denn ein finanzielles Interesse kann ihre Darstellung färben und sollte bei jeder Verkaufsaussage mitbedacht werden.","Man sucht nach kontrollierten Studien, in denen das Mittel mit einem Scheinpräparat verglichen wurde, denn nur ein solcher Vergleich zeigt, ob ein Mittel tatsächlich etwas bewirkt.","Man vergleicht die Aussage der Verkäuferin mit dem Text auf der Packung, denn Widersprüche zwischen mündlicher und schriftlicher Angabe wären ein deutliches Warnzeichen für unsorgfältige Angaben."],"correctIndex":0,"explanation":"Die Behauptung lässt sich ohne Autoritäten und ohne Selbstversuch prüfen: durch Nachrechnen. Ein Mol eines Stoffes enthält etwa 6 × 10²³ Teilchen (Avogadro-Konstante). Bei C12 (1 zu 10²⁴) enthält ein Mol des Endprodukts im Mittel nur noch etwa 0,6 Moleküle der Ausgangssubstanz. C30 bedeutet 1 zu 10⁶⁰, also weit jenseits dieser Grenze. Bei einer einmolaren Urtinktur bräuchte man für im Mittel ein einziges Molekül eine Lösungskugel mit etwa dem Durchmesser Erde–Sonne (rund 150 Millionen km). Die Aussage „enthält noch den vollen Wirkstoff, nur feiner verteilt“ scheitert also an der Teilchennatur der Materie. Die anderen Schritte sind für sich vernünftig, treffen aber nicht den Kern: Ein finanzielles Interesse der Verkäuferin ändert nichts an der Teilchenzahl, Studien mit Scheinpräparat prüfen eine mögliche Wirkung und nicht den Gehalt, und ein Abgleich mit der Packung zeigt nur, ob zwei Angaben übereinstimmen, nicht, ob sie stimmen.","coreRule":"⚡ Behauptungen über Stoffe lassen sich nachrechnen: Materie ist nicht unendlich teilbar, und ab einer bestimmten Verdünnung ist statistisch kein Teilchen mehr da.","quote":"","quoteLabel":"","scenario":"Du stehst in einer Apotheke und liest die Beschreibung eines Mittels. Die Verkäuferin erklärt dir die Herstellung der C30-Potenz.","beleg":"Werkstück C.2.1, Fußnoten gl-c-avogadro und gl-c-c30: Rademacher, P. (2013): „Die Mär vom Wasser mit Gedächtnis“. Chemie in unserer Zeit 47(1), S. 24–31","kurz":"Die Aussage lässt sich nachrechnen: Bei 1 zu 10⁶⁰ ist im Mittel kein einziges Molekül der Ausgangssubstanz mehr übrig. „Feiner verteilt“ verkennt, dass Materie aus Teilchen besteht und nicht beliebig teilbar ist.","prueffrage":"Wie viel vom Ausgangsstoff kommt am Ende an, wenn man dreißigmal hintereinander jeweils nur ein Hundertstel weitergibt?","rueckmeldung":[{"option":1,"text":"Ein Verkaufsinteresse ist bei Verkaufsaussagen tatsächlich ein Grund zur Vorsicht. Ob die Behauptung stimmt, entscheidet es aber nicht: Die Teilchenzahl im Mittel bleibt dieselbe, egal wer verdient."},{"option":2,"text":"Ein Vergleich mit einem Scheinpräparat ist der richtige Weg, um eine mögliche Wirkung zu prüfen. Die Aussage betrifft aber den Gehalt, und der lässt sich ohne Studie nachrechnen."},{"option":3,"text":"Ein Widerspruch zwischen Mündlichem und Schriftlichem wäre ein Warnzeichen. Stimmen beide überein, heißt das aber nur, dass sie sich nicht widersprechen. Ob die Angabe zum Wirkstoff stimmt, bleibt offen."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"daten","kurz":"NIST CODATA: Avogadro constant","oeffentlich":true,"url":"https://physics.nist.gov/cgi-bin/cuu/Value?na","abruf":"2026-10-12"},{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices: assessing the evidence and ensuring consistency in regulating medical claims in the EU","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"87e57cfad720f77a"}},{"id":"qc-4","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.2","stufe":1,"question":"Welche Frage solltest du als Erstes klären, bevor du bei einer Infektion über ein Antibiotikum entscheidest?","options":["Ob er Mittel nimmt, die sich mit einem Antibiotikum nicht vertragen.","Ob seine Beschwerden von Bakterien oder von Viren verursacht werden.","Ob er früher schon ein Antibiotikum bekam und es ohne Allergie vertrug.","Ob in seiner Region die Erreger häufig gegen Antibiotika resistent sind."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob eine Infektion vorliegt, sondern welcher Erreger dahintersteckt. Antibiotika greifen Strukturen an, die Bakterien haben, menschliche Zellen aber nicht, etwa die Zellwand. Viren besitzen weder Zellwand noch eigenen Stoffwechsel, sie sind genetische Pakete, die fremde Zellen zur Vervielfältigung nutzen. Bei einer gewöhnlichen Erkältung (virale Ursache) hat ein Antibiotikum also nichts, woran es angreifen könnte. Es nützt nicht, kann aber schaden: Es tötet empfindliche Bakterien im Körper und begünstigt die wenigen zufällig resistenten, die überleben und sich vermehren.","coreRule":"⚡ Bevor du eine Behandlung wählst, kläre, was der Angreifer ist: Das Wort „Infektion“ allein sagt noch nichts darüber, welches Mittel hilft.","quote":"„Ich habe eine Infektion, also brauche ich Antibiotika.“","quoteLabel":"Typischer Fehlschluss","scenario":"Ein Mann mit laufender Nase, Halsschmerzen und Abgeschlagenheit sagt zu seiner Ärztin: „Ich habe eine Infektion, also brauche ich Antibiotika.“ Die Ärztin lehnt ab.","beleg":"Werkstück C.4.2, Abschnitt „Die vergebliche Medikation“ und „Kontext & Tiefe“ (Bakterien: Antibiotika greifen z. B. die Zellwand an; Viren: keine Zellwand, kein eigener Stoffwechsel; Resistenzen durch unnötigen Einsatz).","kurz":"Ein Antibiotikum wirkt nur gegen Bakterien, nicht gegen Viren. Aus „Infektion“ folgt deshalb noch nicht „Antibiotikum“; zuerst zählt der Erreger. Bei einer Erkältung ist er meist ein Virus, dann nützt das Mittel nichts und kann sogar schaden.","prueffrage":"Was genau steckt hinter dem Wort „Infektion“, und gilt das für alle Infektionen gleich?","rueckmeldung":[{"option":0,"text":"Wechselwirkungen mit seinen Mitteln wären wichtig, sobald ein Antibiotikum verordnet würde. Davor muss aber feststehen, ob es bei diesen Beschwerden überhaupt etwas ausrichten kann."},{"option":2,"text":"Eine frühere gute Verträglichkeit ist sinnvoll zu wissen, sobald ein Antibiotikum infrage kommt. Ob es das tut, ist die vorgelagerte Frage, und die beantwortet die Verträglichkeit nicht."},{"option":3,"text":"Die Resistenzlage hilft bei der Wahl des Wirkstoffs, wenn Bakterien beteiligt sind. Ob hier überhaupt Bakterien im Spiel sind, sagt sie nicht, und genau davon hängt die Entscheidung zuerst ab."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Mobley 2006, How do antibiotics kill bacterial cells but not human cells?, Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/how-do-antibiotics-kill-b/","abruf":"2026-10-12"},{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Antibiotics","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/antibiotics/overview-of-antibiotics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"77d216dbe560b3b4"}},{"id":"qc-5","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.4","stufe":3,"question":"Was ist an diesem Argument der entscheidende Fehler?","options":["Die Prämisse ist falsch: Ein Großbrand in einem Hochhaus wird deutlich heißer als ein reines Kerosinfeuer, sodass der Stahl dort durchaus bis zum Schmelzen erhitzt werden konnte.","Die Prämisse ist richtig, aber der Schluss setzt unbemerkt voraus, Stahl müsse schmelzen, um zu versagen; schon weit darunter verliert er einen Großteil seiner Tragfähigkeit.","Die Prämisse ist richtig, aber der Schluss betrachtet das Feuer für sich allein und übersieht, dass der Einschlag die Träger schon vorher beschädigt haben kann.","Die Prämisse ist richtig, aber der Schluss übersieht, dass ein lang anhaltender Großbrand den Stahl nach und nach doch bis zu seinem Schmelzpunkt aufheizen kann."],"correctIndex":1,"explanation":"Das Argument prüft die falsche Größe. Dass Stahl bei 800–1000 °C nicht schmilzt, stimmt, ist aber unerheblich: Ein Träger muss nicht flüssig werden, um zu versagen, es genügt, dass er die Last nicht mehr trägt. Baustahl verliert schon bei 600–800 °C über die Hälfte seiner Tragfähigkeit; bei etwa 800 °C bleibt rund ein Zehntel, bei 1000 °C nur noch wenige Prozent. Geschwächte Träger biegen sich durch und knicken aus; gibt ein Stockwerk nach, stürzt der obere Gebäudeteil auf das darunterliegende, und die dynamische Belastung übersteigt die statische Last, für die ein Gebäude ausgelegt ist, um ein Vielfaches (progressiver Kollaps). Das erklärt den Einsturz bereits vollständig; eine Sprengung wird nur durch den unbegründeten Zwischenschritt „Stahl muss schmelzen“ scheinbar nötig.","coreRule":"⚡ Ein Bauteil muss nicht schmelzen, um zu versagen: Prüfe, ob die Prämisse des Gegenarguments überhaupt zur Schlussfolgerung passt.","quote":"","quoteLabel":"","scenario":"In einer Diskussion über den Einsturz eines Hochhauses, in dem nach einem Flugzeugeinschlag und dem Abschlagen des Brandschutzes ein Großbrand wütete, argumentiert jemand: „Kerosinfeuer erreicht höchstens 800–1000 °C, Stahl schmilzt aber erst bei etwa 1500 °C. Also kann das Feuer den Einsturz nicht verursacht haben, es muss eine Sprengung gewesen sein.“","kurz":"Das Argument prüft die falsche Größe: Stahl muss nicht schmelzen, um zu versagen. Schon bei 600–800 °C verliert er über die Hälfte seiner Tragfähigkeit, und Feuer von 800–1000 °C reicht dafür völlig aus.","prueffrage":"Was wurde beim Einschlag abgeschlagen, und wozu ist es an den Stahlträgern eines Hochhauses angebracht?","rueckmeldung":[{"option":0,"text":"Ein Großbrand klingt nach Temperaturen weit über einem Kerosinfeuer. Doch auch ein Gebäudebrand bleibt typischerweise bei etwa 800–1000 °C, und die genannte Prämisse stimmt. Der Fehler liegt woanders: Der Stahl muss gar nicht schmelzen, um zu versagen."},{"option":2,"text":"Ein Einschlag kann Träger tatsächlich vorschädigen, und das kann zum Versagen beitragen. Das Argument scheitert aber nicht daran, dass es diesen Punkt auslässt: Schon die Hitze allein schwächt den Stahl so stark, dass der Einsturz erklärbar ist."},{"option":3,"text":"Je länger ein Brand dauert, desto näher kommt der Stahl der Flammentemperatur. Diese liegt aber bei höchstens 800–1000 °C, weit unter dem Schmelzpunkt. Der Fehler ist, dass Schmelzen überhaupt vorausgesetzt wird: Versagen beginnt schon deutlich früher."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"},{"typ":"literatur","kurz":"NIST (2005): Final Report on the Collapse of the World Trade Center Towers (NCSTAR 1)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3750e78fbc0ac48a"}},{"id":"qc-6","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.6","stufe":3,"question":"Welche Folgerung ist am besten begründet?","options":["Eine Selbstentzündung kann die Frau von innen entzündet haben; da sich keine äußere Zündquelle fand, bleibt nach Ausschluss aller gewöhnlichen Erklärungen nur diese übrig.","Ein kurzes, sehr heißes Feuer kann den Körper rasch verbrannt haben; weil es nur kurz loderte, blieb ihm keine Zeit, auf die übrige Einrichtung im Raum überzugreifen.","Eine kleine äußere Zündquelle kann die Kleidung entzündet haben; danach brannte Körperfett über Stunden langsam am Stoff weiter, ohne den Raum zu erfassen.","Eine bislang unbekannte Ursache kann gewirkt haben; da sich weder eine Zündquelle noch Brandschäden im Raum fanden, lässt sich der Fall derzeit nicht erklären."],"correctIndex":2,"explanation":"Der Film schließt von „ich sehe keine Ursache“ auf „es gab keine Ursache“. Das ist ein Fehlschluss: Eine Zigarette, Kerze oder ein Funke ist schnell übersehen, vor allem wenn das Feuer sie selbst verzehrt hat. Auch die unversehrte Umgebung spricht nicht gegen ein normales Feuer. Sie passt zu einem Feuer, das klein und langsam brennt: Schmelzendes Körperfett wird von verkohlter Kleidung aufgesaugt und brennt dort wie an einem Kerzendocht, nur eben umgekehrt, weil der Brennstoff innen liegt. Experimentell ließ sich das nachstellen: Ein in eine Baumwolldecke gewickelter Schweinekadaver (DeHaan und Nurbakhsh, 2001), mit Benzin entzündet, brannte mehr als 6,5 Stunden von selbst weiter; als die Forscher es löschten, waren bereits über 60 Prozent des Tierkörpers zerstört. Eine bekannte, reproduzierbare Erklärung braucht keine neue, geheimnisvolle Ursache. Die Selbstentzündung klingt nach einer Lösung, wenn keine Quelle zu sehen ist, doch ausgeschlossen wurde nichts: Die Zündquelle wurde nur nicht gesehen.","coreRule":"⚡ Keine sichtbare Ursache heißt nicht: keine Ursache. Eine Erklärung mit bekannter Physik schlägt „unerklärlich“.","quote":"Kein Zauberfeuer: Banale Zündquelle + stundenlanger Schwelbrand = Dochteffekt.","quoteLabel":"Merksatz:","scenario":"Eine Dokumentation zeigt den Fall einer älteren Frau, die in ihrer Wohnung fast vollständig zu Asche verbrannt ist. Der Sessel darunter ist zerstört, aber die übrige Einrichtung ist kaum beschädigt. Im Film heißt es: „Ohne erkennbare Zündquelle und ohne Brandschäden im Raum kann das nur eine spontane Selbstentzündung gewesen sein.“","beleg":"Werkstück C.5.6, Fußnoten gl-c-reeser, gl-c-dehaan; Red Flags und Anti-Denkmuster","kurz":"Aus „keine Zündquelle zu sehen“ folgt nicht „keine vorhanden“: Ein Funke oder eine Kerze kann übersehen oder verzehrt worden sein. Ein kleines, langsames Feuer, bei dem Körperfett in der Kleidung wie an einem Docht brennt, erklärt auch die unversehrte Umgebung.","prueffrage":"Welche Gegenstände in der Wohnung sind verbrannt und welche nicht, und wie weit standen sie vom Sessel entfernt?","rueckmeldung":[{"option":0,"text":"Dass keine Zündquelle zu sehen war, stimmt. Ausgeschlossen wurde damit aber nichts: Ein Funke oder eine Kerze ist schnell übersehen, zumal wenn das Feuer sie verzehrt hat. Wo kein Ausschluss stattfand, bleibt auch nichts „übrig“."},{"option":1,"text":"Die unversehrte Umgebung passt zu einem räumlich begrenzten Feuer. Ein kurzes, sehr heißes Feuer würde den Körper aber kaum so weitgehend zerstören. Dafür braucht es ein kleines Feuer, das sehr lange brennt."},{"option":3,"text":"Zurückhaltung im Urteil ist grundsätzlich klug, und eine Zündquelle wurde tatsächlich nicht gesehen. Der Fall ist aber nicht unerklärt: Es gibt eine bekannte, nachstellbare Erklärung, die ohne geheimnisvolle Ursache auskommt."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass and Its Implications for the Consumption of Human Bodies in Fires. J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth: Experiments in the Combustibility of the Human Body. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0d50065001d68c62"}},{"id":"qc-7","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.3","stufe":1,"question":"Bei der Frage nach unserer Herkunft sagt jemand: „Wir sind aus Sternenstoff gemacht? Das ist doch nur eine hübsche Metapher, so wie ‚Wir sind alle eins‘.“ Welche Antwort zeigt am besten, dass die Aussage wörtlich und nachprüfbar gemeint ist?","options":["Das Universum bestand anfangs fast nur aus Wasserstoff und Helium; Kohlenstoff und Sauerstoff entstanden später durch Kernfusion in Sternen und wurden durch Sternexplosionen verteilt. Die Kohlenstoff- und Sauerstoffatome in deinem Körper waren also tatsächlich einmal Teil von Sternen.","Die Verbindung von Mensch und Sternen ist ein altes Motiv in Dichtung und Philosophie; viele Kulturen verstanden sich als Teil eines großen kosmischen Ganzen. Der Satz steht also in einer langen, ernst gemeinten Denktradition und drückt aus, wie Menschen sich im Kosmos sehen.","Ein Großteil der Atome in deinem Körper ist Wasserstoff, der nach heutigem Wissen schon in den ersten Minuten nach dem Urknall entstand, etwa gebunden im Wasser, das du trinkst. Diese Atome sind also so alt wie das Universum selbst.","Die Gesetze der Physik gelten überall im Universum, in fernen Sternen ebenso wie in deinem Körper, und Messungen in Labor und Teleskop bestätigen das seit Langem. Mensch und Stern folgen also denselben Naturgesetzen."],"correctIndex":0,"explanation":"Die Aussage lässt sich an Beobachtungen prüfen: Das frühe Universum bestand fast nur aus Wasserstoff (etwa 75 %) und Helium (etwa 25 %). Kohlenstoff, Sauerstoff, Eisen und alles andere Schwere gab es nicht und musste erst entstehen. Kohlenstoff, Sauerstoff und Eisen entstehen durch Kernfusion in Sternen und ihren Explosionen; sehr schwere Elemente wie Gold großenteils auch bei Neutronensternkollisionen. Sternexplosionen und Sternwinde streuen die neuen Elemente ins All, wo sie in spätere Gaswolken, Sterne und Planeten eingehen. Wer Kohlenstoff und Sauerstoff im Körper hat, trägt damit den Beleg in sich, dass in unserer galaktischen Nachbarschaft mindestens ein massereicher Stern gelebt hat und gestorben ist. Das ist keine Metapher, sondern eine überprüfbare Herkunftsgeschichte der Materie.","coreRule":"⚡ Wer „Metapher“ sagt, muss prüfen, ob sich die Aussage nicht doch wörtlich belegen lässt: Wir sind nicht von den Sternen beeinflusst, sondern aus ihnen gemacht.","quote":"","quoteLabel":"","scenario":"Ein Gespräch über Esoterik und Wissenschaft: Eine Person hält „Wir sind aus Sternenstoff gemacht“ für eine rein poetische Redewendung ohne Tatsachengehalt.","beleg":"Werkstück C.1.3; Haupttext sowie Abschnitt „Kontext & Tiefe“ (Supernova/Sternwinde); Fn gl-c-elementherkunft (Kobayashi et al. 2020); Fn gl-c-nukleosynthese (Tyson/Gott/Strauss 2022; Schwedt 2014).","kurz":"Die Aussage wird nachprüfbar, weil sich sagen lässt, woher welche Atome stammen: Kohlenstoff und Sauerstoff gab es anfangs nicht, sie entstanden in Sternen. Eine hübsche Formulierung muss keine Metapher ohne Tatsachengehalt sein.","prueffrage":"Welche Stoffe gab es kurz nach dem Urknall überhaupt, und woher soll der Rest stammen?","rueckmeldung":[{"option":1,"text":"Dass der Satz in einer ernst gemeinten Denktradition steht, ist richtig. Er sagt aber nur, wie Menschen sich im Kosmos sehen, und nichts darüber, woher die Atome stammen, und genau darum ging es."},{"option":2,"text":"Der Wasserstoff stammt tatsächlich aus der Frühzeit des Universums. Das erklärt aber nicht, woher Kohlenstoff und Sauerstoff kommen, und gerade bei diesen Atomen zeigt sich die Verbindung zu den Sternen."},{"option":3,"text":"Dass überall dieselben Naturgesetze gelten, ist gut belegt. Daraus folgt aber nichts über die Herkunft der Atome: Gleiche Gesetze können ganz verschiedene Stoffgeschichten zulassen."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Fields, B. D.; Molaro, P.; Sarkar, S.: Big Bang Nucleosynthesis (rev. Aug. 2023). In: Particle Data Group, Review of Particle Physics 2024, Kap. 24","oeffentlich":true,"url":"https://pdg.lbl.gov/2024/reviews/rpp2024-rev-bbang-nucleosynthesis.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Imagine the Universe!: Supernovae","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/science/objects/supernovae1.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"67545bb84e487d36"}},{"id":"qc-8","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.5","stufe":2,"question":"Du liest die Schlagzeile: „Fossilienfund beweist: Die Gesteinsschicht ist genau 410 Millionen Jahre alt.“ Welche Rückfrage prüft am besten, wie belastbar diese Altersangabe ist?","options":["Wurde das Alter über den Zerfall radioaktiver Isotope gemessen, oder stützt es sich nur auf Schichtenfolge und Fossilien?","Wer hat die Untersuchung des Fundes bezahlt, und hätte der Geldgeber Interesse an einem besonders hohen Alter der Schicht?","Wie vollständig ist das Fossil erhalten, und reicht es, um das Tier sicher zu bestimmen, dessen Schicht datiert wurde?","Wie viele Fossilien dieser Art sind bekannt, und wäre die Schicht mit dem Fund demnach besonders selten und bedeutend?"],"correctIndex":0,"explanation":"Schichtenfolge und Fossilien ordnen nur die Reihenfolge: In ungestörten Schichten liegt das Ältere unten. Konkrete Jahreszahlen stammen aus radiometrischer Datierung, etwa der Uran-Blei-Methode, die den gleichmäßigen, vorhersagbaren Zerfall radioaktiver Isotope wie eine Stoppuhr nutzt. Wer eine Altersangabe prüfen will, fragt deshalb nach der Methode hinter der Zahl. Die Frage nach dem Geldgeber klingt nach gesunder Skepsis, prüft aber mögliche Interessen und nicht die Altersbestimmung. Erhaltung und Artbestimmung wirken wie Sorgfalt am Fund, betreffen aber das Tier und nicht das Alter der Schicht. Wie selten der Fund ist, klingt nach Einordnung, sagt aber nichts darüber, wie man auf die Jahreszahl kam.","coreRule":"⚡ Schichten ordnen die Reihenfolge, Isotope liefern die Jahre: Frag bei jeder Altersangabe nach der Messmethode.","quote":"","quoteLabel":"","scenario":"Ein Nachrichtenportal berichtet über den Fund eines Fossils in einer Gesteinsschicht. Der Artikel nennt ein exaktes Alter in Jahren, erklärt aber nicht, woher es stammt.","beleg":"Werkstück C.1.5, Abschnitt „Kontext & Tiefe“ (Buch der Gesteine, Atomare Uhr); Fn. gl-c-erdalter (Dalrymple 2001) für die übereinstimmenden Datierungen","kurz":"Eine genaue Jahreszahl stammt nicht aus der Schichtenfolge, die nur Älteres von Jüngerem trennt, sondern aus einer Messung wie dem Zerfall radioaktiver Isotope. Wer die Zahl prüfen will, fragt deshalb nach der Methode dahinter.","prueffrage":"Woran lässt sich in der Meldung erkennen, wie aus dem Fund eine Zahl in Millionen Jahren wurde?","rueckmeldung":[{"option":1,"text":"Nach möglichen Interessen zu fragen, ist an sich ein sinnvoller Reflex. Er sagt aber nichts darüber, wie die Zahl zustande kam: Auch eine bezahlte Untersuchung kann sauber datieren, eine unabhängige ungenau."},{"option":2,"text":"Eine gut erhaltene, sicher bestimmte Art ist wichtige Sorgfalt am Fund. Diese Frage gilt aber dem Tier, nicht der Schicht: Wie alt das Gestein ist, folgt daraus noch nicht."},{"option":3,"text":"Wie selten ein Fund ist, hilft bei der Einordnung seiner Bedeutung. Über die Jahreszahl sagt es nichts, denn auch ein seltener Fund kann richtig oder falsch datiert sein."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"USGS: Geologic Time – Relative Time Scale","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/relative.html","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS: Geologic Time – radiometrische Zeitskala","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/radiometric.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"98f0e8e26b54aecf"}},{"id":"qc-9","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.6","stufe":2,"question":"Welche Antwort trifft die Schwachstelle im zweiten Satz des Gastes am besten?","options":["„Leben jenseits der Erde ist bisher nicht nachgewiesen, also gibt es auch keine alte Zivilisation, die das Reisen gelöst haben könnte.“","„Bei sehr hoher Geschwindigkeit vergeht für Reisende weniger Zeit; wer zurückkehrt, findet eine Heimat vor, in der viel mehr Zeit verging.“","„Sie setzen leichte Reisen voraus, nennen aber keinen Weg; schon zum nächsten Stern bräuchte unsere schnellste Sonde 6.600 Jahre.“","„Nichts mit Masse erreicht die Lichtgeschwindigkeit; damit wäre ein Besuch von fremden Sternen bei uns physikalisch ausgeschlossen.“"],"correctIndex":2,"explanation":"Der Satz des Gastes trägt seine Last in einer stillen Annahme: dass Reisen zwischen Sternen mühelos möglich sind. Nichts mit Masse erreicht die Lichtgeschwindigkeit (rund 300.000 km/s), die Milchstraße misst etwa 100.000 Lichtjahre, und selbst Tausende Zivilisationen lägen im Schnitt Tausende Lichtjahre auseinander. Schon mit der schnellsten menschlichen Sonde (rund 690.000 km/h, und diese Geschwindigkeit erreicht sie nur im Sturz auf die Sonne zu) dauerte der Weg zum nächsten Stern (gut 4 Lichtjahre) etwa 6.600 Jahre. „Sicher längst im Griff“ ist ein Argument aus Unwissenheit: Es nennt keinen Mechanismus und verschiebt die Beweislast; die Antwort, die genau diese Annahme benennt, trifft die Schwachstelle.","coreRule":"⚡ Prüfe, welche Annahme eine Behauptung stillschweigend voraussetzt; „sicher irgendwie gelöst“ ersetzt keinen Mechanismus.","quote":"","quoteLabel":"","scenario":"In einem Podcast sagt ein Gast: „Unzählige Sichtungen zeigen, dass uns Außerirdische ständig besuchen. Eine Zivilisation, die so alt ist, hat das Reisen sicher längst im Griff.“ Die Moderatorin will auf den zweiten Satz antworten und hat einen Zettel mit Stichpunkten vor sich. Darauf steht: Nichts mit Masse erreicht die Lichtgeschwindigkeit; der nächste Stern ist gut 4 Lichtjahre entfernt, die schnellste menschliche Sonde bräuchte dorthin etwa 6.600 Jahre; Leben jenseits der Erde ist bisher nicht nachgewiesen, wird aber ernsthaft erforscht; bei sehr hoher Geschwindigkeit vergeht für die Reisenden weniger Zeit als für die Daheimgebliebenen.","kurz":"Der Satz setzt stillschweigend voraus, dass Reisen zwischen Sternen mühelos gelingen, und nennt keinen Weg dorthin. Dabei bräuchte schon die schnellste menschliche Sonde etwa 6.600 Jahre zum nächsten Stern; „sicher längst“ ersetzt hier den Beleg.","prueffrage":"Welche Annahme muss stimmen, damit der Schluss des Gastes überhaupt funktioniert, und nennt er dafür irgendeinen Beleg?","rueckmeldung":[{"option":0,"text":"Dass Leben jenseits der Erde bisher nicht nachgewiesen ist, stimmt. Daraus folgt aber nicht, dass es nichts gibt; es wird ernsthaft erforscht. Der Satz greift zudem die Voraussetzung an, statt die stille Annahme müheloser Reisen aufzudecken."},{"option":1,"text":"Dass für Reisende bei sehr hoher Geschwindigkeit weniger Zeit vergeht, ist richtig. Es sagt aber nichts darüber, ob solche Geschwindigkeiten überhaupt erreichbar sind, und setzt die Reise sogar voraus. So bleibt die Annahme des Gastes unangetastet."},{"option":3,"text":"Dass nichts mit Masse die Lichtgeschwindigkeit erreicht, stimmt. Ein Besuch wäre dadurch aber nicht ausgeschlossen, nur sehr langwierig und schwierig. Aus einer Schwierigkeit ein Verbot zu machen, behauptet mehr, als sich belegen lässt."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 3, 5.9 Relativistic Energy","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-3/pages/5-9-relativistic-energy","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Science: Parker Solar Probe (Missionsseite)","oeffentlich":true,"url":"https://science.nasa.gov/mission/parker-solar-probe/","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Imagine the Universe!: The Nearest Neighbor Star","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/features/cosmic/nearest_star_info.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f0d29a729cd2a313"}},{"id":"qc-10","status":"entwurf","clusterId":"C","werkstueckRef":"C.3.3","stufe":2,"question":"Ein Kritiker sagt: „Evolution ist reiner Zufall, und durch reinen Zufall entsteht kein Auge.“ Welcher Einwand trifft seinen Denkfehler am genauesten?","options":["Er übersieht, dass Lebewesen sich im Laufe ihres Lebens gezielt an ihre Umwelt anpassen und die dabei erworbenen Merkmale an ihre Nachkommen weitergeben.","Er übersieht, dass nur das Entstehen neuer Varianten zufällig ist, während die Umwelt nach Überleben und Fortpflanzung auswählt und kleine Vorteile sich summieren.","Er übersieht, wie lang die Erdgeschichte ist, denn in so gewaltigen Zeiträumen kann auch etwas derart Unwahrscheinliches wie ein Auge rein zufällig entstehen.","Er übersieht, dass das Auge nicht auf einmal entstand, sondern in sehr vielen kleinen Zufallsschritten, die für sich genommen jeweils durchaus wahrscheinlich genug waren."],"correctIndex":1,"explanation":"Der Kritiker setzt den Prozess mit seiner ersten Hälfte gleich. Mutation und Neukombination von Genen erzeugen ungerichtete Variation: Eine Mutation ist an sich weder gut noch schlecht. Danach arbeitet die Umwelt als nicht-zufälliger Filter, denn wer mit einem Merkmal besser überlebt und sich häufiger fortpflanzt, gibt es öfter weiter. Über viele Generationen summieren sich winzige Vorteile, ohne dass jemand ein Ziel oder einen Plan hätte (der Biologe Richard Dawkins nannte das den „blinden Uhrmacher“). Die Wahrscheinlichkeit, dass ein Auge auf einen Schlag durch Würfeln entsteht, ist verschwindend gering. Aber genau das behauptet niemand, und der Kritiker bekämpft damit einen Strohmann.","coreRule":"⚡ Evolution ist die nicht-zufällige Auswahl von zufälligen Variationen.","quote":"","quoteLabel":"","scenario":"","kurz":"Zufällig ist nur das Entstehen neuer Varianten. Danach filtert die Umwelt nach Überleben und Fortpflanzung, und kleine Vorteile summieren sich über Generationen. Der Kritiker setzt den ganzen Prozess mit seiner zufälligen ersten Hälfte gleich.","prueffrage":"Gibt es bei heutigen Tieren Augen in vielen Abstufungen, vom lichtempfindlichen Fleck bis zum Linsenauge, und nützt schon die einfachste Stufe?","rueckmeldung":[{"option":0,"text":"Dass Lebewesen sich anpassen, ist beobachtbar, und deshalb klingt das plausibel. Im Leben erworbene Merkmale werden aber nicht vererbt. Anpassung entsteht über Variation und Auswahl, und genau diese Auswahl übersieht der Kritiker."},{"option":2,"text":"Viel Zeit wirkt wie ein Gegenmittel gegen kleine Wahrscheinlichkeiten. Der Einwand übernimmt aber die Annahme des Kritikers, das Auge sei reines Würfelglück, nur mit mehr Würfen. Auch beliebig viel Zeit macht Zufall allein nicht zum Konstrukteur eines Auges."},{"option":3,"text":"Kleine Schritte sind tatsächlich ein wichtiger Teil der Erklärung. Wenn sie aber rein zufällig blieben, gäbe es nichts, was sie in dieselbe Richtung bündelt. Erst die Auswahl nach Überleben und Fortpflanzung lässt kleine Vorteile bestehen und sich summieren."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte a2 und b1)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Campbell, N. A.; Reece, J. B. u. a.: Campbell Biologie, 10. Aufl., Pearson 2016 (Landkarte [^gl-c-drift])","oeffentlich":false,"seite":"633, 636, 637"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d4f95193efbcb521"}},{"id":"qc-11","status":"entwurf","clusterId":"C","werkstueckRef":"C.3.6","stufe":4,"question":"Was ist an diesem Argument fehlerhaft?","options":["Es behandelt Eingriffe gleich, deren Folgen sich grundlegend unterscheiden: Beim Erwachsenen bleibt die Änderung bei ihm, beim Embryo wird sie vererbt (falsche Äquivalenz).","Es nennt Genveränderungen beim Menschen ethisch heikel, ohne das näher zu begründen, und baut die ganze Forderung auf diese bloß behauptete Annahme (unbegründete Prämisse).","Es fordert gleiche Strenge, ohne zu sagen, worin sie bestehen soll, sodass offen bleibt, was die Forderung für Erwachsene und Embryos konkret bedeutet (Vagheit).","Es schließt von CRISPR, also einem einzelnen Verfahren, auf jede Genveränderung beim Menschen, obwohl es andere Verfahren gar nicht betrachtet (vorschnelle Verallgemeinerung)."],"correctIndex":0,"explanation":"Das Argument wirft zwei Anwendungen in einen Topf, die ethisch sehr verschieden wiegen. Wird eine Körperzelle eines erwachsenen Patienten editiert (somatisch), bleibt die Veränderung auf diesen einen Menschen beschränkt; er kann einwilligen, und der Nutzen lässt sich gegen das Risiko abwägen. So arbeitet etwa Casgevy gegen die Sichelzellkrankheit; die britische MHRA ließ die Therapie im November 2023 als weltweit erste Behörde zu. Wird dagegen ein Embryo, eine Eizelle oder eine Samenzelle editiert (Keimbahn), wird die Veränderung unwiderruflich an alle künftigen Generationen vererbt, deren Langzeitfolgen unklar sind und die nie zustimmen konnten. Wer beides pauschal gleichsetzt, kann weder die erlaubte Heilung noch das echte Risiko angemessen beurteilen. Die gute Frage lautet deshalb nicht „Gentechnik: ja oder nein?“, sondern: Welche Zellen, mit welcher Zustimmung, mit welcher Vererbbarkeit?","coreRule":"⚡ Bevor du Gentechnik bewertest, frag: Bleibt die Veränderung beim Patienten (somatisch) oder geht sie an alle Nachkommen (Keimbahn)?","quote":"","quoteLabel":"","scenario":"In einer Diskussion sagt jemand: „Dass Forscher menschliche Zellen mit CRISPR verändern, ist ethisch heikel. Deshalb muss man jede Genveränderung beim Menschen gleich streng behandeln, egal ob bei einem erkrankten Erwachsenen oder bei einem Embryo.“","kurz":"Der Schluss auf gleiche Strenge übersieht, dass sich beide Fälle ethisch stark unterscheiden: Beim Erwachsenen bleibt die Änderung bei ihm, bei Embryo oder Keimzellen wird sie vererbt, ohne dass die Nachkommen zustimmen konnten.","prueffrage":"Wer ist von der Veränderung betroffen, und konnte jede dieser Personen dazu etwas sagen?","rueckmeldung":[{"option":1,"text":"Die Aussage „ethisch heikel“ wird tatsächlich nicht begründet. Sie ist aber weithin anerkannt und kein Kernproblem. Fehlerhaft ist erst der Sprung von „heikel“ zu „überall gleich streng“."},{"option":2,"text":"Wie „gleich streng“ aussehen soll, bleibt wirklich offen. Auch eine genaue Festlegung würde aber nichts retten, denn die Fälle unterscheiden sich in Vererbbarkeit und Einwilligung. Der Fehler liegt in der Gleichsetzung selbst."},{"option":3,"text":"CRISPR steht im Satz nur als Beispiel; gefordert wird es für „jede Genveränderung“, ohne Beschränkung auf ein Verfahren. Der Schluss springt nicht von einem Verfahren auf alle, sondern von einem Bedenken auf gleiche Behandlung."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „What are the Ethical Concerns of Genome Editing?“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/policy-issues/Genome-Editing/ethical-concerns","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a3848a27a52e5c41"}},{"id":"qc-12","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.5","stufe":2,"question":"Nach einer Operation wird einer Gruppe von Schmerzpatienten eine Zuckerpille als „starkes neues Schmerzmittel“ gegeben. Viele berichten kurz darauf von deutlich weniger Schmerzen. Ein Kollege winkt ab: „Das war nur Einbildung, da kann nichts Reales im Körper passiert sein.“ Was spricht am stärksten gegen diesen Schluss?","options":["Viele Patienten berichteten kurz darauf von deutlich weniger Schmerzen, und eine so häufige Erfahrung lässt sich kaum als bloße Einbildung Einzelner abtun.","Die Erwartung starker Linderung kann im Gehirn körpereigene Schmerzdämpfer wie Endorphine freisetzen, also kann die Linderung körperlich real sein.","Die Patienten spüren ihren Schmerz selbst am besten, und wenn sie deutlich weniger Schmerzen angeben, ist diese Linderung für sie wirklich real.","Die Patienten hielten die Pille für ein echtes Schmerzmittel, also haben sie sich die Linderung nicht bewusst eingebildet, und sie ist eher real."],"correctIndex":1,"explanation":"„Nur Einbildung“ unterstellt, dass alles, was von der Erwartung abhängt, nicht real sein kann. Das ist ein Fehlschluss. Erwartung kann messbare körperliche Vorgänge anstoßen: Eine als starkes Schmerzmittel angepriesene Zuckerpille kann im Gehirn die Ausschüttung körpereigener Endorphine auslösen, bei Parkinson-Patienten setzte eine Placebo-Injektion in einer kleinen PET-Studie mit sechs Patienten Dopamin frei. Kontrollierte Studien finden Placebo-Wirkungen fast nur bei Beschwerden, die Patienten selbst einschätzen. Die Placebo-Wirkung ist also real, aber begrenzt und sagt nichts darüber, ob die Behandlung selbst wirkt.","coreRule":"⚡ Ein Effekt, der von der Erwartung abhängt, ist nicht „nur Einbildung“. Er kann real sein und sagt trotzdem nichts über die spezifische Wirkung einer Behandlung.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück C.4.5, Abschnitt „Kontext & Tiefe“, Fußnoten gl-c-colloca, gl-c-dopamin (Schmerzlinderung/Endorphine, Dopamin); Frage aus Abfrage zu Anwendung umgebaut","kurz":"„Nur Einbildung“ unterstellt, dass Erwartungsabhängiges nicht real sein kann. Erwartung kann aber körperliche Vorgänge anstoßen, etwa die Ausschüttung körpereigener Endorphine. Die Linderung kann also real sein, auch wenn die Pille selbst nichts bewirkt.","prueffrage":"Hat der Kollege im Körper der Patienten irgendetwas nachgesehen, bevor er sagt, dort sei nichts Reales passiert?","rueckmeldung":[{"option":0,"text":"Die Häufigkeit beeindruckt, sagt aber nur, dass viele Linderung berichten, nicht, was im Körper geschah. Auch eine Erwartung, die viele teilen, kann solche Berichte auslösen. Entscheidend ist, ob sich ein körperlicher Vorgang dahinter denken lässt."},{"option":2,"text":"Schmerz ist tatsächlich etwas, das am besten die Betroffenen selbst einschätzen können. Dass die Linderung erlebt wurde, zeigt aber noch nicht, dass im Körper etwas Messbares geschah. Genau das behauptet der Kollege zu Unrecht auszuschließen."},{"option":3,"text":"Dass die Patienten nichts vortäuschten, stimmt, trifft aber den Einwand nicht. „Einbildung“ kann auch unbewusst gemeint sein, und für die Frage nach dem Körper bleibt die Unabsichtlichkeit ohne Gewicht."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Levine, Gordon & Fields 1978, The mechanism of placebo analgesia, Lancet 2(8091) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1016/s0140-6736(78)92762-9","url":"https://pubmed.ncbi.nlm.nih.gov/80579/","abruf":"2026-10-12"},{"typ":"url","kurz":"de la Fuente-Fernández u. a. 2001, Expectation and dopamine release: mechanism of the placebo effect in Parkinson's disease, Science 293 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1126/science.1060937","url":"https://pubmed.ncbi.nlm.nih.gov/11498597/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hróbjartsson & Gøtzsche 2010, Placebo interventions for all clinical conditions, Cochrane Database Syst Rev (PMC7156905)","oeffentlich":true,"doi":"10.1002/14651858.CD003974.pub3","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a7c06c32247de48b"}},{"id":"qc-13","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"01607b278ef344d2","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"clusterId":"C","werkstueckRef":"C.4.6","stufe":3,"question":"Welche Nachfrage prüft am besten, ob die Besserung auch ohne Behandlung zu erwarten war?","options":["Wie oft hattest du schon Schmerzspitzen, nach denen es auch ohne jede Behandlung wieder besser wurde?","Wie lange hat der Akupunkteur studiert und wie viele Patienten behandelt er pro Woche?","Wie stark war deine Erwartung, dass dir die Behandlung helfen wird, und wie überzeugt war der Akupunkteur?","Wie genau hat sich die Besserung angefühlt und an welchen Stellen des Rückens hast du sie bemerkt?"],"correctIndex":0,"explanation":"Wer Hilfe am Tiefpunkt sucht, erwischt oft genau den Extremwert. Nach einem extremen Wert liegt der nächste meist wieder näher am persönlichen Durchschnitt, auch ohne jede Behandlung. Die Nachfrage nach früheren Schmerzspitzen, die von allein abklangen, prüft genau das: Wäre die Besserung auch ohne Nadeln zu erwarten gewesen? Die Frage nach der Erwartung zielt auf den Placebo-Effekt, eine andere Erklärung, und Ausbildung des Behandlers oder das Gefühl der Besserung klären ebenfalls nicht, ob sie ohnehin gekommen wäre. Die eigene Vorgeschichte ist ein erster Prüfstein; ob die Nadeln selbst wirken, zeigt erst ein Vergleich mit Menschen, die nicht oder nur zum Schein behandelt wurden.","coreRule":"⚡ Wer am Tiefpunkt behandelt, hält die Rückkehr zur Mitte leicht für Heilung. Frag erst, was ohne Behandlung zu erwarten war.","quote":"","quoteLabel":"","scenario":"Ein Freund erzählt: „Ich hatte schreckliche Rückenschmerzen. Sonst sind sie meist mittelstark und schwanken von Tag zu Tag. Am schlimmsten Tag war ich beim Akupunkteur, am nächsten Tag war es deutlich besser. Die Nadeln wirken!“","beleg":"Werkstück C.4.6, Abschnitt „Regression zur Mitte“ (Rückenschmerz-Beispiel Skala 1-10, Akupunkteur), Werkbank-Frage","kurz":"Wer am schlimmsten Tag Hilfe sucht, erwischt oft einen Extremwert; danach liegt der nächste Tag meist wieder näher am Durchschnitt, auch ohne Behandlung. Die Besserung allein zeigt deshalb nicht, dass die Nadeln gewirkt haben.","prueffrage":"Warum ging dein Freund ausgerechnet an diesem Tag zum Akupunkteur und nicht an einem gewöhnlichen?","rueckmeldung":[{"option":1,"text":"Ausbildung und Erfahrung eines Behandlers wirken wie ein Qualitätsmerkmal. Sie sagen aber nichts über den Schmerzverlauf deines Freundes und damit nicht, ob die Besserung nach der Spitze ohnehin zu erwarten war."},{"option":2,"text":"Erwartung und Überzeugung können tatsächlich zur Besserung beitragen, das ist ein eigener Erklärungsweg (Placebo). Er klärt aber nicht, ob es nach einer Schmerzspitze von selbst besser wird, und genau darum geht es hier."},{"option":3,"text":"Genaue Angaben zur Besserung machen die Schilderung anschaulicher und wirken deshalb aufschlussreich. Ohne Vergleich mit dem üblichen Verlauf zeigen sie aber nicht, ob die Besserung ohnehin gekommen wäre."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vickers u. a. 2018, Acupuncture for Chronic Pain: Update of an Individual Patient Data Meta-Analysis, J Pain 19(5) (PMC5927830)","oeffentlich":true,"doi":"10.1016/j.jpain.2017.11.005","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"01607b278ef344d2"}},{"id":"qc-14","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.7","stufe":1,"question":"Ein Artikel meldet: „Alarm! In Haferflocken wurde eine Substanz nachgewiesen, die in hohen Mengen Leberschäden verursacht.“ Menge, Grenzwert und Vergleichswerte nennt er nicht. Welche Reaktion ist die vernünftigste?","options":["Beim Hersteller klären, ob die Substanz den Haferflocken zugesetzt wurde oder als Verunreinigung hineingeraten ist, bevor man urteilt.","Die gefundene Menge in den Haferflocken erfragen und mit Grenzwert und Vergleichswerten aus anderen Quellen abgleichen, bevor man urteilt.","Nachschlagen, ob die Leberschäden durch die Substanz zuerst bei Menschen oder zuerst bei Tieren beobachtet wurden, bevor man urteilt.","Prüfen, ob dieselbe Redaktion früher schon Alarm bei Lebensmitteln geschlagen hat und wie sich das herausstellte, bevor man urteilt."],"correctIndex":1,"explanation":"Ob ein Stoff schadet, entscheidet die Menge, nicht seine bloße Anwesenheit. Fast jede Substanz ist unterhalb einer Schwelle harmlos und oberhalb giftig: Wasser und Kochsalz können in extremen Mengen töten, Botulinumtoxin wird in winzigen Dosen sogar als Medikament eingesetzt. Selbst bei Stoffen, für die vorsorglich keine sichere Schwelle angenommen wird, hängt das Risiko von der Dosis ab. Die Meldung „gefunden“ sagt deshalb allein nichts über eine Gefahr aus. Aussagekräftig wird sie erst durch drei Zahlen: die gefundene Menge, den Grenzwert und die Belastung aus anderen, oft natürlichen Quellen. Alarmismus wie reflexhaftes Abwiegeln überspringen genau diese Prüfung. Woher der Stoff in das Produkt kam, ändert nichts daran, ob die vorhandene Menge gefährlich ist. Ob die Schäden zuerst bei Tieren oder Menschen beobachtet wurden, beantwortet ebenfalls nicht, wie viel hier gefunden wurde. Und der Ruf einer Redaktion ersetzt nicht die Zahlen, die in der Meldung fehlen.","coreRule":"⚡ Die Anwesenheit eines Stoffs sagt nichts über Gefahr. Entscheidend ist die Menge im Verhältnis zur Schwelle.","quote":"","quoteLabel":"","scenario":"","kurz":"Ob ein Stoff schadet, hängt von der Menge ab, nicht von seiner bloßen Anwesenheit. Erst gefundene Menge, Grenzwert und Vergleichswerte machen aus „nachgewiesen“ eine Aussage über Gefahr.","prueffrage":"Würde dieselbe Meldung dich beunruhigen, wenn der nachgewiesene Stoff Kochsalz wäre, das in großen Mengen ebenfalls schadet?","rueckmeldung":[{"option":0,"text":"Woher der Stoff stammt, ist eine berechtigte Frage, etwa für die Verantwortung des Herstellers. Ob die vorhandene Menge gefährlich ist, ändert sich dadurch aber nicht, und genau diese Menge fehlt in der Meldung."},{"option":2,"text":"Wie sich Leberschäden durch den Stoff zuerst gezeigt haben, erzählt etwas über die Forschungsgeschichte. Wie viel davon in den Haferflocken steckt, erfährst du damit nicht, und die Menge ist hier der entscheidende Punkt."},{"option":3,"text":"Eine Redaktion mit Hang zum Alarm ist ein Grund für Vorsicht beim Lesen. Die Zahlen, die der Meldung fehlen, liefert dieser Blick auf ihre Vorgeschichte aber nicht, und ohne sie bleibt das Urteil offen."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Grandjean, P. (2016): Paracelsus Revisited: The Dose Concept in a Complex World. Basic & Clinical Pharmacology & Toxicology 119(2), 126–132","oeffentlich":true,"doi":"10.1111/bcpt.12622","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4942381/","abruf":"2026-10-12"},{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"},{"typ":"url","kurz":"Paracelsus (1538): Sieben Defensiones, hg. Sudhoff 1915 (Digitalisat Wellcome Collection), dritte Defension","oeffentlich":true,"url":"https://wellcomecollection.org/works/jxt2qtp7","seite":"25","abruf":"2026-10-08"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"739eb560d9774c77"}},{"id":"qc-15","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.8","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Er unterstellt, dass die Selektion Herzinfarkte mit 70 voll gewichtet, obwohl sie am Fortpflanzungserfolg ansetzt, den diese Spätfolgen kaum noch berühren.","Er unterstellt, dass die Selektion schädliche Gene restlos entfernt, obwohl sie solche Gene nur langsam seltener macht und Reste davon lange erhalten bleiben.","Er unterstellt, dass das Gen schon lange verbreitet ist, obwohl die Selektion womöglich schlicht noch nicht genug Zeit hatte, es wieder auszusortieren.","Er sucht nach einem Nutzen für die Alten, obwohl die Selektion dem Erhalt der Art dient und die Alten den Jungen Platz machen sollen, sodass ein Schaden im Alter passt."],"correctIndex":0,"explanation":"Die natürliche Selektion optimiert den Fortpflanzungserfolg, nicht die Lebensspanne. Ein Gen, das früh Nachkommen begünstigt und erst nach der Fertilitätsphase schadet, wird kaum „bestraft“: Seine späten Kosten fallen für den Fortpflanzungserfolg wenig ins Gewicht, sein früher Nutzen zählt voll. Dieses Muster heißt antagonistische Pleiotropie. Ein verborgener Nutzen im Alter ist also gar nicht nötig, um das Fortbestehen des Gens zu erklären. Altern erscheint hier als Nebenwirkung evolutionärer Kurzsichtigkeit, nicht als Ziel der Selektion. Zu prüfen ist stets, auf welchen Zeitraum sich ein „Das hätte die Evolution aussortiert“ überhaupt stützen kann. Hinweis: Ob es beim Menschen ein zweifelsfrei belegtes Gen dieser Art gibt, ist offen; belegt ist das Muster an Hefe, Würmern, Fliegen und Mäusen. Die Denkfigur der Frage bleibt davon unberührt. Sein Fehler liegt in der Annahme, die Selektion bewerte auch späte Schäden voll.","coreRule":"⚡ Selektion zählt den Fortpflanzungserfolg, nicht die Lebensspanne – „Warum hat die Evolution das nicht aussortiert?“ setzt eine Bewertung voraus, die es so nicht gibt.","quote":"Evolution agiert als blinder Bastler: Sie nutzt „gut genug für jetzt“-Lösungen, ohne langfristige Kosten zu berücksichtigen.","quoteLabel":"Zum Weiterdenken:","scenario":"Ein Gen erhöht mit 20 Jahren die Fortpflanzungschancen und steigert mit 70 das Herzinfarktrisiko. Im Gespräch über das Altern sagt jemand dazu: „Wenn ein Gen im Alter Herzinfarkte auslöst, müsste die natürliche Selektion es längst aussortiert haben. Dass es noch da ist, zeigt, dass es einen verborgenen Nutzen für die Alten haben muss.“","beleg":"Werkstück C.4.8, Abschnitt „Evolutionäre Kurzsichtigkeit“; Austad & Hoffman 2018 (Fußnote gl-c-austad) zum Beleg an Modellorganismen und zur offenen Lage beim Menschen.","kurz":"Selektion setzt am Fortpflanzungserfolg an und bewertet späte Schäden daher kaum. Ein früh nützliches Gen bleibt, auch wenn es mit 70 schadet; ein verborgener Nutzen für die Alten ist gar nicht nötig.","prueffrage":"Wenn ein Träger dieses Gens mit 70 einen Herzinfarkt erleidet, was hat das Gen in seinem Leben bis dahin schon bewirkt?","rueckmeldung":[{"option":1,"text":"Dass Selektion schädliche Gene nicht restlos und nur langsam entfernt, stimmt. Das erklärt aber nicht, warum dieses Gen bleibt: Sein Schaden kommt spät, sein Nutzen früh, und das fällt bei der Selektion unterschiedlich ins Gewicht."},{"option":2,"text":"Zeitmangel kann bei manchen Genen tatsächlich eine Rolle spielen. Hier wäre aber auch beliebig viel Zeit kein Grund zum Aussortieren, denn die späten Kosten fallen für den Fortpflanzungserfolg kaum ins Gewicht, der frühe Nutzen dagegen voll."},{"option":3,"text":"Richtig ist, dass für das Gen kein Nutzen im Alter nötig ist. Die Begründung trägt aber nicht: Selektion dient nicht dem Erhalt der Art und plant keinen Platz für die Jungen ein. Sie wirkt nur über den Fortpflanzungserfolg des Einzelnen."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"65a4c480b1f559ac"}},{"id":"qc-16","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.10","stufe":4,"question":"Wie bewertest du den Schluss des Blogs im Licht der Leserantwort?","options":["Er scheitert, weil der Körper Energie aufnimmt und Wärme abgibt; als offenes System darf er Ordnung halten, Altern hat biologische Gründe.","Er trägt, weil auch die Verarbeitung der Nahrung Entropie erzeugt; die Zufuhr von außen gleicht den inneren Verfall also nicht vollständig aus.","Er trägt im Großen und Ganzen, weil der Zweite Hauptsatz allgemein gilt; die Hydra-Daten zeigen nur eine seltene Ausnahme von dieser Regel.","Er scheitert, weil die Hydra-Daten Altern bei einem Vielzeller widerlegen; Nahrung und Wärmeabgabe ändern an der Thermodynamik dagegen nichts."],"correctIndex":0,"explanation":"Der Zweite Hauptsatz sagt, dass die Gesamtentropie wächst, nicht dass jedes Teilsystem zerfallen muss. Ein offenes System darf seine Ordnung halten, solange es Energie aufnimmt und Entropie nach außen abgibt, und genau das tut der Körper mit Nahrung und Wärmeabgabe. Beim Süßwasserpolypen Hydra steigt die Sterblichkeit im Labor über Jahre nicht an; auch manche Einzellerklone halten offenbar als Kultur ihr gleichmäßiges Wachstum aufrecht. Dass Reparatur bei den meisten Lebewesen auf Dauer unvollständig bleibt, weil sie mit allem anderen um Energie konkurriert, ist ein biologischer Befund, kein Naturgesetz; der Blog schließt von einem Gesetz über das gesamte Universum auf ein Verbot für ein einzelnes offenes System.","coreRule":"⚡ Ordnung halten kostet Energie, ist aber nicht verboten: Prüfe bei Berufung auf ein Naturgesetz, ob es für das betrachtete System überhaupt gilt. Die Grenzen des Alterns sind biologisch, nicht thermodynamisch.","quote":"","quoteLabel":"","scenario":"Ein Wissenschaftsblog behauptet: „Jede Reparatur im Körper kostet Energie, und jede Energieumwandlung erhöht die Entropie des Universums. Nach dem Zweiten Hauptsatz der Thermodynamik kann ein Organismus deshalb gar nicht dauerhaft intakt bleiben, Altern ist ein Naturgesetz.“ Ein Leser antwortet: Der Körper nehme täglich Nahrung auf und gebe Wärme ab. Außerdem steige beim Süßwasserpolypen Hydra die Sterblichkeit im Labor über Jahre nicht an, auch wenn dort einzelne Tiere sterben.","kurz":"Der Zweite Hauptsatz verlangt, dass die Gesamtentropie wächst, nicht dass jedes Teilsystem zerfällt. Der Körper nimmt Energie auf und gibt Entropie als Wärme ab, kann also Ordnung halten; Altern hat biologische Gründe.","prueffrage":"Welche Annahme über den Körper steckt im Schluss des Blogs, und lässt sie sich mit Nahrungsaufnahme und Wärmeabgabe vereinbaren?","rueckmeldung":[{"option":1,"text":"Dass die Verdauung Entropie erzeugt, stimmt. Das gilt aber für die Gesamtbilanz; ein offenes System kann diese Entropie abgeben und innen Ordnung halten. Dass Reparatur oft unvollständig bleibt, ist ein biologischer Befund, kein Gesetz."},{"option":2,"text":"Der Zweite Hauptsatz gilt tatsächlich allgemein, aber für die Gesamtentropie, nicht als Verbot für jedes Teilsystem. Die Hydra ist daher keine Ausnahme von ihm, sondern zeigt, dass dauerhafte Ordnung im Prinzip möglich ist; auch manche Einzellerklone halten durch."},{"option":3,"text":"Dass die Hydra gegen ein Naturgesetz des Alterns spricht, stimmt. Altern ist bei den meisten Lebewesen aber real; die Hydra widerlegt es nicht allgemein. Und Nahrung und Wärmeabgabe sind gerade der Grund, warum die Thermodynamik keine Ordnungserhaltung verbietet."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Schaible u. a. 2015, Constant mortality and fertility over age in Hydra, PNAS 112(51) (PMC4697432)","oeffentlich":true,"doi":"10.1073/pnas.1521002112","abruf":"2026-10-12"},{"typ":"doi","kurz":"Wang u. a. 2010, Robust Growth of Escherichia coli, Current Biology 20(12) (PMC2902570)","oeffentlich":true,"doi":"10.1016/j.cub.2010.04.045","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams 1957, Pleiotropy, natural selection, and the evolution of senescence, Evolution 11(4)","oeffentlich":false,"doi":"10.1111/j.1558-5646.1957.tb02911.x"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"fb695c27a8db2330"}},{"id":"qc-17","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.11","stufe":2,"question":"Eine Forscherin liest: „Grönlandhaie leben im eiskalten Nordatlantik und werden mehrere Jahrhunderte alt. Das Wasser ist also die Ursache für das lange Leben.“ Welcher Einwand prüft diesen Schluss am besten?","options":["Es fehlt der Vergleich: Man müsste wissen, ob verwandte Haie in wärmerem Wasser kürzer leben und ob die Kälte über einen langsameren Stoffwechsel wirken könnte, statt nur gleichzeitig vorzukommen.","Es fehlt die Quellenprüfung: Man müsste wissen, wer die Altersschätzungen der Grönlandhaie veröffentlicht hat und ob unabhängige Fachleute die Arbeit begutachtet haben, bevor man ihr Ergebnis weiterverwendet.","Es fehlt die Angabe zur Stichprobe: Man müsste wissen, wie viele Grönlandhaie untersucht wurden und ob zufällig ausgewählte Tiere gemessen wurden, statt nur besonders alte Tiere zu zählen.","Es fehlt die Genauigkeit der Schlagzeile: Man müsste klären, ob „fast unsterblich“ überhaupt stimmt, denn mehrere Jahrhunderte Lebensdauer sind noch keine Unsterblichkeit, auch nicht im kalten Wasser."],"correctIndex":0,"explanation":"Dass zwei Dinge zusammen auftreten (kaltes Wasser, hohes Alter), beweist noch keinen ursächlichen Zusammenhang. Ein starker Test ist der Vergleich: Leben nahe verwandte oder ähnlich gebaute Tiere in wärmerem Wasser kürzer? Zusätzlich braucht es einen plausiblen Mechanismus: Chemische Reaktionen laufen bei niedriger Temperatur langsamer ab, also auch der Stoffwechsel wechselwarmer Tiere, und ein verlangsamter Stoffwechsel gilt als einer der Hauptgründe für das hohe Alter des Grönlandhais. Die anderen Einwände sind für sich sinnvoll, prüfen aber nicht den Schluss von der Kälte auf das lange Leben: Quelle und Stichprobe betreffen die Verlässlichkeit der Altersangaben, nicht die Frage nach der Ursache. Und die Übertreibung in der Schlagzeile ändert nichts daran, ob Kälte und hohes Alter ursächlich zusammenhängen.","coreRule":"⚡ Aus „zusammen aufgetreten“ folgt noch keine Ursache: Prüfe Vergleichsfälle und frage nach einem Mechanismus, der zur Ursache passt.","quote":"Chemische Reaktionen laufen bei höheren Temperaturen schneller ab.","quoteLabel":"Merksatz:","scenario":"Eine Schlagzeile zu Grönlandhaien: „Kaltes Wasser macht Haie fast unsterblich.“ Der Artikel stützt sich darauf, dass die Tiere in Wassertemperaturen knapp über dem Gefrierpunkt leben und Altersschätzungen von mehreren Jahrhunderten vorliegen.","kurz":"Dass kaltes Wasser und hohes Alter zusammen auftreten, zeigt noch keine Ursache. Erst der Vergleich mit Verwandten in wärmerem Wasser und ein plausibler Mechanismus wie ein langsamerer Stoffwechsel stützen den Schluss.","prueffrage":"Was außer dem kalten Wasser zeichnet Grönlandhaie noch aus, das ihr langes Leben ebenso erklären könnte?","rueckmeldung":[{"option":1,"text":"Die Herkunft der Altersschätzungen zu prüfen ist grundsätzlich klug. Sie betrifft aber nur, wie verlässlich die Zahlen sind, nicht, ob die Kälte das lange Leben verursacht. Diese Frage bliebe auch bei bester Quelle offen."},{"option":2,"text":"Wie viele Tiere untersucht wurden, ist für die Verlässlichkeit der Altersangaben wichtig. Ob die Kälte das hohe Alter bewirkt, klärt das aber nicht; dafür fehlt der Blick auf andere Haie und auf einen möglichen Wirkungsweg."},{"option":3,"text":"Zu Recht fällt „fast unsterblich“ auf: Mehrere Jahrhunderte sind keine Unsterblichkeit. Das trifft aber die Schlagzeile, nicht den Schluss der Forscherin, und ändert nichts an der offenen Frage, ob Kälte und hohes Alter ursächlich zusammenhängen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Ste-Marie u. a. 2020, A first look at the metabolic rate of Greenland sharks (Somniosus microcephalus) in the Canadian Arctic, Scientific Reports 10 (PMC7653932)","oeffentlich":true,"doi":"10.1038/s41598-020-76371-0","abruf":"2026-10-12"},{"typ":"url","kurz":"Nielsen u. a. 2016, Eye lens radiocarbon reveals centuries of longevity in the Greenland shark, Science 353 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1126/science.aaf1703","url":"https://pubmed.ncbi.nlm.nih.gov/27516602/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"dfd81e83b1a5ba73"}},{"id":"qc-18","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.1","stufe":1,"question":"Ein Politiker hält an einem eiskalten Wintertag einen Schneeball in die Kamera und erklärt, die globale Erwärmung sei damit widerlegt. Was ist an seinem Argument fehlerhaft?","options":["Er schließt von der Kälte eines Wintertags an einem Ort auf den langfristigen globalen Durchschnitt und verwechselt damit Wetter mit Klima.","Er überzieht seinen Befund, denn ein eiskalter Tag schwächt die These der Erwärmung zwar, reicht für sich allein aber nicht aus, um sie zu widerlegen.","Er wählt einen zu kleinen Ausschnitt, denn hätte er am selben Tag Kältewerte aus vielen Ländern gezeigt, wäre sein Einwand ernster zu nehmen.","Er wählt einen zu kurzen Zeitraum, denn hätte er über mehrere kalte Wochen hinweg Schneebälle gezeigt, wäre sein Einwand ernster zu nehmen."],"correctIndex":0,"explanation":"Wetter ist der kurzfristige, chaotische Zustand der Atmosphäre an einem Ort, Klima der statistische Durchschnitt über Jahrzehnte (üblicherweise etwa 30 Jahre). Ein Bild dafür: Ein Hund an der Leine läuft wild hin und her, der Spaziergänger geht trotzdem stetig in eine Richtung. Wer nur fünf Sekunden auf den Hund schaut, kann den Weg des Spaziergängers nicht beurteilen. Genauso sagt ein einzelner kalter Tag so wenig über den Klimatrend aus wie ein einzelner warmer Tag. Auch eine sich erwärmende Welt hat weiterhin kalte Tage und harte Kälteeinbrüche; sie werden nur seltener und milder, während Hitzewellen häufiger und heftiger werden.","coreRule":"⚡ Ein einzelner Tag ist Wetter, kein Klimatrend: Prüfe, ob eine Beobachtung für den langfristigen Durchschnitt repräsentativ ist.","quote":"Ein einzelner kalter Tag sagt genauso wenig über den Klimatrend aus wie ein einzelner warmer Tag.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück C.5.1 (Das Klimasystem), Abschnitt „Kontext & Tiefe“ und Fußnote gl-c-ipcc-extreme (IPCC 2021, SPM A.3.1/A.3.2)","kurz":"Ein kalter Tag an einem Ort ist Wetter, das Klima ist der Durchschnitt über Jahrzehnte. Der Fehler: Aus einer kurzen lokalen Momentaufnahme wird auf den langfristigen globalen Trend geschlossen. Kältetage gibt es auch in einer sich erwärmenden Welt.","prueffrage":"Wie war das Wetter am selben Tag in anderen Teilen der Erde, etwa auf der Südhalbkugel, wo dann Sommer ist?","rueckmeldung":[{"option":1,"text":"Dass ein einzelner Tag eine These nicht widerlegt, stimmt. Er schwächt sie aber auch nicht ein wenig, denn über den Trend sagt ein Kältetag so wenig wie ein Hitzetag. Das Problem ist die Art der Evidenz, nicht ihr Gewicht."},{"option":2,"text":"Ein einzelner Ort ist tatsächlich ein sehr enger Ausschnitt. Aber auch Kältewerte aus vielen Ländern am selben Tag wären nur eine Momentaufnahme, also Wetter. Für Klima fehlt weiterhin die Zeitspanne."},{"option":3,"text":"Ein längerer Zeitraum wäre der richtige Ansatz, doch einige kalte Wochen sind immer noch Witterung. Klima ist der Durchschnitt über Jahrzehnte, etwa 30 Jahre. Wochen liegen weit darunter."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"},{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"24a3379eef359c7b"}},{"id":"qc-19","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.3","stufe":2,"question":"Was ist an diesem Argument fehlerhaft?","options":["Der Schluss setzt voraus, dass die Lebensdauer der Streifen allein am Flugzeug liegt, und lässt außer Acht, dass die Luft in Flughöhe unterschiedlich feucht sein kann.","Der Schluss stützt sich nur auf zwei Beobachter und lässt außer Acht, dass erst viele übereinstimmende Beobachtungen an verschiedenen Orten den Verdacht begründen könnten.","Der Schluss setzt voraus, dass versprühte Chemikalien Streifen länger sichtbar halten, und lässt außer Acht, dass er gar nicht erklärt, wie sie das bewirken sollten.","Der Schluss kennt nur zwei Möglichkeiten, Kondensstreifen oder Chemikalien, und lässt außer Acht, dass langlebige Streifen noch ganz andere Ursachen haben könnten."],"correctIndex":0,"explanation":"Der Schluss behandelt „schnelles Verschwinden“ als Normalfall und jede Abweichung als Beweis für Eingriff von außen. Bei der Verbrennung im Triebwerk entstehen vor allem CO₂ und Wasserdampf; der Wasserdampf gefriert in großer Höhe zu Eiskristallen. Ob diese Kristalle schnell verschwinden oder wachsen, hängt von der Feuchtigkeit der Umgebungsluft ab: In trockener Luft lösen sie sich rasch auf, in eisübersättigter Luft bleiben sie stundenlang und breiten sich aus. Die Luftfeuchte in zehn Kilometern Höhe ist aber unsichtbar und wechselt von Tag zu Tag. Wer sie nicht kennt, kann aus der Dauer der Streifen nichts über Chemikalien ableiten. Auch die Gittermuster brauchen keine Absicht: Auf viel beflogenen Luftstraßen kreuzen sich die Routen, und bei passendem Wetter bleiben die Streifen unterschiedlicher Flugzeuge nebeneinander sichtbar. Das Wetter erklärt die Beobachtung einfacher als ein geheimes Programm, das viele Mitwissende bräuchte (Ockhams Rasiermesser).","coreRule":"⚡ Die Variation im Aussehen der Streifen ist ein Abbild des unsichtbaren Wetters in der Höhe, kein Beleg für eine geheime Zutat. Bevor du Absicht annimmst, frage nach der einfachsten Erklärung.","quote":"","quoteLabel":"","scenario":"Zwei Menschen sehen am Himmel lange, sich ausbreitende Streifen, die sich zu einem Gittermuster kreuzen. Ihr Schluss: „Normale Kondensstreifen lösen sich nach Sekunden auf. Diese hier stehen stundenlang am Himmel. Also werden hier Chemikalien versprüht.“","kurz":"Wie lange ein Streifen bleibt, hängt von der unsichtbaren Luftfeuchte in Flughöhe ab: In trockener Luft verschwindet er rasch, in eisübersättigter bleibt er stundenlang. Aus der Dauer allein auf Chemikalien zu schließen, übersieht diese gewöhnliche Erklärung.","prueffrage":"Bleiben die Streifen über derselben Gegend jeden Tag gleich lange stehen, obwohl dort Tag für Tag ähnliche Flugzeuge fliegen?","rueckmeldung":[{"option":1,"text":"Mehr übereinstimmende Beobachtungen würden den Eindruck tatsächlich festigen. Sie änderten aber nichts am Fehler: Alle sähen dieselben Streifen, und solange die Luftfeuchte unbeachtet bleibt, bliebe der Schluss auf Chemikalien ebenso unbegründet."},{"option":2,"text":"Dass kein Mechanismus genannt wird, ist eine echte Lücke im Argument. Sie berührt aber nicht den Kern: Selbst mit einem Mechanismus bliebe die einfachere Erklärung durch das Wetter unbeachtet, die das Argument gar nicht prüft."},{"option":3,"text":"Dass das Argument nur zwei Möglichkeiten zulässt, stimmt. Die Option bleibt aber vage: Sie nennt nicht die Ursache, auf die es ankommt, nämlich die wechselnde Luftfeuchte in Flughöhe, die langlebige Streifen ganz ohne Chemikalien erklärt."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schumann, U. (1996): On conditions for contrail formation from aircraft exhausts. Meteorologische Zeitschrift 5(1), 4–23 (doi 10.1127/metz/5/1996/4)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"2eb5fefcd5058057"}},{"id":"qd-1","status":"entwurf","clusterId":"D","werkstueckRef":"D.1.1","stufe":1,"question":"Ein Epidemiologe legt Daten zur Wirksamkeit einer Impfung vor. Jemand entgegnet: „Was weiß der schon? Der fährt einen dicken Mercedes und ist arrogant!“ Was ist an dieser Entgegnung das Kernproblem?","options":["Sie greift die Person an, ohne die vorgelegten Daten inhaltlich zu prüfen","Sie schlägt einen unhöflichen Ton an, der ein sachliches Gespräch erschwert","Sie behauptet Dinge über den Epidemiologen, ohne sie ihrerseits zu belegen","Sie misst ihn an seinem Lebensstil statt an seiner fachlichen Qualifikation"],"correctIndex":0,"explanation":"Die logische Gültigkeit eines Arguments hängt nie von den Eigenschaften der Person ab, die es ausspricht. Ein Epidemiologe kann arrogant sein und trotzdem korrekte Zahlen vorlegen. Die Entgegnung wechselt von der Sachebene auf die persönliche Ebene und lässt die Daten unberührt. Dieses Ausweichen heißt Ad hominem („gegen den Menschen“). Ein Argument muss nach seiner eigenen Stimmigkeit und den Beweisen bewertet werden, die es stützen.","coreRule":"⚡ Trenne die Botschaft vom Boten: Prüfe das Argument, nicht den Sprecher.","quote":"","quoteLabel":"","scenario":"","kurz":"Ob Daten stimmen, hängt nicht davon ab, wer sie vorlegt: Auch ein arroganter Epidemiologe kann richtige Zahlen haben. Die Entgegnung wechselt von der Sache auf die Person und lässt die Daten unberührt.","prueffrage":"Welche Wörter der Entgegnung beziehen sich auf die Impfung oder die Daten, und welche auf etwas anderes?","rueckmeldung":[{"option":1,"text":"Der Ton ist tatsächlich unhöflich, aber auch eine freundliche Entgegnung könnte an den Daten vorbeigehen. Das Kernproblem liegt nicht in der Wortwahl, sondern darin, dass die Sachebene verlassen wird."},{"option":2,"text":"Belegt sind die Behauptungen über den Epidemiologen tatsächlich nicht. Selbst wenn sie zuträfen, sagten sie über die Daten nichts aus, und genau darin liegt das Problem."},{"option":3,"text":"Der Lebensstil ist ein unpassender Maßstab, das stimmt. Aber auch die fachliche Qualifikation ersetzt nicht die Prüfung der Daten, denn entscheidend bleiben Zahlen und Belege selbst."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Ad Hominem)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Walton, D. (1998): Ad Hominem Arguments. Tuscaloosa: University of Alabama Press","oeffentlich":false,"seite":"S. xiv–xv (laut Landkarte-Fußnote gl-d-fehlschluss)"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"101ec62cbc48d6c2"}},{"id":"qd-2","status":"entwurf","clusterId":"D","werkstueckRef":"D.1.3","stufe":1,"question":"Was ist an der Aussage fehlerhaft, und wie reagierst du am besten?","options":["Sie lässt nur zwei Extreme zu und verschweigt Zwischenwege; du fragst, welche weiteren Positionen es gibt, etwa Zustimmung zum Ziel bei Kritik an Maßnahmen.","Sie lässt nur zwei Extreme zu; du sicherst dem Sprecher deine Unterstützung zu, weil du das Ziel teilst, und bringst deine Zweifel an Maßnahmen später vor.","Sie arbeitet mit dem aufgeladenen Wort „Feind“; du bittest den Sprecher, sachlicher zu formulieren, damit ruhig über die Initiative gesprochen werden kann.","Sie verlangt volle Zustimmung ohne Begründung; du fragst nach Belegen dafür, dass die geplanten Maßnahmen wirken, bevor du dich für eine Seite entscheidest."],"correctIndex":0,"explanation":"Der Sprecher präsentiert eine komplexe Lage als Entweder-oder: volle Zustimmung oder Feindschaft. Dass man das Ziel teilen und einzelne Maßnahmen dennoch kritisieren oder verbessern kann, kommt nicht vor; Kritik an einem Teil wird so automatisch als Ablehnung des Ganzen gedeutet. Das ist ein falsches Dilemma. Am besten sprengst du den Rahmen: Du fragst nach den Optionen, die fehlen, und nennst selbst mindestens eine, etwa „Ziel ja, diese Maßnahme überarbeiten“. Ein echtes Dilemma gäbe es nur, wenn tatsächlich keine weiteren Möglichkeiten existierten.","coreRule":"⚡ Spreng den Rahmen: Frage nach den Optionen C, D und E!","quote":"Die Speisekarte des Tyrannen: Fauliger Fisch oder Glasscherben.","quoteLabel":"Bild zum Merken:","scenario":"In einer Bürgerversammlung über eine geplante Initiative sagt ein Sprecher: „Entweder du unterstützt unsere Initiative zu 100 %, oder du bist ein Feind der Gerechtigkeit!“ Du hältst das Ziel für richtig, hast aber Zweifel an einzelnen Maßnahmen.","beleg":"Werkstück D.1.3, Abschnitte „Kernidee“, „Red Flags“, „Anti-Denkmuster“ (Parabel „Speisekarte des Tyrannen“)","kurz":"Der Sprecher macht aus einer vielschichtigen Lage ein Entweder-oder und deutet Kritik an Maßnahmen als Ablehnung des Ganzen. Du sprengst den Rahmen, indem du nach den fehlenden Positionen fragst und selbst eine nennst, etwa „Ziel ja, diese Maßnahme überarbeiten“.","prueffrage":"Welche der Möglichkeiten im Satz des Sprechers beschreibt deine eigene Haltung zu Ziel und Maßnahmen?","rueckmeldung":[{"option":1,"text":"Dass du das Ziel teilst, ist wichtig, und das Problem des Satzes erkennst du auch. Mit deiner Zusicherung spielst du aber nach seinen Regeln, und Kritik gilt weiter als Feindschaft. Die fehlenden Positionen bleiben unausgesprochen, solange du sie nicht nennst."},{"option":2,"text":"Das Wort „Feind“ ist tatsächlich scharf, und ein ruhigerer Ton hilft jedem Gespräch. Selbst in sachlichen Worten bliebe aber das Entweder-oder bestehen, und das ist der eigentliche Fehler: Kritik an einzelnen Maßnahmen hätte weiterhin keinen Platz."},{"option":3,"text":"Nach Belegen zu fragen ist grundsätzlich gut. Hier führt es aber am Kern vorbei: Das Problem ist nicht fehlende Begründung, sondern dass nur zwei Möglichkeiten zur Wahl stehen. Wer sich „für eine Seite entscheidet“, übernimmt diese Einteilung, statt sie infrage zu stellen."}],"familie":"falsches-dilemma","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge False Dilemma, Black-or-White)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"94c3bdebba93c69d"}},{"id":"qd-3","status":"entwurf","clusterId":"D","werkstueckRef":"D.2.5","stufe":3,"question":"Zwei Zeitungsberichte über dieselbe Stadt enthalten identische Kriminalzahlen. Nur der erste Satz unterscheidet sich: Bericht A nennt Kriminalität „ein wildes Tier, das die Stadt heimsucht“, Bericht B nennt sie „ein Virus, das die Stadt infiziert“. Leser von A fordern danach deutlich häufiger Polizei und Gefängnisse, Leser von B häufiger Prävention und Sozialreformen. Gefragt, was ihr Urteil geprägt habe, nennen fast alle die Zahlen. Welche Erklärung ist am sparsamsten?","options":["Das Bild legt unbemerkt fest, welche Lösungen naheliegend wirken, und die Leser schreiben ihr Urteil trotzdem den Zahlen zu.","Die Leser erleben das Bild als Bevormundung und urteilen aus Trotz entgegengesetzt dazu, nennen aber trotzdem die Zahlen.","Das Bild macht die Gefahr greifbar, und Greifbares halten Menschen für häufiger; die Leser schätzen die Lage verschieden ein.","Die Leser deuten die Zahlen im Sinn ihrer schon vorhandenen Haltung, und diese Haltung unterscheidet die beiden Lesergruppen."],"correctIndex":0,"explanation":"Die Zahlen sind in beiden Berichten identisch, also können sie den Unterschied nicht erklären. Ein einzelnes Bild genügt, um den Raum der als plausibel empfundenen Lösungen zu verschieben: Ein Tier verlangt Einsperren und Bekämpfen, ein Virus Diagnose und Heilung. Dass die Leser danach die Statistik als Grund nennen, passt dazu: Der Einfluss wirkt unbemerkt, deshalb suchen sie die Ursache dort, wo sie sie sehen können. Wichtig bleibt die Vorsicht beim Ausmaß: Spätere Studien fanden den Effekt kleiner oder gar nicht, sodass offen ist, wie robust er ist. Die anderen Erklärungen beschreiben echte Mechanismen, passen aber nicht zu den Angaben: Trotz gegen das Bild setzte voraus, dass die Leser es als Einfluss bemerken; in der Originalstudie von Thibodeau und Boroditsky (2011) nannten aber nur 15 von 485 Teilnehmenden die Metapher als einflussreich, und die Leser folgen dem Bild ja gerade. Dass ein Bild Gefahr greifbarer macht, erklärt höchstens verschiedene Häufigkeitsschätzungen, nicht die verschiedenen Lösungswünsche. Von einer schon vorhandenen, unterschiedlichen Haltung der Gruppen ist nichts bekannt; sie unterscheiden sich nur im Bild des ersten Satzes.","coreRule":"⚡ Wenn bei identischen Fakten das Urteil kippt, ist die Formulierung der Verdächtige, auch wenn niemand sie als Einfluss nennt.","quote":"Welches Bild benutzt dieser Text gerade -- und welche Lösung würde ich für naheliegend halten, wenn er stattdessen ein völlig anderes Bild benutzt hätte, bei identischen Fakten?","quoteLabel":"Prüffrage:","scenario":"","beleg":"Werkstück D.2.5; Fußnote gl-d-thibodeau; Anmerkung anm-gl-d-thibodeau (Experiment 1: 74% vs. 56%, 15 von 485 nennen die Metapher). Beleglage: Replikation Steen et al. 2014 ohne Effekt, Metaanalyse Brugman et al. 2019 nur schwach.","kurz":"Die Zahlen sind identisch, also erklärt allein das Bild im ersten Satz den Unterschied: Es lässt andere Lösungen naheliegend wirken. Weil der Einfluss unbemerkt bleibt, suchen die Leser den Grund in den Zahlen, wie groß der Effekt ist, bleibt offen.","prueffrage":"Worin unterscheiden sich die beiden Berichte tatsächlich, und worin nicht?","rueckmeldung":[{"option":1,"text":"Trotz gegen ein Bild setzt voraus, dass man es als Einflussnahme bemerkt. Hier folgen die Leser dem Bild aber gerade, und sie nennen die Zahlen als Grund, nicht das Bild. Der Trotz hätte sie in die Gegenrichtung getrieben."},{"option":2,"text":"Greifbarkeit kann tatsächlich Schätzungen verändern, etwa wie häufig etwas vorkommt. Gemessen wurde hier aber etwas anderes: welche Lösungen die Leser wollen. Dass sie die Lage verschieden einschätzen, steht im Szenario nirgends."},{"option":3,"text":"Bestehende Haltungen färben Urteile oft tatsächlich. Nur ist von einer unterschiedlichen Haltung der beiden Gruppen nichts bekannt: Sie unterscheiden sich allein im ersten Satz. Diese Erklärung bräuchte also eine zusätzliche Annahme, die nicht gegeben ist."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"dc89681413df2939"}},{"id":"qd-4","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.2","stufe":2,"question":"Bei Gegenwind wird die radikale Aussage „Unsere Methode heilt jede Krankheit“ plötzlich zu „Ich sage ja nur, dass eine positive Einstellung beim Heilen hilft“. Kaum lässt du die Kritik fallen, wiederholt er die Ausgangsbehauptung wie zuvor. Welche Reaktion ist die klügste?","options":["Du erklärst ihm geduldig, wie kontrollierte Studien mit Vergleichsgruppen funktionieren, damit er versteht, warum die Methode Belege braucht.","Du schlägst einen Kompromiss vor: Vielleicht heilt die Methode nicht jede Krankheit, aber doch manche, und darauf könnt ihr euch einigen.","Du stimmst der vernünftigen zweiten Aussage zu und fragst dann, ob er weiter dazu steht, dass die Methode jede Krankheit heilt.","Du fragst zuerst, welche Studien die zweite Aussage stützen, und stimmst ihr erst zu, wenn er sie vorlegt, bevor ihr weiterredet."],"correctIndex":2,"explanation":"Die zweite Aussage ist harmlos und weithin akzeptiert, die erste ist außergewöhnlich und nicht belegt. Beide sind nicht dasselbe, denn aus „Einstellung kann beim Heilungsprozess helfen“ folgt nicht „Die Methode heilt jede Krankheit“. Wer bei Kritik auf die harmlose Aussage ausweicht und später zur kühnen zurückkehrt, nutzt die Zustimmung zur einen, um die andere unbemerkt durchzubringen. Das ist die Motte-and-Bailey-Täuschung (so benannt von Nicholas Shackel 2005): eine schwer zu verteidigende Vorburg und ein leicht zu verteidigender Turmhügel, zwischen denen man hin- und herwechselt. Die klügste Reaktion trennt beide Aussagen sauber: Du stimmst dem Vernünftigen zu, ohne dass daraus Zustimmung zum Radikalen wird, und bringst das Gespräch auf die ursprüngliche Behauptung zurück. So muss er sich festlegen. Die anderen Reaktionen sind in anderer Lage sinnvoll, passen hier aber nicht: Eine Erklärung kontrollierter Studien hilft, wenn jemand sie nicht kennt, nicht wenn er ausweicht. Ein Kompromiss würde der unbelegten Aussage ein Stück Wahrheit zugestehen, das sie nie belegt hat. Und für die unstrittige zweite Aussage Belege zu verlangen, beendet das Ausweichen nicht.","coreRule":"⚡ Stimme der harmlosen Aussage zu, aber kehre zur ursprünglichen, kühnen Behauptung zurück: Lass den Gegner nicht in den Fluchtturm entwischen.","quote":"Lass uns zur ursprünglichen, viel stärkeren („Bailey“) Aussage zurückkehren, die du zu Beginn gemacht hast. Stehst du immer noch zu dieser?","quoteLabel":"Merksatz","scenario":"Du diskutierst mit einem Anhänger einer spirituellen Bewegung. Er behauptet: „Unsere Methode kann jede Krankheit heilen, Krebs und AIDS eingeschlossen.“ Du fragst nach kontrollierten Studien. Daraufhin sagt er: „Was ich eigentlich meinte: Eine positive Einstellung und spirituelles Wohlbefinden sind wichtig für den Heilungsprozess.“ Dem stimmst du zu, und prompt erklärt er wieder, seine Methode heile jede Krankheit.","kurz":"Der vernünftigen Aussage kannst du zustimmen. Daraus folgt aber nichts für die erste. Weil Zustimmung zur einen schnell als Zustimmung zur anderen gilt, trennst du beide sauber und kehrst zur Ausgangsbehauptung zurück. So muss er sich festlegen.","prueffrage":"Behauptet er am Ende des Gesprächs dasselbe wie am Anfang, oder hat sich zwischendurch etwas verschoben?","rueckmeldung":[{"option":0,"text":"Wie Studien funktionieren, zu erklären ist nützlich, wenn jemand sie nicht kennt. Hier wurde aber schon nach ihnen gefragt, und er ist ausgewichen. Das Problem ist der Wechsel zwischen den Aussagen, nicht fehlendes Wissen."},{"option":1,"text":"Ein Kompromiss wirkt fair, weil man sich in der Mitte trifft. Er gesteht aber einer unbelegten Aussage ein Stück Wahrheit zu, das sie nie belegt hat, und „manche“ ist genauso ungestützt wie „jede“. Zudem muss er sich weiter nicht festlegen."},{"option":3,"text":"Belege zu fordern ist grundsätzlich richtig. Für die zweite Aussage sind sie aber kaum nötig, weil sie weithin akzeptiert ist. Der Streitpunkt ist die erste, und dort bringt die Forderung hier nichts, solange er zwischen beiden hin- und herspringen kann."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3), 295–320","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"51bbcc8cf3c2c129"}},{"id":"qd-5","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.8","stufe":2,"question":"Eine Rednerin stellt eine Theorie vor, die alle Fachleute für falsch halten. Auf die Kritik antwortet sie: „Über Galilei und Semmelweis haben die Leute damals auch gelacht. Also muss an meiner Theorie etwas dran sein!“ Was ist an diesem Schluss fehlerhaft?","options":["Der Schluss ist umgekehrt: Dass manche Entdecker zunächst abgelehnt wurden, heißt nicht, dass jeder Abgelehnte ein Entdecker ist; abgelehnt wurden auch unzählige Irrtümer.","Der Schluss ist ein Autoritätsargument: Die Rednerin leiht sich das Ansehen von Galilei und Semmelweis, um ihrer eigenen, von den Fachleuten abgelehnten Theorie Gewicht zu geben.","Der Schluss ist eine schiefe Analogie: Galilei und Semmelweis lebten in einer ganz anderen Zeit, heute prüft die Wissenschaft neue Ideen deutlich offener als damals.","Der Schluss weicht der Sache aus: Die Rednerin geht auf die Einwände der Fachleute inhaltlich nicht ein, sondern lenkt mit Galilei und Semmelweis auf ein anderes Thema."],"correctIndex":0,"explanation":"Der Schluss kehrt eine Aussage ungültig um: Dass manche spätere Durchbrüche zunächst abgelehnt wurden, sagt nichts darüber, ob jede abgelehnte Idee ein Durchbruch ist. Abgelehnt wurden ebenso zahllose Ideen, die zu Recht verworfen blieben, nur erzählt von denen niemand. Für die Frage, ob eine These stimmt, ist „abgelehnt“ bei beiden Gruppen gleich und trägt deshalb keine Information. Galilei überzeugte, weil seine Beobachtungen (Venusphasen, Jupitermonde) jeder mit einem Fernrohr nachprüfen konnte, nicht weil er auf Widerstand stieß. Dass Fachleute sich irren können, ist richtig, rechtfertigt aber keine einzelne Außenseiter-These; dort entscheiden prüfbare Vorhersagen und Daten.","coreRule":"⚡ Ablehnung ist kein Beweis für Wahrheit: Wo ist dein Fernrohr?","quote":"","quoteLabel":"","scenario":"","kurz":"Dass manche spätere Durchbrüche zunächst abgelehnt wurden, macht nicht jede abgelehnte Idee zum Durchbruch: Abgelehnt wurden auch zahllose Irrtümer. Wer so schließt, kehrt die Aussage um, obwohl „abgelehnt“ bei beiden Gruppen vorkommt und nichts über Wahrheit verrät.","prueffrage":"Was hat die Rednerin mit Galilei und Semmelweis nachweislich gemeinsam, und was davon spricht für ihre Theorie?","rueckmeldung":[{"option":1,"text":"Dass berühmte Namen als Glanz geliehen werden, kann man hier beobachten. Die Rednerin behauptet aber nicht, Galilei oder Semmelweis würden ihre Theorie stützen; sie nutzt sie als Vergleich. Fehlerhaft ist der Schluss vom Abgelehntwerden auf Richtigkeit."},{"option":2,"text":"Dass Galilei und Semmelweis in einer anderen Zeit lebten, stimmt. Aber selbst bei gleichen Zeiten bliebe der Schluss ungültig: Abgelehnt wurden damals wie heute Durchbrüche und Irrtümer. Der Fehler liegt in der Umkehrung, nicht im Zeitabstand."},{"option":3,"text":"Die Rednerin geht auf die Einwände tatsächlich nicht ein, das ist ein Mangel ihrer Antwort. Der Schluss wäre aber auch bei sachlicher Erwiderung ungültig, denn „abgelehnt“ sagt über Durchbrüche und Irrtümer gleichermaßen nichts aus."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain: Reflections on the Romance of Science, Kap. 5 „Night Walkers and Mystery Mongers“","oeffentlich":false},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Affirming the Consequent“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b78cc3b436c4e0e4"}},{"id":"qd-6","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Was ist an diesem Austausch das Entscheidende?","options":["Die Nachfragen sind berechtigt: Lena hat öffentlich ein Urteil gefällt, und wer das tut, sollte es auf Nachfrage auch weiterhin belegen und genauer erläutern.","Die Nachfragen zeigen echtes Interesse: Der Nutzer bleibt höflich, also sollte Lena geduldig weiter antworten, bis alles geklärt ist.","Die Nachfragen sollen zermürben: Der Nutzer nutzt Höflichkeit und Beleg-Forderungen, und Lena schuldet ihm nach ihren Antworten keine weiteren Belege.","Die Nachfragen zeigen ein Missverständnis: Der Nutzer versteht nicht, was Lena mit „schlecht“ meint, also sollte sie ihr Urteil noch genauer erklären."],"correctIndex":2,"explanation":"Wer behauptet, muss belegen – aber einmal, nicht endlos. Ein ehrlich Fragender arbeitet mit der Antwort, prüft sie oder sagt, was ihn noch nicht überzeugt; hier folgt auf jede Antwort nur die nächste Forderung. Dieses Muster heißt Sealioning: Eine Frage kostet Sekunden, eine belegte Antwort oft Stunden, und so wird endloses Nachfragen für den Fragenden billig und für Lena teuer. Quellen zu verlangen ist berechtigt, solange mit den Antworten gearbeitet wird; eine Pflicht zur Dauerverteidigung folgt daraus nicht. Die Beweislast klingt nach einer Pflicht, die erst endet, wenn der Fragende zufrieden ist, doch Lena hat sie mit ihrer Verbraucherumfrage erfüllt. Ein Gish-Galopp klingt nach Überforderung, bräuchte aber eine Flut von Behauptungen, hier gibt es nur Fragen, eine nach der anderen. Dass der Nutzer eine Behauptung in Fragen verpackt, klingt nach Suggestion, doch er streut keine eigene These, sondern fordert immer Neues; die letzte Frage enthält zwar eine Unterstellung, trägt aber diese Wirkung nicht.","coreRule":"⚡ Grenze setzen: Du schuldest Belege für deine Behauptung einmal – danach erst wieder, wenn dein Gegenüber mit dem Beleg gearbeitet hat.","quote":"","quoteLabel":"","scenario":"Unter Lenas Beitrag über ihre schlechten Erfahrungen mit einem Paketdienst fragt ein Nutzer freundlich: „Hast du dafür eine Quelle?“ Lena nennt eine Verbraucherumfrage. Er antwortet: „Danke! Und eine zweite?“ Dann: „Was meinst du genau mit ‚schlecht'?“ Dann: „Warum wirst du jetzt unfreundlich?“ Auf keine ihrer drei Antworten geht er inhaltlich ein.","beleg":"Werkstück D.3.9, Fußnote gl-d-sealioning: Malki, D. (2014): „The Terrible Sea Lion“. Wondermark Nr. 1062; Johnson, A. (2017): „The Multiple Harms of Sea Lions“.","kurz":"Wer behauptet, muss belegen, aber einmal und nicht endlos. Hier folgt auf jede Antwort nur die nächste Forderung, ohne dass er mit ihr arbeitet. Das billige Fragen kostet Lena viel Zeit; Lena hat ihre Pflicht mit der Umfrage erfüllt.","prueffrage":"Was macht der Nutzer mit Lenas Antworten, bevor er die nächste Frage stellt?","rueckmeldung":[{"option":0,"text":"Wer öffentlich urteilt, muss das tatsächlich belegen können, und die erste Quellenfrage war berechtigt. Lena hat aber geliefert. Daraus folgt nicht, dass sie sich unbegrenzt weiter verteidigen muss, solange jemand noch eine Forderung nachlegt."},{"option":1,"text":"Höflichkeit allein zeigt noch kein echtes Interesse. Ein ehrlich Fragender greift die Antworten auf, prüft sie oder sagt, was ihn nicht überzeugt. Hier bleibt jede Antwort unbeachtet, und geduldiges Weiterantworten hätte deshalb kein Ende."},{"option":3,"text":"Eine Präzisierungsfrage kann berechtigt sein. Hier ist sie aber die dritte Forderung in Folge, und der Nutzer geht auch darauf nicht ein. Das Muster spricht für Zermürben, nicht für ein Missverständnis, das sich durch mehr Erklärung lösen ließe."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"},{"typ":"url","kurz":"Malki, D. (2014): „The Terrible Sea Lion“, Wondermark Nr. 1062","oeffentlich":true,"url":"https://wondermark.com/c/1062/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"9c159f76566b2594"}},{"id":"qd-7","status":"entwurf","clusterId":"D","werkstueckRef":"D (Kasten zu den Etiketten)","stufe":2,"question":"Wie bewertest du die Entgegnung der Kollegin am treffendsten?","options":["Ihr Einwand gegen das Sommer-Argument stimmt, ihr Schluss nicht: Die Erwärmung zeigen jahrzehntelange Messreihen.","Sie hat im Kern recht: Wenn das stärkste Argument ein heißer Sommer ist, steht die Erwärmung auf schwachen Füßen.","Sie urteilt zu streng: Ein einzelner Sommer reicht zwar nicht aus, ist aber ein Hinweis, der zur Erwärmung passt.","Sie macht denselben Fehler wie er: Auch sie zieht aus einem einzigen Sommer einen Schluss, nur in die andere Richtung."],"correctIndex":0,"explanation":"Die Kollegin hat recht, dass ein einzelner heißer Sommer Wetter ist: Das Argument des Kollegen stützt seine Schlussfolgerung nicht. Falsch wird die Schlussfolgerung dadurch aber nicht. Wer aus dem Fehler folgert, an der Erwärmung sei nichts dran, begeht selbst einen Fehlschluss, den sogenannten Fehlschluss-Fehlschluss. Auch ein Name für einen Denkfehler widerlegt noch nichts: Es kommt auf die Belege für die Schlussfolgerung selbst an, und das sind hier die langjährigen Messreihen, nicht ein einzelner Sommer.","coreRule":"⚡ Ein schlechtes Argument macht den Schluss nicht falsch: Prüfe die Schlussfolgerung getrennt vom Argument.","quote":"Ein Name für einen Denkfehler widerlegt noch nichts.","quoteLabel":"Merksatz:","kurz":"Der Einwand der Kollegin stimmt: Ein heißer Sommer ist Wetter und stützt den Schluss nicht. Aber ein schwaches Argument macht die Behauptung nicht falsch. Ob sich das Klima erwärmt, zeigen jahrzehntelange Messreihen.","prueffrage":"Woran würdest du erkennen, ob die Aussage auch dann belegt wäre, wenn man den Sommer ganz wegließe?","rueckmeldung":[{"option":1,"text":"Ein heißer Sommer ist als Beleg tatsächlich dünn. Die Erwärmung beruht aber gar nicht auf ihm, sondern auf jahrzehntelangen Messreihen; die Schwäche eines Arguments sagt nichts über seine Schlussfolgerung."},{"option":2,"text":"Ein einzelner Sommer ist Wetter und trägt die Schlussfolgerung nicht, deshalb ist ihr Einwand nicht zu streng. Offen bleibt, was aus dem Einwand folgt: Dass die Erwärmung „erledigt“ sei, jedenfalls nicht."},{"option":3,"text":"Sie zieht gerade keinen Schluss aus dem Sommer, sondern grenzt Wetter von Klima ab, und das stimmt. Ihr Fehler kommt danach: Sie folgert aus dem schwachen Argument, die Schlussfolgerung selbst sei widerlegt."}],"familie":"fehlschluss-macht-nichts-falsch","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Validity and Soundness“ (anonymer Verfasser)","oeffentlich":true,"url":"https://iep.utm.edu/val-snd/","abruf":"2026-10-12"},{"typ":"doi","kurz":"IPCC (2021): Summary for Policymakers. Climate Change 2021: The Physical Science Basis, WG I, AR6","oeffentlich":true,"doi":"10.1017/9781009157896.001","seite":"Abschnitt A.1.2","abruf":"2026-10-04"},{"typ":"literatur","kurz":"Novella, S. u. a. (2018): The Skeptics' Guide to the Universe, Kap. 10, Abschnitt „Fallacy Fallacy“ (E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Natur und Klima","scenario":"Beim Mittagessen sagt ein Kollege: „Schau dir diesen heißen Sommer an, der Klimawandel ist real!“ Eine Kollegin entgegnet: „Ein einzelner Sommer ist Wetter, nicht Klima. Damit ist das Gerede von der Erwärmung erledigt.“ Du weißt, dass sich die Aussage, das Klima erwärme sich, auf Messreihen über Jahrzehnte stützt."},{"id":"qd-8","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.8","stufe":3,"question":"Welche Antwort an den Redner ist im Licht deiner Recherche die stärkste?","options":["„Ihr Vergleich trägt nicht: Kolumbus wurde nicht verlacht, sondern mit Gründen abgelehnt, und das ist etwas anderes als Spott.“","„Ihr Vergleich trägt nicht: Ablehnung trifft Genies wie Irrtümer, und Kolumbus' Kritiker hatten mit dem zu breiten Ozean recht.“","„Ihr Vergleich trägt nicht: Kolumbus hat seine Rechnung geschönt und taugt daher wegen seiner Unredlichkeit nicht als Vorbild.“","„Ihr Vergleich trägt nicht: Kolumbus' Plan lehnte nur eine Kommission ab, Ihren lehnt die ganze Fachwelt ab, und das wiegt schwerer.“"],"correctIndex":1,"explanation":"Das Argument des Redners schließt von „Manche Genies wurden abgelehnt“ auf „Wer abgelehnt wird, ist ein Genie“. Das ist ein ungültiger Schluss: Auch über Bozo den Clown wurde gelacht (Carl Sagan). Dazu passt das Beispiel selbst nicht, wie deine Recherche zeigt: Die königliche Kommission unter Hernando de Talavera lehnte den Plan 1490 zwar ab, aber keiner ihrer Einwände stellte die Kugelgestalt der Erde in Frage. Sie hielt den Ozean für zu breit, und ihre Zweifel waren berechtigt, weil Kolumbus seine Rechnung geschönt hatte. Die Kritiker hatten also recht. Die Ablehnung durch Fachleute ist für echte Außenseiter und für Irrtümer dieselbe, sie ist daher kein Beleg; ein Beleg wäre eine prüfbare Vorhersage, die der Redner vorlegen müsste.","coreRule":"⚡ Ablehnung durch Fachleute ist kein Beweis: Sie trifft Genies und Irrtümer gleichermaßen, und die berühmten Beispiele stimmen oft nicht.","quote":"","quoteLabel":"","scenario":"Ein Redner sagt: „Mein Plan wird von allen Fachleuten abgelehnt. Das ist ein gutes Zeichen, denn auch Kolumbus wurde verlacht, und am Ende hatte er recht.“ Du schlägst nach: Eine königliche Kommission lehnte Kolumbus' Plan 1490 tatsächlich ab. Keiner ihrer Einwände bezweifelte die Kugelgestalt der Erde; sie hielt den Ozean für zu breit, und Kolumbus hatte seine Rechnung geschönt.","kurz":"Der Vergleich trägt nicht: Ablehnung trifft Genies wie Irrtümer gleichermaßen und belegt daher nichts. Außerdem passt das Beispiel nicht, denn Kolumbus' Kritiker hatten mit dem zu breiten Ozean recht. Der Fehler ist, aus „manche Genies wurden abgelehnt“ zu schließen, wer abgelehnt wird, sei eines.","prueffrage":"Worauf genau bezogen sich die Einwände gegen Kolumbus, und gab es sie auch bei Plänen, die scheiterten?","rueckmeldung":[{"option":0,"text":"Die Kommission lehnte tatsächlich mit Gründen ab, nicht mit Spott. Das ist aber nur eine Nebenfrage: Auch mit dem Wort „abgelehnt“ bliebe der Fehlschluss stehen, dass Ablehnung für den Redner spreche. Die Kernfrage ist, ob die Kritiker recht hatten."},{"option":2,"text":"Dass Kolumbus seine Rechnung schönte, stimmt und erklärt, warum die Zweifel berechtigt waren. Der Angriff auf seine Redlichkeit trifft aber den Schluss des Redners nicht: Auch mit einem ehrlichen Vorbild bliebe „abgelehnt, also genial“ unbelegt."},{"option":3,"text":"Eine Kommission gegen alle Fachleute klingt nach einem wichtigen Unterschied. Das ändert aber nichts am Kern: Ablehnung ist bei echten Außenseitern wie bei Irrtümern dieselbe, ob nun wenige oder viele ablehnen, und bleibt daher ohne Beweiskraft. Außerdem hat der Redner „alle“ nur behauptet."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Russell, J. B. (1991): Inventing the Flat Earth: Columbus and Modern Historians. New York: Praeger","oeffentlich":false},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain, Kap. 5 („Bozo the Clown“-Zitat)","oeffentlich":false},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Affirming the Consequent“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5533b420b3520a8b"}},{"id":"qd-9","status":"entwurf","clusterId":"D","werkstueckRef":"D (Einleitung, Prebunking)","stufe":4,"question":"Ein Medienbildungsprojekt wirbt: „Nach unseren kurzen Prebunking-Videos erkennen Menschen manipulative Tricks nachweislich besser.“ Ein Kollege antwortet: „Dann ist das Problem der Desinformation ja gelöst.“ Welche Reaktion wird der Sachlage am besten gerecht?","options":["Das Ergebnis ist nützlich, aber begrenzt: Ein Effekt von rund fünf Prozent, binnen eines Tages gemessen, rechtfertigt weder Triumph noch Abwinken.","Das Ergebnis ist ein klarer Erfolg: Ein Effekt von rund fünf Prozent, gestützt auf über 22.000 Antworten, ist gut gesichert und darf als Durchbruch gelten.","Das Ergebnis ist ernüchternd: Ein Effekt von rund fünf Prozent ist so klein, dass er kaum ins Gewicht fällt und den Aufwand für solche Videos kaum lohnt.","Das Ergebnis ist ein Teilerfolg: Wer manipulative Tricks besser erkennt, glaubt seltener Falschmeldungen, das Problem schrumpft also um etwa fünf Prozent."],"correctIndex":0,"explanation":"Wer Wirkung und Grenze zusammen nennt, urteilt am genauesten. Die Forschung zur Inokulation zeigt, dass sich das Erkennen solcher Techniken schulen lässt, aber nur in Grenzen: Im Feldversuch auf YouTube (22.632 Antworten, Roozenbeek u. a. 2022, Science Advances) stieg die Erkennung im Mittel um rund 5 % und verfehlte knapp die vorab festgelegte kleinste bedeutsame Effektgröße. „Messbar“ heißt also nicht „groß“, und „klein“ heißt nicht „null“. Gemessen wurde innerhalb eines Tages und nur bei bestimmten Kniffen, und dass ein Problem „gelöst“ sei, folgt aus einem Effekt dieser Größe erst recht nicht. Dass das Problem um etwa fünf Prozent schrumpfe, klingt nach einer einfachen Rechnung, doch gemessen wurde das Erkennen der Kniffe, nicht, ob Menschen danach weniger Falschmeldungen glauben.","coreRule":"⚡ Prebunking hilft, aber der Effekt ist begrenzt: Nenne Wirkung und Grenze zusammen.","quote":"","quoteLabel":"","scenario":"Prebunking bedeutet: Man zeigt Menschen vorab kurz, wie typische Manipulationskniffe funktionieren (etwa emotional aufgeladene Sprache oder falsche Dilemmata), bevor sie ihnen im Netz begegnen. In einem Feldversuch auf YouTube mit rund 22.600 Antworten stieg die Erkennung solcher Kniffe im Mittel um etwa 5 %, gemessen innerhalb eines Tages.","kurz":"Der Effekt ist messbar, aber klein: rund 5 % mehr Erkennung, binnen eines Tages gemessen. Der Fehler ist, entweder zu jubeln oder abzuwinken, statt Wirkung und Grenze zusammen zu nennen. „Klein“ ist nicht „null“, „messbar“ nicht „groß“.","prueffrage":"Welche Formen von Desinformation und welche Zeitspanne hat der Feldversuch überhaupt erfasst?","rueckmeldung":[{"option":1,"text":"Die große Zahl an Antworten spricht dafür, dass der Effekt real ist. Sie macht ihn aber nicht groß: Er blieb knapp unter der vorab festgelegten kleinsten bedeutsamen Größe, und gemessen wurde nur kurz danach und bei bestimmten Kniffen."},{"option":2,"text":"Klein ist der Effekt tatsächlich, und er verfehlte knapp die vorab gesetzte Schwelle. Aber „klein“ heißt nicht „null“: Eine messbare Verbesserung ist etwas anderes als keine, und wer nur die Grenze nennt, lässt die Wirkung aus."},{"option":3,"text":"Gemessen wurde das Erkennen der Kniffe, nicht, ob Menschen danach weniger Falschmeldungen glauben. Die fünf Prozent beziehen sich auf die Erkennung und lassen sich deshalb nicht in eine Verkleinerung des Problems umrechnen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Roozenbeek, J. u. a. (2022): Psychological inoculation improves resilience against misinformation on social media. Science Advances 8(34), eabo6254","oeffentlich":true,"doi":"10.1126/sciadv.abo6254","seite":"S. 1 und 4–5 (laut Belegregister)","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qe-1","status":"entwurf","clusterId":"E","werkstueckRef":"E.1.1","stufe":1,"question":"Ein Freund sagt: „Ein Ball und ein Schläger kosten zusammen 1,10 €, der Schläger kostet genau 1 € mehr als der Ball. Der Ball kostet also 10 Cent – das sah ich sofort.“ Was ist hier der beste Rat?","options":["Er sollte andere fragen, was sie herausbekommen, denn kommen mehrere unabhängig voneinander auf 10 Cent, ist seine Antwort wahrscheinlich richtig.","Er sollte nachrechnen und prüfen, ob beide genannten Bedingungen zusammen stimmen, denn nur die Probe zeigt, ob die Antwort die Aufgabe löst.","Er sollte seinem ersten Eindruck vertrauen, denn bei so einfachen Zahlen ist die schnelle, mühelose Antwort in der Regel auch die richtige.","Er sollte die Aufgabe noch einmal Wort für Wort lesen, denn bei solchen Rätseln steckt der Haken meist in einer missverständlichen Formulierung."],"correctIndex":1,"explanation":"Mit 10 Cent für den Ball müsste der Schläger 1,10 € kosten, zusammen wären das 1,20 €. Die Bedingung „zusammen 1,10 €“ ist verletzt. Richtig ist: Der Ball kostet 5 Cent, der Schläger 1,05 €. Gerade bei Aufgaben, die sich auf den ersten Blick mühelos lösen lassen, lohnt sich die Gegenprobe, denn dass sich eine Antwort sofort richtig anfühlt, sagt nichts darüber, ob sie stimmt. Bei dieser Aufgabe liegt die intuitive Antwort bei vielen Menschen daneben, und selbst wer richtig rechnet, denkt oft zuerst an 10 Cent. Wer die Probe macht, setzt das langsame, bewusste Denken ein und fängt den Fehler des schnellen, intuitiven Denkens ab.","coreRule":"Fühlt sich eine Antwort sofort richtig an, mach die Gegenprobe: Stimmen alle Bedingungen gemeinsam?","quote":"","quoteLabel":"","scenario":"","kurz":"Mit 10 Cent für den Ball käme der Schläger auf 1,10 €, zusammen also 1,20 €. Dass sich eine Antwort sofort richtig anfühlt, beweist nichts; erst die Probe zeigt, ob alle Bedingungen stimmen (hier: 5 Cent).","prueffrage":"Wenn der Ball 10 Cent kostet und der Schläger einen Euro mehr, was kosten dann beide zusammen?","rueckmeldung":[{"option":0,"text":"Andere zu fragen kann zum Nachdenken anregen. Viele geraten bei dieser Aufgabe aber an denselben Fehler, und dass sie sich einig sind, zeigt nur, dass sie gleich verführt wurden, nicht, dass die Antwort stimmt."},{"option":2,"text":"Einfache Zahlen lassen die schnelle Antwort sicher wirken. Gerade hier liegt die mühelose Antwort bei vielen daneben, und dass sie sich richtig anfühlt, sagt nichts darüber, ob sie die Aufgabe löst."},{"option":3,"text":"Sorgfältiges Lesen schadet nie. Der Text ist hier aber eindeutig, der Fehler liegt nicht in der Formulierung, sondern im schnellen Schluss, und den deckt erst die Probe mit den Zahlen auf."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Frederick, S. (2005): Cognitive Reflection and Decision Making. Journal of Economic Perspectives 19(4), S. 25–42","oeffentlich":true,"doi":"10.1257/089533005775196732","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"40240a6383c7e078"}},{"id":"qe-2","status":"entwurf","clusterId":"E","werkstueckRef":"E.1.2","stufe":2,"question":"Was ist die sparsamste Erklärung für diesen Befund?","options":["Die Studierenden wollen dem Versuchsleiter gefallen (soziale Erwünschtheit), also bewertet die 1-Dollar-Gruppe die langweilige Aufgabe freundlicher.","Mit nur 1 Dollar lässt sich die Lüge kaum rechtfertigen (kognitive Dissonanz), also passen die Studierenden ihre Einstellung zur Aufgabe an.","Wer die Aufgabe anderen als interessant schildert, glaubt es danach eher selbst (Wiederholung), also bewertet die 1-Dollar-Gruppe sie freundlicher.","Hohe Bezahlung untergräbt die innere Motivation (Überrechtfertigungseffekt), also verliert die 20-Dollar-Gruppe das Interesse an der Aufgabe."],"correctIndex":1,"explanation":"Wer gegen seine Überzeugung redet, erlebt einen Widerspruch zwischen seinem Selbstbild und seinem Verhalten. Bei 20 Dollar gibt es eine bequeme Begründung („Ich hab’s für das Geld getan“), der Widerspruch bleibt klein. Bei 1 Dollar fehlt diese Begründung: „Ich bin ein ehrlicher Mensch“ und „Ich habe für einen mickrigen Dollar gelogen“ passen schlecht zusammen. Der einfachste Ausweg ist, die eigene Einstellung nachzujustieren: „Eigentlich war die Aufgabe gar nicht so langweilig.“ Allerdings ist die Befundlage nicht ganz so eindeutig, wie sie klingt: Eine große Wiederholung testete nicht die 1-/20-Dollar-Anordnung selbst, sondern eine Variante desselben Paradigmas (Aufsatz gegen die eigene Überzeugung, Wahlfreiheit statt Bezahlung) und fand den erwarteten Effekt der Wahlfreiheit nicht. Die Erklärung gilt daher als plausibel, nicht als endgültig bewiesen.","coreRule":"⚡ Wenn Verhalten und Überzeugung kollidieren, passen wir oft die Überzeugung an, vor allem dann, wenn eine äußere Rechtfertigung fehlt.","quote":"","quoteLabel":"","scenario":"In einem Experiment mussten Studierende eine extrem langweilige Aufgabe erledigen. Danach sollten sie dem nächsten Teilnehmer erzählen, die Aufgabe sei interessant gewesen. Die einen bekamen dafür 20 Dollar, die anderen nur 1 Dollar. Später sollten alle die Aufgabe bewerten: Die 1-Dollar-Gruppe fand sie deutlich interessanter als die 20-Dollar-Gruppe.","beleg":"Werkstück E.1.2; Fn. gl-e-festinger (Festinger & Carlsmith 1959; Replikation Vaidis u. a. 2024 mit Einschränkung) und Anm. anm-gl-e-festinger","kurz":"Wer für nur 1 Dollar lügt, hat kaum eine Rechtfertigung und passt eher die eigene Einstellung an („so langweilig war es gar nicht“). Bei 20 Dollar erklärt das Geld das Verhalten. Das ist plausibel, aber nicht endgültig bewiesen.","prueffrage":"Worin unterscheiden sich die beiden Gruppen außer in der Bezahlung überhaupt?","rueckmeldung":[{"option":0,"text":"Dass Befragte gefallen wollen, kommt tatsächlich vor. Dieser Wunsch gälte aber für beide Gruppen gleich und könnte nicht erklären, warum gerade die 1-Dollar-Gruppe die Aufgabe interessanter findet."},{"option":2,"text":"Dass Reden das eigene Urteil färben kann, geht in die richtige Richtung. Sprechen mussten aber beide Gruppen, und einmal. Nur die Bezahlung unterscheidet sie, und genau dieser Unterschied bleibt hier unerklärt."},{"option":3,"text":"Belohnung kann innere Motivation tatsächlich schwächen. Das setzt aber eine Aufgabe voraus, die vorher Freude machte. Diese Aufgabe war extrem langweilig, und es gibt keine Messung davor, an der sich ein Interessenverlust ablesen ließe."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Festinger, L.; Carlsmith, J. M. (1959): Cognitive Consequences of Forced Compliance. Journal of Abnormal and Social Psychology 58(2), S. 203–210 (Volltext: Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Festinger/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vaidis, D. C. u. a. (2024): A Multilab Replication of the Induced-Compliance Paradigm of Cognitive Dissonance. Advances in Methods and Practices in Psychological Science 7(1)","oeffentlich":true,"doi":"10.1177/25152459231213375","url":"https://research-repository.uwa.edu.au/en/publications/cea91f86-625c-4f4d-85ff-d41f3d22a503","abruf":"2026-10-12"},{"typ":"url","kurz":"Solovjeva, M.; Buttlar, B.; Daniel, A.; Vaidis, D. C. (2026): Cognitive Dissonance. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter3.html","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0a8c17a12603c6b1"}},{"id":"qe-3","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.2","stufe":2,"question":"Ein Kommilitone sagt: „Dass fast zwei Drittel der Teilnehmer in Milgrams Gehorsamsexperiment bis zum vermeintlich tödlichen Schock gingen, zeigt, dass die meisten Menschen im Kern grausam sind.“ Welche Reaktion prüft diese Schlussfolgerung am besten?","options":["Man fragt, ob die Persönlichkeit das Verhalten allein erklärt oder ob die Situation (Autorität, Verantwortungsabgabe, kleine Schritte) mitentscheidend war.","Man fragt, ob die Teilnehmer, die bis zum vermeintlich tödlichen Schock gingen, einen Querschnitt aller Menschen bildeten oder eine besonders gehorsame Auswahl.","Man fragt, ob sich der Anteil von fast zwei Dritteln in späteren Wiederholungen des Versuchs bestätigen ließ oder ob er ein einmaliger Zufallswert war.","Man fragt, ob die Teilnehmer die Schocks wirklich für echt hielten oder ob sie ahnten, dass niemand Schmerzen erlitt, und deshalb einfach weitermachten."],"correctIndex":0,"explanation":"Die Schlussfolgerung springt von einem Verhalten in einer ganz bestimmten Situation auf einen Charakterzug. Dabei war die Situation sehr speziell: Eine angesehene Institution, ein Versuchsleiter, der die Verantwortung übernahm, und Schocks, die in 15-Volt-Schritten langsam stiegen, sodass es nie eine klare Grenze zum Aufhören gab. Wie stark die Situation wirkt, zeigt sich auch daran, dass die Gehorsamsquote in den Varianten des Experiments zwischen null und über neunzig Prozent schwankte, je nachdem, wie Autorität, Distanz zum Opfer und Rahmen gestaltet waren. Wer ein Verhalten erklärt, muss deshalb zuerst prüfen, welchen Anteil die Umstände haben, bevor er auf feste Eigenschaften der Person schließt. Dass Menschen unter starkem situativem Druck oft gehorchen, heißt nicht, dass sie im Kern böse sind.","coreRule":"⚡ Erkläre Verhalten nicht vorschnell mit Charakter: Prüfe zuerst, welche Kraft die Situation hatte.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück E.2.2; Fußnote gl-e-milgram (Milgram 1963: 26 von 40 = 65 % bis 450 V). Die Schwankungsbreite der Gehorsamsquote von null bis über neunzig Prozent in den Varianten steht im Fließtext des Abschnitts „Die situativen Faktoren des Gehorsams“; Fußnote gl-e-milgram-varianten verweist dazu auf Milgram 1974 und Haslam/Reicher 2012. Die Frage wurde von der reinen Prozentabfrage zur Denkaufgabe (Fundamentaler Attributionsfehler: Situation vs. Charakter) umgebaut.","kurz":"Aus Verhalten in einer sehr speziellen Lage lässt sich nicht auf einen festen Charakterzug schließen. Erst muss geklärt werden, wie viel die Umstände ausmachen: Autorität, abgegebene Verantwortung und kleine Schritte können Gehorsam auch ohne Grausamkeit erklären.","prueffrage":"Welches Verhalten wurde in welcher Lage beobachtet, und auf welche Eigenschaft schließt der Kommilitone daraus?","rueckmeldung":[{"option":1,"text":"Wer wissen will, auf wen sich die Zahl übertragen lässt, fragt zu Recht nach der Auswahl der Teilnehmer. Ein perfekter Querschnitt würde aber noch nicht klären, ob das Verhalten aus dem Charakter oder aus der Situation kam."},{"option":2,"text":"Eine Wiederholung würde zeigen, wie verlässlich die Zahl ist. Aber auch ein bestätigter Wert sagt nichts darüber, ob Charakter oder Situation ihn erzeugt hat, und genau darauf zielt der Schluss des Kommilitonen."},{"option":3,"text":"Ob die Schocks für echt gehalten wurden, betrifft die Gültigkeit des Versuchs. Der Sprung vom Verhalten auf einen Charakterzug bliebe davon unberührt, denn auch wer sie für echt hielt, kann unter Druck gehorcht haben."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the ‚Nature‘ of Conformity: What Milgram and Zimbardo’s Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7c13a2d8d64c7ebd"}},{"id":"qe-4","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.4","stufe":1,"question":"In einer Finanzausschuss-Sitzung wird ein Kraftwerksprojekt für 10 Millionen Euro in zweieinhalb Minuten abgenickt. Über einen Fahrradschuppen für 350 Euro wird 45 Minuten gestritten: Holz oder Aluminium, Blau oder Grün. Welche Erklärung für diesen Verlauf ist am plausibelsten?","options":["Beim Schuppen kann jeder mitreden und sich profilieren, beim Kraftwerk fehlt vielen das Verständnis für kluge Fragen, und niemand will unwissend wirken.","Bei Holz oder Aluminium, Blau oder Grün gibt es keine Lösung, die man ausrechnen kann, beim Kraftwerk dagegen geben die Zahlen das Ergebnis schon weitgehend vor.","350 Euro sind greifbar, also wird um den Betrag gerungen, während 10 Millionen so abstrakt wirken, dass sie im Ausschuss kaum noch etwas auslösen.","Beim Kraftwerk verlässt man sich darauf, dass andere die Pläne schon gründlich geprüft haben, beim Schuppen fühlen sich dagegen viele selbst zuständig."],"correctIndex":0,"explanation":"Die Zeit, die eine Gruppe auf ein Thema verwendet, folgt nicht der Wichtigkeit, sondern der Mitredbarkeit. Zum Fahrradschuppen hat jeder eine Meinung, und mit einem Vorschlag zur Farbe lässt sich Kompetenz risikolos zeigen. Beim Kraftwerk ist das anders: Die Technik ist komplex, und wer eine Frage stellt, riskiert, unwissend zu wirken. Also schweigen viele, und der Antrag wird durchgewunken. Dieses Muster hat C. Northcote Parkinson 1957 satirisch als „Gesetz der Trivialität“ (Bikeshedding) beschrieben.","coreRule":"⚡ Teile Sitzungszeiten nach Budget und Risiko ein, nicht nach Streitlust!","quote":"Die Debatte über das Atomkraftwerk dauert exakt zweieinhalb Minuten.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück E.2.4, Fußnote gl-e-parkinson: Parkinson, Parkinson's Law, and Other Studies in Administration (1957), Kapitel „High Finance, or The Point of Vanishing Interest“; Beispiel Reaktor vs. Fahrradschuppen.","kurz":"Die Beratungszeit folgt der Mitredbarkeit, nicht der Wichtigkeit: Zum Schuppen kann jeder risikolos etwas beitragen, beim Kraftwerk riskiert man, unwissend zu wirken. Naheliegend ist der Schluss, wichtige Dinge bekämen mehr Aufmerksamkeit.","prueffrage":"Worum ging es im Streit über den Schuppen, und wie viel stand dabei auf dem Spiel?","rueckmeldung":[{"option":1,"text":"Dass sich Farbe und Material nicht ausrechnen lassen, stimmt und lässt Streit zu. Aber auch beim Kraftwerk entscheiden nicht allein Zahlen; es wurde nicht nachgerechnet, sondern abgenickt. Entscheidend ist, wer mitreden kann."},{"option":2,"text":"Kleine Beträge sind tatsächlich greifbarer, und das kann eine Rolle spielen. Es erklärt aber nicht, warum beim Kraftwerk kaum jemand nachfragt. Dafür ist wohl eher ausschlaggebend, dass Fragen dort leicht unwissend wirken."},{"option":3,"text":"Vertrauen in andere und diffuse Zuständigkeit gibt es in Gremien durchaus. Im Szenario steht aber nichts davon, dass die Pläne geprüft wurden; das wird nur angenommen. Plausibler ist, dass Fragen beim Kraftwerk ein Risiko bedeuten."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3dca50d12dec05e0"}},{"id":"qe-5","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.2","stufe":2,"question":"Welche Vorhersage über seinen Versuch ist am besten begründet?","options":["Er wird den Euro entwerten, weil Geld nur auf Einbildung beruht und mit seinem Glauben auch der Wert für alle anderen schwindet.","Er wird bald knapp bei Kasse sein, weil der Euro wie ein Berg unabhängig davon existiert, was irgendein Mensch über ihn denkt.","Er wird gut zurechtkommen, weil Geld wie ein Traum nur im Kopf des Einzelnen existiert und für ihn nun einfach wegfällt.","Er wird bald knapp bei Kasse sein, weil der Euro für alle anderen weiterwirkt, solange sie gemeinsam darauf vertrauen."],"correctIndex":3,"explanation":"Der Freund verwechselt „keine physische Existenz“ mit „nicht wirklich vorhanden“. Es gibt nicht nur zwei Kategorien, die objektive Realität (ein Baum, die Schwerkraft) und die rein persönliche (ein Traum, ein Kopfschmerz). Geld gehört zu einer dritten: Es existiert im gemeinsamen Glauben und in der Kommunikation eines großen Netzwerks von Menschen. Genau das zeigt sein Versuch: Wenn er allein aufhört, an den Euro zu glauben, ist er nicht erleuchtet, sondern pleite, denn Vermieter, Arbeitgeber und Supermarkt handeln weiter danach. Ein Schimpanse nimmt ebenso eine Banane, aber keinen Geldschein, weil er nicht Teil dieses Netzwerks ist. Dass sein Ausstieg den Euro für alle entwertet, verkennt, dass Geld erst zusammenbricht, wenn eine kritische Masse aufhört, an die gemeinsame Geschichte zu glauben, wie beim Wertverfall einer Währung bei Hyperinflation; ein Einzelner ist keine solche Masse. Der Berg-Vergleich sagt die Folge richtig voraus, nennt aber den falschen Grund, denn ein Berg verschwindet nicht, wenn niemand mehr an ihn denkt, Geld unter Umständen schon. Und wäre Geld nur ein Traum im eigenen Kopf, würden Vermieter und Supermarkt es nicht weiter verlangen.","coreRule":"⚡ Real ist nicht nur, was man anfassen kann: Vieles wirkt, weil viele gemeinsam daran glauben und danach handeln.","quote":"","quoteLabel":"","scenario":"Ein Freund sagt: „Geld ist doch nur bedrucktes Papier. Es hat keinen echten Wert, also existiert es gar nicht wirklich.“ Um das zu beweisen, will er ab sofort keine Euro mehr annehmen und keine mehr ausgeben. Sein Vermieter, sein Arbeitgeber und der Supermarkt rechnen weiter in Euro, und sonst macht niemand bei seinem Versuch mit.","kurz":"Der Euro wirkt durch das gemeinsame Vertrauen vieler, nicht durch den Glauben eines Einzelnen. Wer allein aufhört, daran zu glauben, steht ohne Geld da, obwohl Vermieter, Arbeitgeber und Supermarkt weiter danach handeln.","prueffrage":"Was ändert sich im Verhalten seines Vermieters und des Supermarkts, wenn nur er den Euro ablehnt?","rueckmeldung":[{"option":0,"text":"Dass Geld auf gemeinsamem Glauben beruht, stimmt. Ein Einzelner ist aber keine kritische Masse: Der Wert schwindet erst, wenn sehr viele das Vertrauen verlieren, und hier rechnen alle anderen weiter in Euro."},{"option":1,"text":"Die Vorhersage trifft zu, der Grund nicht. Ein Berg bleibt, auch wenn niemand an ihn denkt, Geld dagegen existiert im gemeinsamen Glauben und kann unter Umständen verschwinden, wenn dieser Glaube bricht."},{"option":2,"text":"Ein Traum existiert nur für den, der ihn träumt. Geld wirkt dagegen über viele Menschen hinweg, sonst würden Vermieter und Supermarkt es nicht weiter verlangen. Sein Ausstieg ändert für ihn viel, für sie nichts."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"97384975ce37b1a2"}},{"id":"qe-6","status":"entwurf","clusterId":"E","werkstueckRef":"E.4.3","stufe":2,"question":"Was folgt daraus für die Auswahl der Beiträge, die das System bevorzugt ausspielt?","options":["Das System verbreitet bevorzugt, was viele Reaktionen auslöst. Empörendes setzt sich durch, auch ohne dass jemand Wut gezielt fördern will.","Das System zeigt Nutzern bevorzugt, was ihre Sicht bestätigt (Filterblase). Beiträge über die Gegenseite verschwinden, auch ohne dass jemand sie ausblenden will.","Das System wurde von den Entwicklern auf Streit getrimmt. Beiträge über die Gegenseite werden bevorzugt, weil jemand Wut gezielt fördern will.","Das System spiegelt nur, was Nutzer ohnehin teilen. Empörendes fällt auf, doch das System selbst bevorzugt und verstärkt davon nichts."],"correctIndex":0,"explanation":"Ein System, das nur auf Verweildauer und Reaktionen optimiert ist, kennt weder Wahrheit noch Wut. Es merkt sich lediglich, welche Inhalte Menschen zum Bleiben, Kommentieren und Teilen bringen. Studien zeigen, dass Beiträge über die Gegenseite etwa doppelt so oft geteilt werden – so ergab es die Auswertung von rund 2,7 Millionen Beiträgen von US-Medien und Abgeordneten (Rathje et al. 2021). Ein System, das auf Reaktionen optimiert ist, bevorzugt daher solche Inhalte, ohne böse Absicht und ohne Handauswahl. Das ist eine emergente Eigenschaft: Die Bevorzugung entsteht aus dem Optimierungsziel, nicht aus einem bösartigen Plan der Programmierer. Das heißt noch nicht, dass solche Feeds Menschen messbar radikalisieren: Dazu fanden große Feldexperimente keinen Effekt, ein kleineres nur eine geringe, kurzfristige Verschiebung. Und dass Falschnachrichten sich weiter verbreiten, liegt vor allem daran, dass Menschen sie häufiger teilen, nicht an Algorithmen oder Bots (Vosoughi et al. 2018). Die anderen Gedanken klingen sinnvoll, passen aber nicht zum Fall. Eine Filterblase würde zeigen, was die eigene Sicht bestätigt, hier werden aber gerade Beiträge über die Gegenseite am häufigsten geteilt. Eine gezielte Abstimmung auf Streit widerspricht dem Fall, denn das System lernt selbstständig und niemand hat Wut als Ziel vorgegeben. Ein bloßes Spiegeln übersieht, dass das System aus dem Verhalten lernt und das, was zum Bleiben bringt, selbst bevorzugt ausspielt.","coreRule":"⚡ Frag bei jedem System zuerst, worauf es optimiert ist. Was dieses Ziel belohnt, verbreitet sich, ob es wahr oder wichtig ist oder nicht.","quote":"","quoteLabel":"","scenario":"Eine Plattform will, dass Nutzer möglichst lange bleiben, und lässt ihr Empfehlungssystem selbstständig lernen, welche Beiträge dafür am besten funktionieren. Nach einigen Monaten zeigt sich: Beiträge über die politische Gegenseite, oft empört oder abwertend formuliert, werden etwa doppelt so oft geteilt wie Beiträge über die eigene Seite.","beleg":"Werkstück E.4.3; Fußnote gl-e-empoerung (Rathje et al. 2021, 2,7 Mio. Beiträge, doppelt so oft geteilt), Fußnote gl-e-kaninchenbau (Hinweis zur Beleglage), Fußnote gl-e-vosoughi (Menschen verbreiten Falschnachrichten, Bots beschleunigen beides gleich).","kurz":"Wer auf Verweildauer und Reaktionen optimiert, bevorzugt automatisch, was Reaktionen auslöst, hier Empörendes über die Gegenseite. Der naheliegende Fehler ist, hinter einem solchen Muster einen Plan zu vermuten, obwohl es aus dem Ziel selbst entsteht.","prueffrage":"Welche Beiträge werden häufiger geteilt, und was misst das System, während es lernt?","rueckmeldung":[{"option":1,"text":"Filterblasen gibt es, und ein System braucht keine Ausblendeabsicht, um eine zu erzeugen. Hier wird aber gerade das über die Gegenseite doppelt so oft geteilt, also stärker verbreitet. Das Bild passt nicht zu dem, was im Szenario geschieht."},{"option":2,"text":"Das Ergebnis sieht tatsächlich nach Streit aus. Daraus folgt aber kein Plan: Das System lernt selbstständig, und vorgegeben wurde nur, die Verweildauer zu steigern. Dass Wut dabei gut funktioniert, hat niemand bestellt."},{"option":3,"text":"Richtig ist, dass Nutzer Empörendes häufiger teilen. Das System gibt das aber nicht neutral weiter: Es lernt daraus, was zum Bleiben bringt, und spielt genau das selbst bevorzugt aus. So verstärkt es, was es vorfindet."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"url","kurz":"MIT News (Dizikes, P., 8.3.2018): Study: On Twitter, false news travels faster than true stories","oeffentlich":true,"url":"https://news.mit.edu/2018/study-twitter-false-news-travels-faster-true-stories-0308","abruf":"2026-10-12"},{"typ":"doi","kurz":"Guess, A. M. u. a. (2023): How Do Social Media Feed Algorithms Affect Attitudes and Behavior in an Election Campaign? Science 381(6656)","oeffentlich":false,"doi":"10.1126/science.abp9364"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9249f1d161943fec"}},{"id":"qe-7","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.1","stufe":2,"question":"Welche Schlussfolgerung zieht ein Forscher am sinnvollsten aus dieser Beobachtung?","options":["Sie hielt sieben gleiche Urteile für verlässlicher als ihr eigenes und folgte deshalb der Mehrheit, obwohl sie anders sah.","Sie neigt als Person stark zur Anpassung, denn wer sich so oft einer falschen Antwort anschließt, ist leicht beeinflussbar.","Sie stellt ihr Nachgeben später günstiger dar, denn wer die richtige Linie gesehen haben will, wirkt eigenständiger.","Sie beugte sich dem sozialen Druck der sieben anderen, ohne dabei an ihrer eigenen Wahrnehmung der drei Linien zu zweifeln."],"correctIndex":3,"explanation":"Die Person sagt selbst, dass sie die richtige Linie gesehen hat. Damit scheiden die Erklärungen aus, sie habe an ihrer Wahrnehmung gezweifelt oder ihre Wahrnehmung sei verzerrt gewesen: Wer richtig sieht und trotzdem falsch antwortet, gibt dem Druck der Gruppe nach, nicht der Unsicherheit. Dieser soziale Druck, dazuzugehören und nicht negativ aufzufallen, heißt normativer Einfluss. Er wirkt stärker, wenn man unter den Augen der Gruppe antworten muss; die Befundlage dazu ist allerdings uneinheitlich. Ein Gegenstück ist der informative Einfluss: Hier hält man die Gruppe für besser informiert („Wenn alle das sagen, müssen sie etwas wissen, was ich nicht weiß“). In Aschs Nachbefragungen kamen beide Motive vor. Nach seiner Einteilung von 1951 hielten die meisten Nachgebenden die Mehrheit für im Recht (Verzerrung des Urteils), und nur ein Teil wusste die richtige Antwort und passte sich an, um nicht unterlegen zu wirken (Verzerrung der Handlung); als häufigsten Grund nannten die Nachgebenden 1956 allerdings die Pein, allein gegen die Mehrheit zu stehen. Die Person im Beispiel gehört zu diesem zweiten Typ. Wer eine Aussage erklären will, sollte die Begründung der Person selbst ernst nehmen und prüfen, welche Erklärung zu den genannten Fakten passt.","coreRule":"⚡ Wer richtig sieht und trotzdem falsch antwortet, gibt oft nicht der Information nach, sondern dem Wunsch, dazuzugehören.","quote":"Wir passen uns an, weil wir von der Gruppe gemocht, akzeptiert und nicht bestraft werden wollen.","quoteLabel":"Merksatz:","scenario":"In einem Wahrnehmungsversuch sitzt eine Versuchsperson mit sieben anderen Personen im Raum. Man zeigt eine Linie und drei Vergleichslinien; eine davon ist eindeutig gleich lang. Die sieben anderen (Eingeweihte) nennen einstimmig und überzeugt die falsche Linie. Als die Versuchsperson an der Reihe ist, schließt sie sich in vielen Fällen der falschen Antwort an. Später sagt sie: „Ich habe die richtige Linie gesehen, wollte aber nicht als Einzige aus der Reihe fallen.“","beleg":"Werkstück E.2.1; Fn. gl-e-asch-gruende (Asch 1956, S. 32 und 70: häufigste Begründung „painfulness of standing alone against the majority“; andere zweifelten an ihren Augen); Fn. gl-e-einfluss. Korrigiert 12.10.2026 nach dem von Sturm zitierten Studientext: „distortion of judgment“ war die häufigste Gruppe der Nachgebenden, „distortion of action“ („wollten nicht unterlegen scheinen“) die seltenere; die frühere Angabe „Druck am häufigsten genannt“ entfällt.","kurz":"Die Person sagt selbst, sie habe richtig gesehen und trotzdem falsch geantwortet. Das passt zu sozialem Druck: Man wollte nicht auffallen. Der naheliegende Fehler ist, ihr Nachgeben einer unsicheren Wahrnehmung oder einem Charakterzug zuzuschreiben.","prueffrage":"Was sagt die Person selbst darüber, was sie gesehen hat, und wie passt das zu ihrer Antwort?","rueckmeldung":[{"option":0,"text":"Dass viele Menschen eine einstimmige Gruppe für besser informiert halten, kommt in solchen Versuchen tatsächlich vor. Diese Person sagt aber ausdrücklich, sie habe die richtige Linie gesehen. Dazu passt kein Vertrauen in das fremde Urteil, sondern der Wunsch, nicht aufzufallen."},{"option":1,"text":"Wer so oft nachgibt, wirkt schnell wie ein anpassungsfreudiger Mensch. Der Versuch zeigt aber, wie stark die Situation wirkt: Sieben einstimmige Gegenstimmen bringen viele Menschen zum Nachgeben. Aus dem Verhalten allein folgt kein Persönlichkeitsmerkmal."},{"option":2,"text":"Dass man sein Nachgeben im Rückblick schönt, ist denkbar. Hier gibt es dafür aber keinen Anhaltspunkt, und ihre Begründung ist stimmig: Sie nennt ein Motiv, das sich auch in den Nachbefragungen häufig fand. Eine Aussage zu verdächtigen, ohne etwas vorzuweisen, ersetzt keine Prüfung."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b47c9c224a76e9bb"}},{"id":"qe-8","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.3","stufe":4,"question":"Eine Kollegin sagt: „In Labor-Experimenten meldeten Menschen Rauch viel seltener, wenn andere im Raum waren. Also bleibt jeder Notfall vor Publikum unbeantwortet, und Umstehende greifen im Alltag kaum je ein.“ Was ist an diesem Schluss problematisch?","options":["Er macht aus einer gesunkenen Hilfechance ein „nie“, obwohl in einer Menge schon ein einziger Helfer genügt, damit geholfen wird.","Er überträgt einen Laborbefund auf den Alltag, obwohl sich Menschen im Versuch anders verhalten können als auf der Straße.","Er setzt Rauch mit Notfällen allgemein gleich, obwohl man bei unklarem Rauch eher abwartet als bei einem offen ausgetragenen Konflikt.","Er ist im Kern richtig und nur zu scharf formuliert, denn wer in einer Gruppe seltener meldet, wird auch im Alltag seltener helfen."],"correctIndex":0,"explanation":"Im Rauchexperiment meldeten Menschen seltener, wenn andere im Raum waren, etwa weil sich die gefühlte Verantwortung verteilt oder man sich an der Ruhe der anderen orientiert; dieser Befund ist echt. Er zeigt aber eine gesunkene Chance, keine völlige Untätigkeit: Selbst in den Dreiergruppen meldete in 38 % der Fälle jemand den Rauch. Weil schon eine helfende Person genügt, kann eine Menge als Ganzes trotzdem oft helfen. Das zeigten gefilmte Konflikte aus Amsterdam, Lancaster und Kapstadt: Dort griff in gut neun von zehn Fällen mindestens ein Umstehender ein, und die Chance auf Hilfe stieg mit der Zahl der Anwesenden eher. Der Fehler liegt im Sprung von einer gesunkenen Hilfechance auf „jeder Notfall bleibt unbeantwortet“ und „kaum je“.","coreRule":"⚡ Eine Wahrscheinlichkeit für die einzelne Person ist keine Aussage über die Menge: Wenn jeder seltener handelt, kann die Gruppe trotzdem handeln.","quote":"","quoteLabel":"","scenario":"In einem Rauchexperiment meldeten 75 % derer, die allein im Raum waren, den Rauch; in Dreiergruppen meldete nur in 38 % der Gruppen überhaupt jemand den Rauch. Eine Auswertung von 219 gefilmten Konflikten in drei Ländern zeigte dagegen, dass in gut neun von zehn Fällen mindestens ein Umstehender eingriff.","kurz":"Der Laborbefund zeigt eine gesunkene Hilfechance, keine völlige Untätigkeit. Weil schon ein Helfer genügt, kann eine Menge oft helfen. Der Fehler ist der Sprung von „seltener“ zu „nie“ und „kaum je“.","prueffrage":"Wie oft griff in den 219 gefilmten Konflikten mindestens ein Umstehender ein, und wie passt das zu „kaum je“?","rueckmeldung":[{"option":1,"text":"Dass Labor und Straße sich unterscheiden können, ist ein berechtigter Einwand gegen vorschnelle Übertragung. Hier trifft er aber nicht den Kern: Der Laborbefund selbst ist echt. Der Fehler liegt darin, aus „seltener“ ein „nie“ zu machen."},{"option":2,"text":"Unklarer Rauch und offener Streit können das Verhalten durchaus verschieden beeinflussen. Auch bei gleicher Art von Notfall wäre der Schluss aber falsch, denn aus einer gesunkenen Hilfechance folgt nicht, dass nie jemand eingreift."},{"option":3,"text":"Richtig ist, dass die Chance pro Person in Gruppen sinkt. Das ist aber etwas anderes als eine Menge, die nicht hilft: Es genügt ein Helfer, und in gut neun von zehn Konflikten griff jemand ein. Mit „zu scharf“ ist der Fehler also unterschätzt."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Philpot, R.; Liebst, L. S.; Levine, M.; Bernasco, W.; Lindegaard, M. R. (2020): Would I Be Helped? Cross-National CCTV Footage Shows That Intervention Is the Norm in Public Conflicts. American Psychologist 75(1), S. 66–75 (Manuskriptfassung, Lancaster University)","oeffentlich":true,"doi":"10.1037/amp0000469","url":"https://eprints.lancs.ac.uk/id/eprint/134891/1/Would_I_be_Helped_Cross_National_CCTV_Footage_Shows_That_Intervention_Is_the_Norm_in_Public_Conflicts_Postprint.pdf","seite":"PDF-S. 2, 11","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Latané, B.; Darley, J. M. (1968): Group Inhibition of Bystander Intervention in Emergencies. Journal of Personality and Social Psychology 10(3), S. 215–221","oeffentlich":false,"doi":"10.1037/h0026570"},{"typ":"literatur","kurz":"Fischer, P.; Krueger, J. I.; Greitemeyer, T. u. a. (2011): The bystander-effect: A meta-analytic review on bystander intervention in dangerous and non-dangerous emergencies. Psychological Bulletin 137(4), S. 517–537","oeffentlich":false,"doi":"10.1037/a0023304"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"de35b4f6f7ae061d"}},{"id":"qe-9","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.5","stufe":2,"question":"Ein Team beschließt in einer Sitzung eine Regel, die offensichtlich unsinnig ist. Niemand widerspricht. Später erfährst du: Fast alle hielten die Regel insgeheim für Unsinn und hielten sich für den Einzigen mit diesem Zweifel. Was erklärt das Schweigen am besten?","options":["Die Zweifler passten sich einer tatsächlich vorhandenen Mehrheit an, weil sie nicht allein gegen die Gruppe stehen wollten.","Fast alle scheuten den offenen Streit im Team (Harmoniebedürfnis) und schwiegen lieber, als in der Sitzung eine Debatte anzufangen.","Die Verantwortung für einen Einspruch verteilte sich auf alle Anwesenden, sodass sich am Ende niemand mehr zuständig fühlte.","Fast alle deuteten das Schweigen der anderen als Zustimmung und beugten sich so einer Mehrheitsmeinung, die es gar nicht gab."],"correctIndex":3,"explanation":"Entscheidend ist die Lücke zwischen privater Überzeugung und öffentlichem Verhalten. Wer sich unsicher ist, orientiert sich an den anderen und liest deren Schweigen als Zustimmung. Da alle dasselbe tun, wirkt jedes Schweigen wie ein weiterer Beleg dafür, dass alle einverstanden sind. So entsteht eine Mehrheit, die es privat nie gab. Ein bekanntes Beispiel ist der Hörsaal: Nach „Gibt es Fragen?“ meldet sich niemand, obwohl vielen etwas unklar ist, und jeder deutet das Schweigen der anderen als Verständnis. Das Märchen von des Kaisers neuen Kleidern zeigt denselben Kreislauf des Schweigens. Anpassung an eine echte Mehrheit ist etwas anderes: Dort stimmt das Bild der Gruppe, hier ist es eine kollektive Täuschung. Und Verantwortungsdiffusion passt nicht, weil die Leute nicht schweigen, weil sie sich nicht zuständig fühlen, sondern weil sie die Meinung der anderen falsch einschätzen.","coreRule":"⚡ Das Schweigen der anderen ist kein Beleg für ihre Zustimmung. Prüfe, ob du nur ihr Verhalten siehst, nicht ihre Überzeugung.","quote":"Ich sehe nichts … aber alle anderen scheinen die prächtigen Stoffe zu sehen. Ich muss wohl der einzige Dumme hier sein.","quoteLabel":"Gedanke der Bürger im Märchen:","scenario":"Du bist neu im Team und wunderst dich über eine Regel, die laut Protokoll „einstimmig“ beschlossen wurde. Auf Nachfrage räumen mehrere Kolleginnen und Kollegen einzeln ein, sie hätten die Regel von Anfang an für sinnlos gehalten.","kurz":"Fast alle hielten sich für die Einzigen mit Zweifel und lasen das Schweigen der anderen als Zustimmung. So entstand eine Mehrheit, die es privat nie gab. Das ist keine Anpassung an eine echte Mehrheit, sondern eine kollektive Täuschung.","prueffrage":"Woran könntest du erkennen, was die Einzelnen wirklich dachten, als niemand etwas sagte?","rueckmeldung":[{"option":0,"text":"Wer sich anpasst, um nicht allein dazustehen, ist ein bekanntes Muster. Hier ist die Mehrheit aber nur Schein: Privat dachten fast alle gleich, es gab nichts, woran man sich hätte anpassen können."},{"option":1,"text":"Scheu vor Streit kann Schweigen durchaus fördern. Sie erklärt aber nicht, warum sich jeder für den Einzigen hielt: Dann wüsste man ja, dass andere ebenso denken, und die Lage wäre eine andere."},{"option":2,"text":"Verantwortungsdiffusion gibt es, etwa wenn viele Zeugen einer Notlage zusehen. Hier fehlte aber nicht das Zuständigkeitsgefühl, sondern der Blick auf das, was die anderen wirklich dachten."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"f91bc8525ff77ae3"}},{"id":"qe-10","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.7","stufe":4,"question":"Welche Reaktion prüft diese Behauptung am besten?","options":["Ich frage, ob die Forschenden das Verhalten der Wärter beeinflusst haben und ob andere Studien mit weniger Eingriff dasselbe Ergebnis zeigen.","Ich frage, ob die Teilnehmenden damals ausreichend geschützt wurden, denn bei Versuchen mit Menschen hat der Schutz der Beteiligten Vorrang.","Ich frage, ob sich die Behauptung überhaupt widerlegen ließe, denn eine Aussage, die nichts ausschließt, sagt nichts über die Welt.","Ich frage, was die Kollegin genau unter „Tyrann“ versteht, denn unklare Begriffe führen in Diskussionen leicht zu Missverständnissen, die jede Prüfung erschweren."],"correctIndex":0,"explanation":"Ein berühmter Befund ist noch kein belastbarer Befund; entscheidend ist, wie das Ergebnis zustande kam. Eine Archivrecherche zeigt, dass die Studienleitung einen zögerlichen Wärter ausdrücklich zu mehr Härte aufforderte, und ein früherer „Gefangener“ sagte später, er habe sich in seinen Nervenzusammenbruch bewusst hineingesteigert, um entlassen zu werden (der Leiter bestritt das). Weil die Studienleitung ins Geschehen eingriff, sagt das Ergebnis wenig darüber, was Menschen von selbst tun. In der BBC Prison Study, in der die Forscher keine Führungsrolle übernahmen, fügte sich niemand automatisch in seine Rolle; Tyrannei entstand erst durch die Identifikation mit einer Gruppe und ihrer Führung. Die anderen Fragen sind für sich vernünftig, prüfen aber nicht, wie das Ergebnis entstand: Der Schutz der Teilnehmenden ist eine wichtige ethische Frage, sagt aber nichts darüber, ob der Befund stimmt. Die Behauptung ist durchaus widerlegbar, man kann sie an Daten prüfen, dort liegt also nicht das Problem. Und eine Begriffsklärung hilft im Gespräch, zeigt aber nicht, wie das Ergebnis zustande kam.","coreRule":"⚡ Prüfe bei einem berühmten Beleg, wie das Ergebnis zustande kam und ob es sich unter anderen Bedingungen wiederholt.","quote":"","quoteLabel":"","scenario":"In der Mittagspause diskutiert ihr über Macht und Führung. Eine Kollegin sagt: „Das Stanford-Gefängnis-Experiment von 1971 beweist, dass ganz normale Menschen unter Macht automatisch zu Tyrannen werden.“","kurz":"Ein berühmter Befund ist noch kein belastbarer: Entscheidend ist, wie er zustande kam. In Stanford drängte die Studienleitung einen Wärter zu mehr Härte, deshalb sagt das Ergebnis wenig darüber, was Menschen von selbst tun.","prueffrage":"Was genau behauptet die Kollegin über normale Menschen, und was müsste ein Versuch zeigen, damit „automatisch“ stimmt?","rueckmeldung":[{"option":1,"text":"Der Schutz der Teilnehmenden ist eine wichtige ethische Frage und ein guter Anlass für Kritik an der Studie. Ob der Befund stimmt, klärt sie aber nicht: Dazu muss man wissen, wie das Ergebnis entstand."},{"option":2,"text":"Widerlegbarkeit ist ein gutes Prüfkriterium, und die Behauptung erfüllt es: Man kann sie an Daten prüfen. Dort liegt das Problem also nicht, sondern in der Frage, wie der berühmte Befund zustande kam."},{"option":3,"text":"Begriffe zu klären hilft im Gespräch und macht eine Prüfung leichter. Es zeigt aber nicht, wie das Ergebnis zustande kam, und genau davon hängt ab, wie viel der Befund wert ist."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the „Nature“ of Conformity: What Milgram and Zimbardo's Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"},{"typ":"doi","kurz":"Le Texier, T. (2019): Debunking the Stanford Prison Experiment. American Psychologist 74(7), 823–839","oeffentlich":false,"doi":"10.1037/amp0000401"},{"typ":"literatur","kurz":"Reicher, S. D.; Haslam, S. A. (2006): Rethinking the Psychology of Tyranny: The BBC Prison Study. British Journal of Social Psychology 45(1), 1–40","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ac670e99ac69c79d"}},{"id":"qe-11","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.4","stufe":1,"question":"Welche dieser Schlussfolgerungen aus dem Fall ist am besten begründet?","options":["Das Ergebnis kann ihre Erwartung bestätigen, weil ihr Verhalten auf seine Schwäche reagierte, sodass es Folge und nicht Ursache ist.","Das Ergebnis kann zum Teil durch das Verhalten der Lehrerin mitverursacht sein, sodass es ihre Erwartung nicht unabhängig bestätigt.","Das Ergebnis kann ihre Erwartung bestätigen, weil am Jahresende seine eigene Leistung gemessen wird, sodass ihr Verhalten kaum eine Rolle spielt.","Das Ergebnis kann auf Zufall beruhen, weil eine einzelne Jahresleistung schwankt, sodass es ihre Erwartung weder bestätigt noch widerlegt."],"correctIndex":1,"explanation":"Wenn eine Erwartung das eigene Handeln lenkt, kann sie mitverursachen, was sie vorhersagt: Wer weniger gefordert, beachtet und ermutigt wird, hat schlechtere Chancen, gut abzuschneiden. Das Eintreffen der Vorhersage ist dann kein unabhängiger Beleg dafür, dass sie von Anfang an stimmte. Diesen Mechanismus nennt man Golem-Effekt, die negative Seite des Pygmalion-Effekts. Solche Effekte sind nach der Forschungslage meist nur klein und wenig dauerhaft; hier lässt sich nur sagen, dass das Eintreffen die Erwartung nicht unabhängig bestätigt. Dass Erwartungen oft auch deshalb zutreffen, weil sie schlicht richtig waren, bleibt möglich. Um das zu klären, bräuchte man Leistungsdaten, die vom Verhalten der Lehrerin unabhängig sind.","coreRule":"⚡ Wenn eine Erwartung das Handeln lenkt, kann ihr Eintreffen nicht als unabhängiger Beweis für ihre Richtigkeit gelten.","quote":"","quoteLabel":"","scenario":"Eine Lehrerin ist überzeugt, dass ein Schüler „nicht viel auf dem Kasten hat“. Sie ruft ihn selten auf, gibt ihm nur einfache Aufgaben und lobt ihn kaum. Am Schuljahresende schneidet er schlecht ab. Die Lehrerin sagt: „Ich hab's ja gleich gewusst.“","beleg":"Werkstück E.3.4, Abschnitt „Kontext & Tiefe“ (Golem-Effekt), Hinweis zur Beleglage; Fußnote gl-e-rosenthal (Jussim/Harber 2005: Lehrererwartungen sagen Leistungen oft deshalb voraus, weil sie zutreffen).","kurz":"Wer weniger gefordert, beachtet und ermutigt wird, hat schlechtere Chancen, gut abzuschneiden. Das Ergebnis kann also zum Teil vom Verhalten der Lehrerin herrühren und bestätigt ihre Erwartung nicht unabhängig, auch wenn diese richtig gewesen sein kann.","prueffrage":"Welche Gelegenheiten hatte der Schüler im Lauf des Jahres, zu zeigen, was er kann?","rueckmeldung":[{"option":0,"text":"Dass ihr Verhalten auch auf tatsächliche Schwächen reagiert haben kann, ist möglich. Aber das Szenario nennt die Überzeugung der Lehrerin als Ausgangspunkt, und was sie danach tat, kann das Ergebnis mitbewirkt haben. Als bloße Folge lässt sich ihr Verhalten daher nicht verbuchen."},{"option":2,"text":"Gemessen wird am Ende zwar seine eigene Leistung. Doch wer kaum aufgerufen, nur mit einfachen Aufgaben bedacht und selten gelobt wird, hat schlechtere Chancen, gut abzuschneiden. Dass das Verhalten kaum eine Rolle spielt, lässt sich so nicht sagen."},{"option":3,"text":"Einzelne Jahresleistungen schwanken tatsächlich. Im Fall steht aber nichts, was auf Zufall hindeutet, dafür ein naheliegender Einfluss durch das Verhalten der Lehrerin. Deshalb bestätigt das Ergebnis die Erwartung nicht unabhängig, auch wenn sie damit nicht widerlegt ist."}],"familie":"erwartung-erfuellt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies: Knowns and Unknowns, Resolved and Unresolved Controversies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7496ca2e6270b57a"}},{"id":"qe-12","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.5","stufe":2,"question":"Welche Erklärung für das Vorgehen der Gruppe folgt der verbreiteten Deutung des Overton-Fensters?","options":["Die Gruppe nutzt den Mitläufereffekt, damit durch Studien und Medienberichte immer mehr Unentschlossene einer vermeintlichen Mehrheit folgen und sie bei der nächsten Wahl tragen.","Die Gruppe folgt dem Medianwähler-Prinzip, damit ihre Studien sie der Mitte der Wählerschaft annähern und sie dort bei der nächsten Wahl die meisten Stimmen gewinnt.","Die Gruppe will das Fenster der Akzeptanz verschieben, damit ihre Position später akzeptabel wirkt und Politiker sie ohne Risiko aufgreifen können.","Die Gruppe nutzt die Schweigespirale, damit ihre Position durch Studien und Medienberichte vorherrschend wirkt und Andersdenkende aus Furcht vor Isolation verstummen."],"correctIndex":2,"explanation":"Politiker, die wiedergewählt werden wollen, bewegen sich meist nur innerhalb dessen, was als akzeptabel gilt. Eine Position, die als undenkbar gilt, können sie nicht vertreten, ohne ihre Karriere zu riskieren. Nach der verbreiteten Deutung des Overton-Fensters zielt die Arbeit an den Rändern deshalb darauf, die Grenze des Diskutablen selbst zu verschieben. Overtons Kollegen beschreiben das nüchterner: als langsamen Wandel von Werten und Normen, zu dem unter anderem Thinktank-Forschung und Debatte beitragen. Das Beispiel des Rauchverbots zeigt das Muster: Zuerst galt es als Spinnerei, dann als radikal, dann kam der „Kompromiss“ für Krankenhäuser, später wurde es selbstverständlich. Niemand wurde über Nacht überzeugt, sondern der Rahmen des Akzeptablen hat sich verschoben.","coreRule":"⚡ Wer verschiebt, was als diskutabel gilt, verändert, was später als vernünftig durchgeht.","quote":"","quoteLabel":"","scenario":"Eine Gruppe vertritt öffentlich eine Position, die in der Gesellschaft bisher als so extrem gilt, dass kaum jemand sie ernsthaft diskutiert; eine Mehrheit bei der nächsten Wahl strebt sie nicht an. Sie veröffentlicht Studien zu ihrer Idee. Politiker, die wiedergewählt werden wollen, halten Abstand. Medien berichten darüber, meist spöttisch, aber sie berichten. Nach einigen Jahren schlagen gemäßigte Gruppen eine abgeschwächte Version „als Kompromiss“ vor.","beleg":"Werkstück E.3.5, Fußnote gl-e-overton: Lehman, J. G.: „The legacy of the Overton Window“, Mackinac Center, 30.06.2023","kurz":"Wer als Außenseiter keine Mehrheit sucht, will die Grenze des Diskutablen verschieben, damit seine Position später für Politiker vertretbar wird. Der naheliegende Fehler ist, ein bekanntes Wahl- oder Meinungsmodell überzustülpen, obwohl hier gar keine Mehrheit im Spiel ist.","prueffrage":"Was geschieht nach einigen Jahren mit der Idee, und wer greift sie dann auf?","rueckmeldung":[{"option":0,"text":"Mitläufer folgen einer Mehrheit, die sie schon sehen. Hier gilt die Position aber als so extrem, dass kaum jemand sie diskutiert, und die Gruppe strebt keine Mehrheit an. Es gibt also nichts, dem man sich anschließen könnte."},{"option":1,"text":"Das Medianwähler-Prinzip beschreibt Parteien, die zur Mitte rücken, um Stimmen zu holen. Die Gruppe bleibt aber bei ihrer Außenseiterposition und will keine Wahl gewinnen. Auf sie zu rückt am Ende die Mitte, nicht umgekehrt."},{"option":3,"text":"Eine Schweigespirale setzt voraus, dass eine Meinung als vorherrschend erscheint und andere deshalb verstummen. Hier gilt die Position jedoch als extrem, wird kaum diskutiert und von den Medien meist spöttisch behandelt. Als vorherrschend wirkt sie also nicht."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"},{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1709338d9d529a53"}},{"id":"qe-13","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.6","stufe":2,"question":"Wie solltest du die übereinstimmenden Erinnerungen der Geschwister bewerten?","options":["Als starken Beleg, weil zwei Erinnerungen übereinstimmen; dass beide unabhängig entstanden sind, macht einen Irrtum unwahrscheinlich.","Als starken Beleg, weil beide die Szene lebhaft und gefühlsstark schildern; so dichte Erinnerungen entstehen kaum ohne echtes Erlebnis.","Als schwachen Beleg, weil die Erzählungen der Tante und die Nachfrage des Bruders beide Erinnerungen geformt haben können.","Als widerlegt, weil die Eltern übereinstimmend widersprechen; zwei Erwachsene, die sich einig sind, wiegen schwerer als zwei Kinder."],"correctIndex":2,"explanation":"Das Gedächtnis ist kein Archiv, sondern wird bei jedem Abruf neu zusammengesetzt, und dabei können Erwartungen, wiederholte Erzählungen und suggestive Fragen die Erinnerung verändern. Die Forschung von Elizabeth Loftus zeigt: Manchen Menschen lassen sich falsche Erinnerungen an ganze Ereignisse einpflanzen, etwa ein Verlorengehen im Einkaufszentrum; wie vielen und wie vollständig, ist umstritten. Lebhaftigkeit, Sicherheit und Gefühl sagen daher wenig darüber, ob etwas geschah. Hier kann beim Bruder die oft gehörte Erzählung der Tante, bei der Schwester die suggestive Nachfrage des Bruders die Erinnerung geformt haben; die Übereinstimmung beweist daher wenig. Wer die beiden Erinnerungen für unabhängig hält, übersieht, dass der Bruder selbst nachgefragt hat, und wer auf die lebhafte, gefühlsstarke Schilderung baut, verwechselt Eindruck mit Beleg. Wer das Ereignis wegen der einigen Eltern für widerlegt hält, stützt sich auf denselben Schluss aus Übereinstimmung, obwohl auch ihre Erinnerung rekonstruiert ist.","coreRule":"⚡ Lebhaftigkeit und Sicherheit sind kein Beweis: Erinnerung ist Rekonstruktion, kein Archiv.","quote":"Das Gedächtnis ist kein Archiv, sondern ein Wikipedia-Eintrag -- es kann bei jedem Abruf neu geschrieben und bearbeitet werden.","quoteLabel":"Zum Weiterdenken:","scenario":"Eine Schwester und ein Bruder erinnern sich beide „ganz genau“ an einen Familienausflug, bei dem die Schwester als Kind im Einkaufszentrum verloren ging, und schildern die Szene lebhaft und mit starken Gefühlen. Die Eltern sagen, so etwas sei nie passiert. Der Bruder hat die Geschichte über Jahre immer wieder von einer Tante erzählt bekommen. Die Schwester wurde vor Kurzem vom Bruder suggestiv danach gefragt.","kurz":"Beide Erinnerungen können geformt sein: beim Bruder durch die oft gehörte Erzählung der Tante, bei der Schwester durch seine suggestive Nachfrage. Ob eine Erinnerung lebhaft und sicher ist, sagt wenig darüber, ob etwas geschah; die Übereinstimmung beweist daher wenig.","prueffrage":"Woher könnte jede der beiden Erinnerungen stammen, wenn das Ereignis nie stattgefunden hätte?","rueckmeldung":[{"option":0,"text":"Zwei übereinstimmende Erinnerungen wirken wie zwei Zeugen. Hier ist aber fraglich, ob sie unabhängig sind: Der Bruder hat die Schwester selbst suggestiv gefragt, und die Tante kann schon beim Bruder die Vorlage geliefert haben."},{"option":1,"text":"Eine lebhafte, gefühlsstarke Szene fühlt sich nach echtem Erleben an. Dichte Details und starke Gefühle entstehen aber auch bei falschen Erinnerungen; sie sagen wenig darüber, ob etwas geschah, und ersetzen keinen Beleg."},{"option":3,"text":"Dass die Eltern widersprechen, ist durchaus ein Gegenindiz, das Gewicht hat. Widerlegt ist das Ereignis damit aber nicht, denn auch ihre Erinnerung ist rekonstruiert, und die Einigkeit zweier Personen beweist für sich genommen wenig."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Murphy, G. u. a. (2023): Lost in the mall again: a preregistered replication and extension of Loftus & Pickrell (1995). Memory 31(6)","oeffentlich":true,"doi":"10.1080/09658211.2023.2198327"},{"typ":"doi","kurz":"Wade, K. A.; Riesthuis, P.; Bücken, C.; Otgaar, H.; Loftus, E. F. (2025): Still Lost in the Mall – False Memories Happen and That's What Matters. Applied Cognitive Psychology 39(1)","oeffentlich":true,"doi":"10.1002/acp.70028"},{"typ":"literatur","kurz":"Loftus, E. F.; Pickrell, J. E. (1995): The Formation of False Memories. Psychiatric Annals 25(12), 720–725","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"91e0d1185b13141d"}},{"id":"qe-14","status":"entwurf","clusterId":"E","werkstueckRef":"E.4.4","stufe":4,"question":"Welche Frage prüft seine Behauptung am besten?","options":["Wer behauptet die Fälschung, und welche Belege legt er dafür vor, während die Herkunft des Videos unabhängig bestätigt ist?","Wurde die Äußerung aus dem Zusammenhang gerissen, und wirkt sie im ganzen Auftritt vor den Anwesenden harmloser?","Wie häufig sind Fälschungen unter viral gehenden Videos, und wie wahrscheinlich ist es daher, dass dieses Video gefälscht ist?","Wie schwer wiegt die Äußerung moralisch, falls sie echt ist, und welche Konsequenzen sollte sie für den Politiker haben?"],"correctIndex":0,"explanation":"Wer ein Video als Fälschung bezeichnet, behauptet etwas und muss das belegen. Die bloße Möglichkeit von Deepfakes ist kein Beleg, sonst ließe sich jede unbequeme Aufnahme abtun („Lügner-Dividende“). Hier ist die Herkunft durch Augenzeugen und zwei unabhängige Agenturen bestätigt, während für die Fälschung nichts vorgelegt wird. Entscheidend sind Quelle, Bestätigung und Belege. Die Frage nach dem Zusammenhang ist bei Zitaten wichtig, trifft aber nicht die Behauptung, denn der Politiker behauptet eine Fälschung. Die allgemeine Häufigkeit von Fälschungen klingt nach nüchterner Wahrscheinlichkeit, sagt aber nichts über dieses Video, dessen Herkunft belegt ist. Wie schwer die Äußerung moralisch wiegt, ist eine andere Frage als die, ob sie echt ist.","coreRule":"⚡ Die Möglichkeit einer Fälschung ist kein Beleg für eine Fälschung: Die Beweislast liegt bei dem, der sie behauptet.","quote":"Wenn ein Politiker behauptet, ein echtes Video sei ein Fake -- wo sind seine Beweise für die Fälschung?","quoteLabel":"Prüffrage:","scenario":"Ein Politiker wird bei einer skandalösen Äußerung gefilmt, in einem Saal mit etwa hundert Anwesenden. Das Video stammt von mehreren Augenzeugen und wurde von zwei voneinander unabhängigen Nachrichtenagenturen aus verschiedenen Quellen bestätigt. Als es viral geht, sagt der Politiker: „Das ist bestimmt ein Deepfake.“ Belege dafür legt er nicht vor.","kurz":"Wer „Deepfake“ ruft, behauptet etwas und muss es belegen; die bloße Möglichkeit von Fälschungen genügt nicht. Hier ist die Herkunft bestätigt, für die Fälschung wird nichts vorgelegt. Entscheidend sind Quelle, Bestätigung und Belege.","prueffrage":"Wie viele Menschen waren im Saal, und wie viele von ihnen bestreiten, was das Video zeigt?","rueckmeldung":[{"option":1,"text":"Bei Zitaten ist die Frage nach dem Zusammenhang wichtig. Der Politiker behauptet aber nicht, die Äußerung sei verkürzt, sondern das Video sei gefälscht. Das ist eine andere Behauptung, und genau sie bleibt bei dieser Frage ungeprüft."},{"option":2,"text":"Eine Rate klingt nüchtern und genau. Sie sagt aber nur etwas über Videos im Allgemeinen, nicht über dieses: Seine Herkunft ist durch Augenzeugen und zwei unabhängige Agenturen bestätigt, und gegen solche konkreten Belege trägt eine Durchschnittszahl wenig."},{"option":3,"text":"Wie schwer die Äußerung wiegt, ist eine berechtigte, aber nachgelagerte Frage. Sie setzt die Echtheit schon voraus, statt zu klären, ob der Politiker mit seiner Fälschungsbehauptung recht hat. Genau das bleibt dabei ungeprüft."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Chesney, B.; Citron, D. (2019): Deep Fakes: A Looming Challenge for Privacy, Democracy, and National Security. California Law Review 107","oeffentlich":true,"doi":"10.15779/Z38RV0D15J"},{"typ":"doi","kurz":"Barari, S.; Lucas, C.; Munger, K. (2025): Political Deepfakes Are as Credible as Other Fake Media and (Sometimes) Real Media. The Journal of Politics 87(2)","oeffentlich":false,"doi":"10.1086/732990"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"faedcd5a87102a4a"}},{"id":"qe-15","status":"entwurf","clusterId":"E","werkstueckRef":"E.4.4 / Anhang VII.2","stufe":4,"question":"Was ist von dieser Begründung zu halten?","options":["Sie taugt nicht als Beleg: Das Modell kann kaum wissen, wo ein Bild erschienen ist, und eine fehlende Veröffentlichung macht ein Foto nicht unecht.","Sie ist schlüssig: Echte Pressefotos erscheinen in der Regel in Nachrichtenmedien, also spricht eine fehlende Veröffentlichung für ein erzeugtes Bild.","Sie ist ernst zu nehmen: Das Modell nennt einen konkreten Grund und urteilt selbstsicher, hat das Bild also offenbar mit Veröffentlichungen abgeglichen.","Sie ist ein erster Hinweis: Allein reicht sie nicht, doch zusammen mit dem klaren Urteil des Modells spricht schon einiges für ein erzeugtes Bild."],"correctIndex":0,"explanation":"Ein Sprachmodell schlägt die Herkunft eines Bildes meist nicht verlässlich nach, es formuliert eine plausibel klingende Antwort. Wo ein Foto erschienen ist, kann es deshalb oft gar nicht wissen, und selbst wenn: Fehlende Veröffentlichung macht ein Foto nicht unecht, denn Fotos können neu, unveröffentlicht oder nur in Archiven zu finden sein. Wie unzuverlässig solche Urteile sind, zeigte ein kleiner Test des Tow Center for Digital Journalism (Columbia Journalism Review, 2025): Alle getesteten Bilder waren echte, vielfach veröffentlichte Fotos professioneller Fotojournalisten, und trotzdem hielt jedes der sieben Modelle mindestens eines davon für KI-erzeugt. Vorbehalt: Es war ein kleiner Test mit Modellversionen vom Sommer 2025. Wer ein Foto prüft, klärt die Herkunft selbst: Urheber, Erstveröffentlichung, Bestätigung durch Dritte.","coreRule":"⚡ Auch ein „Das ist KI“ vom Sprachmodell ist kein Beleg: Prüfe die Herkunft des Bildes selbst.","quote":"Das Modell erklärt Echtes für erfunden.","quoteLabel":"Merksatz:","kurz":"Ein Sprachmodell kann die Herkunft eines Bildes meist nicht verlässlich nachschlagen, es formuliert nur eine plausible Antwort. Und eine fehlende Veröffentlichung macht ein Foto nicht unecht: Es kann neu, unveröffentlicht oder nur im Archiv zu finden sein.","prueffrage":"Worauf stützt das Modell seine Aussage, und wie könntest du selbst nachprüfen, ob und wo das Foto erschienen ist?","rueckmeldung":[{"option":1,"text":"Echte Pressefotos erscheinen meist in Nachrichtenmedien, das stimmt. Doch ein Foto kann neu, unveröffentlicht oder nur in Archiven zu finden sein, und das Modell kann den Erscheinungsort oft gar nicht verlässlich prüfen."},{"option":2,"text":"Ein genannter Grund und ein sicherer Ton wirken gründlich. Das Modell formuliert aber meist nur eine plausibel klingende Antwort, ohne die Herkunft nachzuschlagen. Selbstsicherheit zeigt hier nicht, dass etwas abgeglichen wurde."},{"option":3,"text":"Dass die Begründung allein nicht reicht, stimmt. Das klare Urteil stützt sie aber nicht: Es kommt aus derselben unzuverlässigen Quelle und ist kein unabhängiger zweiter Hinweis. Selbst bei echten, vielfach veröffentlichten Fotos lagen Modelle im Test daneben."}],"familie":"ki-ausgabe-pruefen","fertigkeit":"F1","scenario":"Du zeigst einem Sprachmodell ein Pressefoto und fragst, ob es KI-erzeugt ist. Es antwortet selbstsicher: „Ja, das Bild ist KI-erzeugt, denn es ist in keinem Nachrichtenmedium erschienen.“","beleg":"Chandrasekar, A.; Jaźwińska, K. (2025): Tow Center for Digital Journalism, Columbia Journalism Review, Test von sieben Sprachmodellen mit echten Pressefotos. Wortlaut (von Sturm am 12.10.2026 im Bericht geprüft): „Although all the pictures we tested were authentic, widely published photos taken by professional photojournalists and published by reputable publications, each model we tested misidentified at least one real photo as AI-generated when we asked.“ Die Begründung „in keinem Nachrichtenmedium erschienen“ ist eine Erfindung für das Beispiel.","quellen":[{"typ":"url","kurz":"Chandrasekar, A.; Jaźwińska, K. (2025): Why AI Models Are Bad at Verifying Photos. Columbia Journalism Review, 26.08.2025","oeffentlich":true,"url":"https://www.cjr.org/tow_center/why-ai-models-are-bad-at-verifying-photos.php","abruf":"2026-10-08"}],"thema":"Technik und KI"},{"id":"qf-1","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.1","stufe":2,"question":"Eine Forscherin erklärt: „Meine Idee klingt seltsam, aber seltsam heißt nicht falsch.“ Woran erkennst du, ob ihre Idee eher spekulative Forschung am Rand der Wissenschaft oder Pseudowissenschaft ist?","options":["Entscheidend ist, wie weit die Idee von etablierten Theorien abweicht, denn je ungewöhnlicher sie klingt, desto verdächtiger ist sie, bei Gruppe X wie bei Gruppe Y.","Entscheidend ist, ob die Idee testbar bleibt und die Gruppe bereit ist, sie bei Gegenbeweisen aufzugeben, wie es Gruppe X vorab festlegt.","Entscheidend ist, ob die Fachwelt die Idee bereits anerkennt, denn solange weder Gruppe X noch Gruppe Y breite Zustimmung hat, bleibt ihr Status offen.","Entscheidend ist, ob sich die Idee in den Experimenten am Ende bestätigt, denn erst dann lässt sich Gruppe X von Gruppe Y unterscheiden."],"correctIndex":1,"explanation":"Seltsamkeit allein sagt nichts: Auch Grenzwissenschaft kann spekulativ und seltsam aussehen, bleibt aber eine testbare Hypothese. Pseudowissenschaft erkennst du am Verhalten gegenüber Gegenbeweisen: Sie ahmt die äußere Form der Wissenschaft nach (Jargon, Rituale, angebliche „Beweise“), macht ihre Behauptungen aber durch Ad-hoc-Ausreden unwiderlegbar und erklärt Misserfolge weg. Die spätere Bestätigung kannst du erst hinterher wissen; du brauchst ein Kriterium, das schon vorher greift.","coreRule":"⚡ Die Methode entscheidet, nicht die Seltsamkeit der Idee.","quote":"Eine Idee kippt in Pseudowissenschaft, wenn sie aufhört, eine testbare Hypothese zu sein, und zu einem dogmatischen, unfehlbaren Glaubenssystem wird.","quoteLabel":"Merksatz:","scenario":"Zwei Gruppen vertreten jeweils eine ungewöhnliche Idee. Gruppe X plant Experimente, die ihre Hypothese klar widerlegen könnten, und hat vorab festgelegt, welche Ergebnisse sie als Scheitern werten würde. Gruppe Y bleibt bei einer Erklärung, die seit Jahrhunderten unverändert ist; bleibt ein Effekt aus, heißt es, die Skepsis der Testpersonen habe ihn blockiert.","beleg":"Werkstück F.1.1 (Kernidee, Checkliste Punkt 2, 4 und 6, Kipppunkt); Fußnote gl-f-cargo nicht einschlägig","kurz":"Entscheidend ist, wie eine Gruppe mit möglichen Gegenbeweisen umgeht: Gruppe X legt vorab fest, was sie widerlegen würde, Gruppe Y erklärt jedes Ausbleiben weg. Ungewöhnlich sind beide, das trennt sie also nicht.","prueffrage":"Beide Gruppen vertreten eine ungewöhnliche Idee: Worin unterscheiden sie sich dann überhaupt?","rueckmeldung":[{"option":0,"text":"Ein Misstrauen gegenüber sehr ungewöhnlichen Behauptungen ist nicht unvernünftig. Als Maßstab trägt es aber nicht, denn beide Ideen sind ungewöhnlich, und auch gute neue Ideen weichen vom Etablierten ab."},{"option":2,"text":"Dass eine neue Idee anfangs wenig Zustimmung hat, ist normal und sagt wenig über ihren Wert. Zudem gründet Pseudowissenschaft eigene „Institute“ und „Fachzeitschriften“, die Anerkennung vortäuschen, wenn die Fachwelt sie nicht gibt."},{"option":3,"text":"Ob sich eine Idee bestätigt, zeigt sich erst im Nachhinein, du brauchst aber ein Kriterium, das vorher greift. Eine testbare Hypothese, die scheitert, ist zudem keine Pseudowissenschaft, sie ist schlicht widerlegt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 3.2, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0313c6d81ac243cf"}},{"id":"qf-2","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.4","stufe":3,"question":"Du fragst dich, ob eine Gruppe, der eine Freundin beigetreten ist, kontrollierend arbeitet. Welche Beobachtung ist ein Hinweis auf Informationskontrolle?","options":["Die Gruppe hält deine Freundin von kritischen Quellen fern und gibt zentrales Wissen nur gestuft weiter.","Die Gruppe füllt den Alltag deiner Freundin mit Treffen und Aufgaben, sodass kaum Zeit für Freunde bleibt.","Die Gruppe schenkt deiner Freundin Herzlichkeit nur bei Wohlverhalten und weckt bei Zweifeln gezielt Schuldgefühle.","Die Gruppe bringt deiner Freundin bei, aufkommende Zweifel mit festen Schlagworten und Wiederholungen zu ersticken."],"correctIndex":0,"explanation":"Informationskontrolle zeigt sich daran, dass kritische Quellen verboten oder abgewertet werden und Wissen nur gestuft weitergegeben wird. Genau das schildert deine Freundin: Kritik wird vorab als „Propaganda von Abtrünnigen“ abgestempelt, und die wichtigen Lehren sind nur höheren Stufen zugänglich, sodass niemand die Behauptungen der Gruppe von außen prüfen kann. Erst wenn mehrere Kontrollmerkmale (bei Verhalten, Information, Denken und Gefühlen) zusammenkommen und stark ausgeprägt sind, spricht das für manipulative Kontrolle; ein einzelnes Merkmal beweist noch nichts. Checklisten wie das BITE-Modell sind dabei Beratungshilfen, keine gesicherten Messinstrumente. Die anderen Beobachtungen sind für sich ernst zu nehmen, betreffen aber andere Bereiche. Ein ausgefüllter Alltag ohne Zeit für Freunde wäre Verhaltenskontrolle und erklärt nicht, wer was lesen darf. Zuwendung nur bei Wohlverhalten und gezielte Schuldgefühle wären Kontrolle der Gefühle, und die Herzlichkeit der Gruppe ist hier an keine Bedingung geknüpft. Ein eingeübtes Ersticken von Zweifeln mit Schlagworten wäre Kontrolle des Denkens, nicht des Zugangs zu Wissen.","coreRule":"⚡ Prüfe bei einer Gruppe die Struktur, nicht das Bekenntnis: Darf man ihre Behauptungen von außen überprüfen und kritisieren?","quote":"","quoteLabel":"","scenario":"Seit einigen Monaten ist deine Freundin Mitglied einer Gruppe, die sich „Aufbruch“ nennt. Sie erzählt, dass dort alle sehr herzlich miteinander umgehen. Neuerdings ruft sie kaum noch an. Als du sie auf einen kritischen Zeitungsartikel über die Gruppe ansprichst, sagt sie: „Das ist Propaganda von Abtrünnigen, so etwas lesen wir nicht. Die wichtigen Lehren gibt es sowieso erst für Mitglieder der höheren Stufen.“","kurz":"Kritik vorab als „Propaganda“ abzustempeln und wichtige Lehren nur höheren Stufen zu geben, verhindert die Prüfung von außen. Das ist Informationskontrolle. Ein einzelnes Merkmal beweist aber noch keine Manipulation; erst mehrere zusammen sprechen dafür.","prueffrage":"Was erzählt die Freundin über die Gruppe, und was davon fände man in einem Sportverein genauso?","rueckmeldung":[{"option":1,"text":"Ein Alltag ohne Zeit für Freunde wäre ernst zu nehmen, er betrifft aber das Verhalten und nicht den Zugang zu Wissen. Im Szenario steht außerdem nur, dass sie kaum noch anruft, nicht dass Treffen und Aufgaben ihren Alltag füllen."},{"option":2,"text":"Zuwendung nur bei Wohlverhalten und gezielte Schuldgefühle wären Kontrolle der Gefühle. Hier wird die Herzlichkeit der Gruppe aber ohne Bedingung geschildert, und von Schuldgefühlen ist nirgends die Rede."},{"option":3,"text":"Zweifel mit Schlagworten zu ersticken wäre Kontrolle des Denkens, also der Umgang mit eigenen Gedanken. Ihr Satz betrifft dagegen, welche Quellen sie überhaupt lesen darf, und von Schlagworten oder Wiederholungen steht dort nichts."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","seite":"Abschnitt II. Information Control","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aa30f1fbfbe5819d"}},{"id":"qf-3","status":"entwurf","clusterId":"F","werkstueckRef":"F.0","stufe":2,"question":"Ein Kritiker sagt über die Suche nach außerirdischer Intelligenz (SETI): „Das ist genauso schlimm wie Astrologie, denn gefunden wurde bisher nichts.“ Welcher Denkfehler steckt in diesem Argument?","options":["Er stellt SETI und Astrologie auf eine Stufe, obwohl beide so verschiedene Themen behandeln, dass man sie nicht vergleichen kann.","Er verlangt von SETI einen Fund, obwohl eigentlich er belegen müsste, dass es keine außerirdische Intelligenz gibt.","Er setzt „bisher nichts gefunden“ mit „widerlegt“ gleich und übersieht, dass die SETI-Suche prinzipiell überprüfbar bleibt.","Er setzt Spott an die Stelle von Gründen, denn der Vergleich mit Astrologie soll SETI lächerlich machen, statt sie zu prüfen."],"correctIndex":2,"explanation":"Ein Ausbleiben von Funden ist nicht dasselbe wie Widerlegung oder fehlende Methode. Die Suche nach außerirdischer Intelligenz zählt zur Grenzwissenschaft: spekulativ, aber prinzipiell empirisch überprüfbar. Ihr Zustand ist „nicht bewiesen“, nicht „widerlegt“. Eine Hypothese darf also unbewiesen sein und trotzdem ehrlich geprüft werden. Astrologie unterscheidet sich darin: Widersprüchliche Befunde werden ignoriert oder wegerklärt, und die Lehren bleiben seit ihrer Gründung oft unverändert und dogmatisch. Entscheidend ist also die Methode, nicht der bisherige Erfolg oder die Seltsamkeit der Idee.","coreRule":"⚡ „Nicht bewiesen“ und „widerlegt“ sind zwei verschiedene Zustände. Beurteile die Methode, nicht den bisherigen Misserfolg.","quote":"Konzentriere dich auf die Methode, nicht auf die Seltsamkeit der Behauptung.","quoteLabel":"Merksatz","beleg":"Werkstück F.0, Red Flags und Abschnitt Grenzwissenschaft (SETI als Beispiel); Fußnote gl-f-string zur Prüfbarkeitsdebatte","kurz":"„Bisher nichts gefunden“ heißt nicht „widerlegt“: Die Suche bleibt prinzipiell überprüfbar, ihr Stand ist „nicht bewiesen“. Der Fehler liegt darin, Erfolg zum Maßstab zu machen, obwohl die Methode entscheidet, ob etwas ehrlich geprüft wird.","prueffrage":"Welchen Teil des Himmels und der möglichen Funkfrequenzen hat die Suche bisher überhaupt abgedeckt?","rueckmeldung":[{"option":0,"text":"Ein Vergleich ist durchaus möglich, auch bei verschiedenen Themen: Man kann fragen, wie beide mit Befunden umgehen. Genau dort liegt der Unterschied, nicht in der Verschiedenheit der Themen."},{"option":1,"text":"Der Gedanke an die Beweislast klingt fair, trifft aber nicht den Kern. Niemand muss die Abwesenheit beweisen; entscheidend ist, dass „unbewiesen“ nicht „widerlegt“ bedeutet und eine Hypothese trotzdem sauber geprüft werden darf."},{"option":3,"text":"Der Vergleich wirkt tatsächlich abwertend, und der Satz nennt zugleich einen Grund, nämlich den fehlenden Fund. Dieser Grund trägt nicht, und das ist der eigentliche Fehler; die abwertende Wirkung ist nur das Beiwerk."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d56e4e265bae133f"}},{"id":"qf-4","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.2","stufe":1,"question":"Welche Erklärung ist am sparsamsten, und wie ließe sie sich am besten prüfen?","options":["Der Kollege dürfte recht haben: Das Futter kam alle 15 Sekunden, und eine so regelmäßige Abfolge von Ritual und Futter spricht für einen Zusammenhang. Prüfen ließe sich das, indem man genau zählt, wie oft das Ritual dem Futter vorausgeht.","Der Kollege könnte falsch liegen: Das Futter kam alle 15 Sekunden, egal was die Tauben taten. Ein Verhalten kurz vor dem Futter kann zufällig mit ihm zusammengefallen sein. Prüfen ließe sich das, indem man schaut, ob das Futter ohne Ritual genauso kommt.","Der Kollege könnte falsch liegen: Die Tauben haben sich Kreisdrehen und Kopfstoßen voneinander abgeschaut, denn Nachahmung breitet Verhalten in Gruppen rasch aus. Prüfen ließe sich das, indem man mehrere Tauben gemeinsam in eine Box setzt.","Der Kollege dürfte recht haben: Hungrige Tauben probieren vieles aus und behalten, was ihnen Futter bringt, daher sind Kreisdrehen und Kopfstoßen Lernerfolge. Prüfen ließe sich das mit Tauben, die Futter erst nach einer bestimmten Handlung bekommen."],"correctIndex":1,"explanation":"Die Fütterung folgte einem starren Zeittakt und hing von keiner Handlung ab. Skinner deutete die Rituale so, dass sich ein Verhalten, das zufällig kurz vor dem Futter auftrat, eingeprägt haben könnte: Gelernt haben die Tauben also durchaus etwas, aber ihr Ritual holte das Futter nicht herbei. Die sparsamste Erklärung braucht deshalb keinen echten Zusammenhang, denn bei festem Takt folgt das Futter immer irgendeinem Verhalten. Prüfen lässt sich das, indem man schaut, ob das Futter auch ohne Ritual genauso kommt. Spätere, genauere Wiederholungen des Versuchs deuteten vieles, was nach Ritual aussah, als gewöhnliches Pickverhalten kurz vor dem Futter oder als vom Fütterungstakt selbst hervorgelockt; eine gut passende Deutung ist also noch nicht die einzig mögliche.","coreRule":"⚡ Danach heißt nicht deswegen: Ein „wirksames“ Ritual belegt noch keine Ursache, solange nicht geprüft ist, was ohne das Ritual geschieht.","quote":"","quoteLabel":"","scenario":"Eine Forscherin setzt hungrige Tauben einzeln in eine Box, in der alle 15 Sekunden automatisch für einige Sekunden Futter erscheint, egal was die Tauben tun. Nach einiger Zeit zeigen mehrere Tauben auffällige Rituale: Eine dreht sich ständig im Kreis, eine andere stößt immer wieder mit dem Kopf in eine Ecke. Ein Kollege sagt: „Die Tauben haben offenbar gelernt, dass ihr Ritual das Futter herbeiholt.“","beleg":"Werkstück F.1.2, Fußnote gl-f-4 (Skinner 1948; Staddon & Simmelhag 1971)","kurz":"Das Futter kam im festen Takt, ganz gleich, was die Tauben taten; ein Verhalten kurz davor kann sich schlicht zufällig eingeprägt haben. Der Fehler ist, aus „folgte aufeinander“ auf „bewirkte“ zu schließen. Prüfen lässt es sich, indem man schaut, ob das Futter auch ohne Ritual kommt.","prueffrage":"Wann genau kam das Futter, und was taten die Tauben jeweils unmittelbar davor?","rueckmeldung":[{"option":0,"text":"Dass dem Futter oft ein Ritual vorausging, stimmt. Bei festem Takt geht dem Futter aber immer irgendein Verhalten voraus, deshalb unterscheidet das Zählen Zufall nicht von Wirkung. Die Regelmäßigkeit stammt vom Takt der Anlage."},{"option":2,"text":"Nachahmung verbreitet Verhalten in Gruppen tatsächlich rasch. Hier saß aber jede Taube allein in der Box und zeigte ein anderes Ritual, es gab also nichts abzuschauen. Eine Gruppe zu testen, prüft zudem eine andere Frage als die des Kollegen."},{"option":3,"text":"Verhalten, das Futter bringt, wird tatsächlich beibehalten, und der Test mit handlungsabhängigem Futter wäre sinnvoll. Hier kam das Futter aber unabhängig von jeder Handlung, die Rituale bringen es nicht herbei. Eingeprägt haben sie sich nur durch zufälliges Zusammentreffen."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): „'Superstition' in the Pigeon“, Journal of Experimental Psychology 38 (Nachdruck Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Staddon, J. E. R.; Simmelhag, V. L. (1971): „The ‚Superstition‘ Experiment: A Reexamination …“, Psychological Review 78(1)","oeffentlich":false,"doi":"10.1037/h0030305"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"6a465dd91135c563"}},{"id":"qf-5","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.3","stufe":2,"question":"Ein Bekannter sagt: „Verschwörungen gibt es nicht. Dass Menschen im Geheimen zusammenarbeiten, ist reine Fantasie.“ Ein anderer behauptet: „Ein Konzern hält seit 40 Jahren zusammen mit Tausenden Mitwissern ein Geheimnis, und bisher hat niemand geplaudert.“ Welche Prüffrage trennt eine reale Verschwörung am besten von einem Verschwörungsmythos?","options":["Wie viele Personen müssten eingeweiht sein, welches begrenzte Ziel verfolgen sie, und wie lange hielte das Geheimnis?","Wem nützt die Behauptung, und welche Interessen haben diejenigen, die sie verbreiten und weitererzählen?","Ist die Behauptung in sich widerspruchsfrei, und erklärt sie die bekannten Ereignisse schlüssig und ohne Lücken?","Gab es früher schon Fälle, in denen ähnliche Absprachen nachweislich aufgedeckt wurden, und wie sahen sie aus?"],"correctIndex":0,"explanation":"Echte Verschwörungen wie Watergate oder der Iran-Contra-Skandal hatten eine begrenzte Zahl von Beteiligten und erreichbare Ziele, und sie wurden durch Lecks, Inkompetenz oder Recherche aufgedeckt. Je mehr Mitwisser, desto schneller fliegt ein Geheimnis auf. Eine Behauptung, die Tausende Eingeweihte über Jahrzehnte hinweg perfekt schweigen lässt, ist deshalb extrem unwahrscheinlich. Die pauschale Leugnung jeder Verschwörung ist ebenfalls falsch, denn echte Fälle existieren. Die anderen Prüffragen sind für sich vernünftig, trennen hier aber nicht: Motive haben echte Verschwörer und Mythenerzähler gleichermaßen. Auch ein ausgedachtes Geheimnis kann in sich stimmig klingen. Und dass es früher aufgedeckte Fälle gab, zeigt nur, dass Verschwörungen vorkommen, nicht, ob gerade diese Behauptung stimmt.","coreRule":"⚡ Zähle Mitwisser, Ziele und Lecks: Echte Verschwörungen sind begrenzt, Mythen grenzenlos.","quote":"","quoteLabel":"","scenario":"","kurz":"Entscheidend ist, wie viele Mitwisser nötig wären und wie lange sie schweigen müssten: Je mehr Eingeweihte, desto eher fliegt ein Geheimnis auf. Echte Verschwörungen waren begrenzt. Pauschales Leugnen ist ebenso falsch wie jede Geschichte glauben.","prueffrage":"Könnten beide Aussagen zugleich falsch sein, und woran würdest du das jeweils festmachen?","rueckmeldung":[{"option":1,"text":"Nach dem Nutzen zu fragen, gehört zum sorgfältigen Prüfen. Hier trennt es aber nicht, denn echte Verschwörer und Erzähler von Mythen haben gleichermaßen Motive. Ein Interesse macht eine Behauptung weder wahr noch falsch."},{"option":2,"text":"Widerspruchsfreiheit ist eine vernünftige Anforderung, reicht aber nicht aus. Auch eine frei erfundene Geschichte kann in sich stimmig klingen und alle bekannten Ereignisse lückenlos erklären. Stimmigkeit allein zeigt nicht, ob sie zutrifft."},{"option":3,"text":"Dass früher Absprachen nachweislich aufgedeckt wurden, stimmt und widerlegt die pauschale Leugnung. Es zeigt aber nur, dass Verschwörungen vorkommen, nicht, ob gerade diese Behauptung zutrifft."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): „On the Viability of Conspiratorial Beliefs“, PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0baf1f9d7933e3c9"}},{"id":"qf-6","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":2,"question":"Ein Video raunt: „Dass wir keine Beweise finden, beweist nur, wie perfekt alles vertuscht wird!“ Was ist an diesem Schluss fehlerhaft?","options":["Er kehrt die Beweislast um: Wer widerspricht, soll erst beweisen, dass es nicht so gewesen ist.","Er greift winzige Auffälligkeiten heraus und bläht sie auf, während der große Rest der Daten verschwindet.","Er wertet fehlende Belege als Beleg für perfekte Tarnung, sodass jede Suche die Behauptung nur bestätigt.","Er verzerrt die gängige Erklärung zur Karikatur, damit sie bei den Zuschauern Wut und Angst auslöst."],"correctIndex":2,"explanation":"Der Schluss ist so gebaut, dass nichts ihn widerlegen kann: Findet man keine Beweise, gilt das als Zeichen perfekter Vertuschung; und auch ein Gegenbeweis würde als Teil der Verschwörung umgedeutet. Genau das ist das Warnsignal „Das Fehlen von Beweisen wird als Beweis gewertet“ (Argument aus Unwissenheit); zugleich ist die Erzählung unfalsifizierbar, denn es gibt kein Ereignis, das den Gläubigen von seiner Meinung abbringen könnte. Eine Behauptung, die kein Ereignis widerlegen kann, ist keine robuste Hypothese, sondern eine Festung des Glaubens. Die anderen Muster kommen in Verschwörungserzählungen ebenfalls vor, stecken aber nicht in diesem einen Satz.","coreRule":"⚡ Fehlende Belege sind kein Beleg für perfekte Tarnung.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück F.1.3.1, Warnsignal 3 (Argument aus Unwissenheit, B.11); Warnsignal 4 (Unfalsifizierbarkeit, A.3)","kurz":"Findet man keine Beweise, gilt das als Zeichen perfekter Vertuschung, und selbst ein Gegenbeweis würde umgedeutet. So werden fehlende Belege zum Beleg, und die Behauptung ist gegen jede Prüfung abgeschirmt.","prueffrage":"Was hat die Suche nach Beweisen laut dem Video ergeben, und wie wird dieses Ergebnis gedeutet?","rueckmeldung":[{"option":0,"text":"Beweislastumkehr kommt in solchen Erzählungen tatsächlich oft vor. Im Satz verlangt aber niemand, etwas zu widerlegen; er deutet das Ausbleiben von Belegen selbst zum Beleg um. Genau dort liegt das Problem."},{"option":1,"text":"Das Herausgreifen kleiner Auffälligkeiten ist ein verbreitetes Muster, und es klingt hier nach Verschwörungsdenken. Der Satz stützt sich aber auf keine einzelnen Daten, sondern darauf, dass keine gefunden werden."},{"option":3,"text":"Eine verzerrte Gegenposition und gezielte Angstmache gehören oft zu solchen Erzählungen. In diesem Satz wird aber keine Erklärung angegriffen; er schützt vielmehr die eigene Behauptung davor, jemals widerlegt zu werden."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Eintrag „Appeal to Ignorance“","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Immune to evidence“","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8e30be1af01c22e4"}},{"id":"qf-7","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.5","stufe":2,"question":"Ein unbekanntes „Institut“ behauptet, ein Nahrungsergänzungsmittel senke den Blutdruck. Die Studie hat keine Kontrollgruppe, bleibt unveröffentlicht, ist aber voller Fachjargon und Grafiken. Welche Frage prüft am besten, ob hier echte Forschung vorliegt oder nur ihre äußere Form?","options":["Hätte die Studie des Instituts auch einen Blutdruckverlauf zeigen können, der der Behauptung widerspricht, oder konnte sie nur bestätigen?","Haben die Autoren des Instituts eine fachliche Ausbildung, und setzen sie Fachbegriffe und Grafiken so ein, wie es in der Forschung üblich ist?","Wie groß ist der Blutdruckeffekt, den das Institut behauptet, und wäre er für Betroffene im Alltag überhaupt spürbar und von Nutzen?","Ist ein Wirkmechanismus bekannt, über den das Mittel den Blutdruck beeinflussen könnte, und wie plausibel ist er nach heutigem Wissen?"],"correctIndex":0,"explanation":"Entscheidend ist nicht, wie die Studie aussieht, sondern ob sie ehrlich scheitern könnte. Echte Forschung berichtet auch Beweise, die der eigenen Theorie widersprechen, und sucht aktiv nach Wegen, sie zu widerlegen; Kontrollgruppen und Replizierbarkeit gehören zu dieser methodischen Strenge. Jargon, Grafiken und Institutsname lassen sich beliebig kopieren, ohne dass die Methode dahintersteht. Der Nobelpreisträger Richard Feynman nannte das „Cargo-Kult-Wissenschaft“: Inselbewohner im Pazifik ahmten nach dem Abzug der US-Soldaten deren Rituale nach, legten Landebahnen an, zündeten Feuer an und setzten einen Mann mit Holzkopfhörern in eine Hütte. Die Form stimmte, aber ihnen fehlte das Verständnis der zugrundeliegenden Prinzipien, und die Flugzeuge kamen nicht. Die Frage nach der Chance auf Widerlegung trennt Landebahn und Flugzeug.","coreRule":"⚡ Prüfe nicht, wie wissenschaftlich etwas aussieht, sondern ob es scheitern könnte: Kontrollgruppe, Replikation, berichtete Gegenbefunde.","quote":"Er hat die Landebahn, aber ihm fehlt der Geist der Wissenschaft.","quoteLabel":"Cargo-Kult-Wissenschaft","scenario":"Ein Freund schickt dir die Studie und sagt: „Das ist doch wissenschaftlich belegt, sieh dir allein die vielen Grafiken an!“","beleg":"Werkstück F.1.5, Fußnote gl-f-7 (Feynman, „Cargo Cult Science“, Caltech 1974)","kurz":"Entscheidend ist, ob die Studie ehrlich hätte scheitern können. Jargon, Grafiken und Institutsname lassen sich nachahmen, ohne dass Methode dahintersteht; echte Forschung sucht auch nach Wegen, die eigene Behauptung zu widerlegen.","prueffrage":"Womit wurden die Werte der Teilnehmenden verglichen, und wo lässt sich die Studie nachlesen?","rueckmeldung":[{"option":1,"text":"Eine fachliche Ausbildung ist ein Hinweis, aber kein Beweis für saubere Arbeit. Jargon und Grafiken lassen sich auch ohne Methode imitieren, und selbst Ausgebildete können ohne Kontrollgruppe nur Bestätigung liefern."},{"option":2,"text":"Die Größe eines Effekts ist wichtig, aber erst, wenn feststeht, dass er überhaupt belastbar gemessen wurde. Ohne Kontrollgruppe ist auch eine behauptete Größe nicht verlässlich und sagt nichts über die Qualität der Forschung."},{"option":3,"text":"Ein plausibler Mechanismus macht eine Behauptung glaubwürdiger, ersetzt aber keine Prüfung. Eine Studie kann einen schönen Mechanismus anführen und trotzdem nur bestätigen können; der Test, ob sie scheitern könnte, bleibt offen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11–12","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8416f2e480ab02fd"}},{"id":"qf-8","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.6","stufe":4,"question":"Ein hochintelligenter Autor, berühmt für einen streng logisch denkenden Romandetektiv, hält inszenierte Feenfotos nach schweren persönlichen Verlusten im Ersten Weltkrieg für Beweise einer geistigen Welt. Seine Kritiker fragen, wie das möglich ist. Welche Erklärung ist am sparsamsten und erklärt zugleich, warum seine Intelligenz ihn nicht schützte?","options":["Er kannte die Fototechnik seiner Zeit zu wenig und deutete die Papierfiguren und Nadeln auf den Bildern daher falsch.","Er setzte seinen Verstand ein, um einen tröstlichen Glauben zu verteidigen, statt die Bilder ergebnisoffen zu prüfen.","Er wurde von den Urhebern der Bilder planvoll getäuscht und merkte nicht, dass sie seine Gutgläubigkeit gezielt ausnutzten.","Er prüfte die Bilder gründlich, fand dabei keinen Fälschungsnachweis und hielt sie deshalb für echte Aufnahmen von Feen."],"correctIndex":1,"explanation":"Gesucht ist eine Erklärung, die das Fehlurteil erklärt und zugleich, warum Intelligenz nicht davor schützte. Das gelingt, wenn man Intelligenz als Werkzeug versteht: Wer unbedingt glauben will, setzt seinen Verstand ein, um für den Glauben zu argumentieren, statt ihn ergebnisoffen zu prüfen. Conan Doyle suchte nach den Verlusten des Ersten Weltkriegs Trost im Fortleben der Toten, und die Fotos waren für ihn eher Bestätigung als offene Frage. Mangelndes Wissen über Fototechnik erklärt nicht, warum ein scharfer Denker so bereitwillig darauf hereinfiel. Die Mädchen hatten mit einem Scherz begonnen und gaben erst 1983 zu, mit Papierfiguren und Hutnadeln gearbeitet zu haben (nur ein Bild hielt Frances weiter für echt); dass sie ihn gezielt für eigene Zwecke benutzten, ist nicht belegt, und auch eine Täuschung erklärt nicht, warum er so wenig kritisch war. Und dass bei einer Begutachtung kein Fälschungsnachweis gefunden wurde, belegt noch keine Echtheit.","coreRule":"⚡ Kritisches Denken ist eine Praxis, die man anwenden muss, keine Eigenschaft, die man besitzt: Je stärker das Bedürfnis zu glauben, desto eher dient die Intelligenz dem Wunsch statt der Prüfung.","quote":"","quoteLabel":"","scenario":"","kurz":"Intelligenz ist ein Werkzeug: Wer unbedingt glauben will, setzt sie ein, um den Glauben zu verteidigen, statt ergebnisoffen zu prüfen. So wurden die Fotos für den trauernden Autor eher zur Bestätigung als zur offenen Frage.","prueffrage":"Was hätte ein fehlender Fälschungsnachweis über die Echtheit der Bilder gesagt, und wie ging der Autor damit um?","rueckmeldung":[{"option":0,"text":"Von der Fototechnik verstand er vermutlich weniger als Fachleute, und die Fälschung bestand tatsächlich aus Papierfiguren und Nadeln. Doch fehlendes Wissen erklärt nicht, warum ein scharfer Denker so bereitwillig glaubte."},{"option":2,"text":"Die Bilder waren tatsächlich gestellt, der Scherz der Mädchen war ihr Ursprung. Dass sie seine Gutgläubigkeit gezielt ausnutzten, ist aber nicht belegt, und Täuschung allein erklärt auch nicht, warum er so wenig kritisch blieb."},{"option":3,"text":"Dass keine Fälschung nachgewiesen wurde, wirkt wie ein Echtheitsbeweis. Wer nichts findet, hat aber noch nichts bewiesen. Und warum er so offen für diesen Schluss war, bleibt dabei ungeklärt."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies (Papierfiguren mit Hutnadeln, Geständnis 1983)","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M.; Peters, E.; Dawson, E. C.; Slovic, P. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper, Yale Cultural Cognition Project)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3a65fae17b1ed610"}},{"id":"qf-9","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.7","stufe":3,"question":"Eine Biologin sagt: „Das bakterielle Flagellum besteht aus vielen Teilen, die nur im Zusammenspiel funktionieren. Entfernt man ein Teil, geht die Fortbewegung verloren. Also kann es nicht schrittweise entstanden sein, es muss geplant worden sein.“ Welche Antwort trifft den Fehler in diesem Schluss am besten?","options":["Der Schluss übersieht, dass Teile des Flagellums früher einen anderen Nutzen gehabt haben können und später in ein neues System eingebaut wurden.","Der Schluss übersieht, dass ein unfertiges Flagellum als Vorstufe erhalten bleiben kann, bis die übrigen Teile dazukommen und es funktioniert.","Der Schluss übersieht, dass die Teile einzeln nacheinander dazugekommen sein können und jedes neue Teil die Fortbewegung ein Stück verbessert hat.","Der Schluss übersieht, dass sich das Flagellum durch ständigen Gebrauch nach und nach verfeinert haben kann, bis alle Teile aufeinander abgestimmt waren."],"correctIndex":0,"explanation":"Aus „ohne ein Teil funktioniert das heutige System nicht“ folgt nicht „es gab nie einfachere Vorstufen“. Teilfunktionen bieten zunächst oft andere Vorteile und werden später in neue Kontexte integriert (Exaptation). Beim Flagellum zeigt das Typ-III-Sekretionssystem, dass ein Teil seiner Bauteile auch ohne den Rest eine andere, nützliche Funktion erfüllen kann; ob es Vorläufer, Abkömmling oder nur Verwandter ist, ist umstritten. Evolution ist zudem kein reiner Zufall, sondern kombiniert zufällige Mutation mit nicht-zufälliger Selektion über lange Zeiträume.","coreRule":"⚡ „Heute nur im Ganzen funktionsfähig“ heißt nicht „ohne Vorläufer entstanden“: Teile können früher anderen Nutzen gehabt haben.","quote":"Evolutionäre Prozesse sind keine rein zufälligen Schritte, sondern kombinieren zufällige Mutation und nicht-zufällige Selektion zu einem Mechanismus, der Komplexität schrittweise aufbaut.","quoteLabel":"Merksatz:","scenario":"Du hörst diese Behauptung in einer Diskussion über die Entstehung komplexer Strukturen bei Bakterien.","beleg":"Werkstück F.1.7, Kontext & Tiefe Abschnitt 1 und 2; Fußnote gl-f-kitzmiller (Typ-III-Sekretionssystem als möglicher Vorläufer, Urteil S. 74–77)","kurz":"Dass heute ohne ein Teil nichts funktioniert, heißt nicht, dass es nie einfachere Vorstufen gab: Teile können zuerst anderen Nutzen gehabt haben und später in ein neues System eingebaut worden sein. Der Fehler ist, vom heutigen Zustand auf die Entstehung zu schließen.","prueffrage":"Woher weiß die Biologin, wie die Vorfahren dieser Bakterien ausgestattet waren?","rueckmeldung":[{"option":1,"text":"Eine Vorstufe, die zwar erhalten bleibt, aber noch nichts leistet, würde die Selektion nicht begünstigen. Tragfähig wird der Gedanke erst, wenn die Teile schon vorher irgendeinen anderen Nutzen hatten."},{"option":2,"text":"Schrittweise Entstehung ist durchaus möglich. Die Antwort setzt aber voraus, dass schon jedes einzelne Teil die Fortbewegung verbessert, und genau das bestreitet das Argument. Der Ausweg liegt bei Teilen, die zunächst etwas anderes leisteten."},{"option":3,"text":"Selektion über lange Zeiträume kann Teile tatsächlich aufeinander abstimmen. Der Gedanke setzt aber ein schon gebrauchtes, funktionierendes System voraus und erklärt nicht, wie es begann. Zudem wirkt Gebrauch nicht vererbbar auf den Bau, sondern Mutation und Selektion."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, U.S. District Court M.D. Pa., Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 74–77","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"66f954422a7141d0"}},{"id":"qf-10","status":"entwurf","clusterId":"F","werkstueckRef":"F.2.1","stufe":1,"question":"Was folgt daraus für die Behauptung des Anbieters?","options":["Beide haben praktisch dasselbe Horoskop, verlaufen aber verschieden. Legte die Planetenstellung den Charakter fest, müssten sie sich viel ähnlicher sein; die Behauptung passt nicht zur Beobachtung.","Beide wurden nicht genau gleichzeitig geboren, und schon wenige Minuten können ein Horoskop verändern. Die Unterschiede zwischen den beiden passen also durchaus zu der Behauptung des Horoskop-Anbieters.","Beide sind nur ein einzelnes Paar, und ein Einzelfall reicht nicht, um eine allgemeine Behauptung zu erschüttern. Dafür bräuchte man viele solche Paare; vorerst sagt das Beispiel wenig aus.","Beide müssten getrennt aufgewachsen sein, damit sich die Wirkung der Sterne von der Wirkung der Umgebung trennen lässt. Ohne das sagt das Paar über die Behauptung des Anbieters wenig aus."],"correctIndex":0,"explanation":"Wenn die Planetenstellung zur Geburtszeit den Charakter und Lebensweg festlegen soll, müssen Menschen mit praktisch gleicher Stellung sich ähnlich entwickeln. Eineiige Zwillinge, die am selben Ort fast gleichzeitig geboren werden, haben praktisch dasselbe Horoskop. Wenn sie sich trotzdem deutlich unterscheiden, passt die starke Behauptung der festen Kausalität nicht zur Beobachtung. Sauberer wäre der Test mit nicht verwandten „Zeitzwillingen“: Gut 2.000 Londoner, die im März 1958 geboren wurden, ähnelten ihren Zeitzwillingen in Intelligenz, Verhalten und Körpermerkmalen nicht stärker als beliebigen anderen. Eine getrennte Kindheit ist für den Test unnötig, denn die Behauptung betrifft die Planetenstellung, nicht die Erziehung.","coreRule":"⚡ Gleiche Ursache, verschiedene Wirkung: Wer behauptet, etwas bestimme den Charakter, muss erklären, warum Gleiches zu Verschiedenem führt.","quote":"","quoteLabel":"","scenario":"Ein Horoskop-Anbieter wirbt: „Die Planetenstellung bei der Geburt legt Charakter und Lebensweg fest.“ Du kennst ein eineiiges Zwillingspaar, das am selben Ort mit wenigen Minuten Abstand geboren wurde. Die beiden sind in Temperament, Beruf und Lebensweg sehr verschieden.","kurz":"Wer fast gleichzeitig am selben Ort geboren wird, hat praktisch dasselbe Horoskop. Würde es Charakter und Lebensweg festlegen, müssten sich solche Menschen ähneln. Dass die Zwillinge sehr verschieden sind, passt nicht zu dieser starken Behauptung.","prueffrage":"Welche Rolle spielen Gene oder Erziehung in der Behauptung des Anbieters überhaupt?","rueckmeldung":[{"option":1,"text":"Minuten können ein Horoskop tatsächlich ein wenig verschieben. Eine so kleine Verschiebung kann aber kaum erklären, dass die beiden in Temperament, Beruf und Lebensweg sehr verschieden sind, wenn die Stellung all das festlegen soll."},{"option":2,"text":"Ein einzelnes Paar ist schwache Evidenz, das stimmt. Die Behauptung ist aber stark: Sie sagt für alle mit gleicher Stellung ähnliche Entwicklung voraus. Ein deutliches Gegenbeispiel passt schlecht dazu, und die Aussage ist nicht bedeutungslos."},{"option":3,"text":"Getrenntes Aufwachsen würde Erziehung und Umgebung ausklammern. Die Behauptung nennt aber die Planetenstellung als Ursache, nicht die Erziehung. Für diesen Test ist die getrennte Kindheit nicht nötig, das Paar sagt also durchaus etwas über sie aus."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? Journal of Consciousness Studies 10(6–7), S. 175–198 (Webfassung)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0924f1ad301ab51e"}},{"id":"qf-11","status":"entwurf","clusterId":"F","werkstueckRef":"F.2.3","stufe":3,"question":"In einem Forum behauptet jemand: „In den Wäldern Nordamerikas lebt ein riesiger Menschenaffe. Bisher hat ihn nur niemand eindeutig erwischt, zum Beispiel mit einem Kadaver, einem Knochen oder verwertbarer DNA.“ Welche Frage prüft diese Behauptung am besten?","options":["Gibt es in Nordamerika Wälder, die so abgelegen und so dicht sind, dass ein großes Tier dort über lange Zeit unentdeckt bleiben könnte?","Gibt es viele voneinander unabhängige Augenzeugen, deren Beschreibungen des Tieres in Größe, Gestalt und Verhalten übereinstimmen?","Gibt es eine ganze Population aus Hunderten oder Tausenden Tieren, die sich fortpflanzt, ohne dass je ein eindeutiger Beleg gefunden wurde?","Gibt es große Tierarten, die lange als Legende galten und erst spät entdeckt wurden, sodass auch dieser Menschenaffe noch auftauchen könnte?"],"correctIndex":2,"explanation":"Ein einzelnes Tier kann keine Art begründen: Damit eine Art nicht ausstirbt, braucht sie eine Population, bei großen Säugetieren Hunderte, wenn nicht Tausende Individuen. Genau diese Population macht die Behauptung prüfbar. So viele große Tiere müssten fressen, sich fortpflanzen und sterben, und sie würden dabei Kadaver, Knochen, Exkremente oder DNA hinterlassen. Die entscheidende Frage lautet deshalb, wie eine solche Population absolut keine eindeutigen Spuren hinterlassen soll. Dass der Gorilla einst als Mythos galt, belegt Bigfoot nicht, es zeigt nur, dass die Welt damals weniger erforscht war.","coreRule":"⚡ Eine Art braucht eine Population, und eine Population hinterlässt Spuren.","quote":"","quoteLabel":"","scenario":"","kurz":"Eine Art besteht nicht aus einem Tier, sondern aus Hunderten oder Tausenden. So viele große Tiere würden Kadaver, Knochen oder DNA hinterlassen. Wer nur fragt, ob ein einzelnes Tier unentdeckt bleiben kann, übersieht diese Lücke.","prueffrage":"Was hinterlässt ein großes Säugetier, während es lebt, frisst und stirbt, und was davon wurde je gefunden?","rueckmeldung":[{"option":0,"text":"Abgelegene, dichte Wälder gibt es, und ein einzelnes Tier könnte dort wohl lange unentdeckt bleiben. Die Behauptung betrifft aber eine ganze Art, und deren Population hinterließe auch in dichtem Wald Spuren."},{"option":1,"text":"Übereinstimmende Berichte klingen nach Beleg. Es bleiben aber Berichte, die sich irren oder angleichen können, und sie ersetzen nicht, was die Behauptung als fehlend benennt: Kadaver, Knochen oder DNA."},{"option":3,"text":"Spät entdeckte Arten wie der Gorilla gibt es wirklich. Das zeigt nur, dass die Welt damals weniger erforscht war, und stützt die Behauptung nicht. Es nennt eine bloße Möglichkeit, prüft aber nichts."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): Minimum viable population size: A meta-analysis of 30 years of published estimates. Biological Conservation 139, S. 159–166 (Autorenfassung)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"S. 159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4d751ff6f54784f0"}},{"id":"qf-12","status":"entwurf","clusterId":"F","werkstueckRef":"F.2.4","stufe":2,"question":"Jemand sagt: „Wie sollen Menschen damals ohne moderne Technik die Pyramiden gebaut haben? Ich kann mir das nicht vorstellen. Also müssen es Aliens gewesen sein.“ Was ist an dieser Argumentationskette fehlerhaft?","options":["Aus zwei denkbaren Erklärungen wird eine gewählt, obwohl es neben Menschen und Aliens durchaus noch ganz andere Möglichkeiten geben könnte.","Aus der fehlenden modernen Technik wird auf fehlendes Können geschlossen, obwohl frühere Kulturen nicht an heutigen Maßstäben zu messen sind.","Aus der offenen Baufrage wird zu Recht eine Alternative erwogen; fehlerhaft ist nur das „müssen“, denn Aliens bleiben bloß eine Möglichkeit unter anderen.","Aus der eigenen Vorstellungslücke wird auf eine Erklärung geschlossen, obwohl fehlende Vorstellungskraft nichts darüber sagt, was möglich war."],"correctIndex":3,"explanation":"Die Kette lautet: „Ich kann mir nicht vorstellen, wie das ging, also waren es Aliens.“ Damit wird eine Grenze der eigenen Vorstellungskraft zum Beweis für eine ganz andere Erklärung gemacht. Das ist das Argument aus persönlichem Unglauben. Dass jemand sich etwas nicht ausmalen kann, sagt nichts darüber, was Menschen mit über Generationen angesammelter Erfahrung leisten können. Experimentelle Archäologie hat für fast alle angeblichen Rätsel dieser Art plausible menschliche Bau- und Transportmethoden demonstriert oder rekonstruiert. Die Alien-Hypothese umgeht so die Beweislast, statt sie zu erfüllen.","coreRule":"⚡ „Ich kann es mir nicht vorstellen“ beschreibt meine Grenze, nicht die Grenze der Menschen von damals.","quote":"","quoteLabel":"","beleg":"Werkstück F.2.4 (Prä-Astronautik), Abschnitt 3 „Die Konfrontation mit der Realität“ und Abschnitt 4 „Die Anatomie der Täuschung“","kurz":"Dass jemand sich den Bau nicht vorstellen kann, sagt nichts darüber, was Menschen mit Erfahrung über Generationen leisten konnten. Der Fehler liegt darin, eine Lücke der eigenen Vorstellung als Beleg für Aliens zu nehmen, statt die Behauptung zu begründen.","prueffrage":"Welche Belege nennt die Person für ihre eigene Erklärung, und gibt es dafür überhaupt welche?","rueckmeldung":[{"option":0,"text":"Dass es neben Menschen und Aliens noch andere Möglichkeiten gibt, stimmt. Selbst mit weiteren Alternativen bliebe der Schluss aber unbegründet, denn der Fehler sitzt früher: Aus einer Vorstellungslücke wird überhaupt eine Erklärung abgeleitet."},{"option":1,"text":"Frühere Kulturen sollte man tatsächlich nicht an heutigen Maßstäben messen. Der Sprecher behauptet aber nicht, sie hätten es nicht gekonnt, sondern nur, er könne es sich nicht vorstellen. Der Fehler liegt in diesem Schritt von der Lücke zur Erklärung."},{"option":2,"text":"Das „müssen“ ist tatsächlich zu stark, Aliens wären allenfalls eine Möglichkeit unter anderen. Zu Recht erwogen wird sie hier aber nicht: Sie entsteht allein aus der Vorstellungslücke, und genau darin liegt der eigentliche Fehler, nicht erst im Wort „müssen“."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Chow, D. (2014): „Solved! How Ancient Egyptians Moved Massive Pyramid Stones“. Live Science, nachgedruckt bei NBC News, 01.05.2014","oeffentlich":true,"url":"https://www.nbcnews.com/science/science-news/solved-how-ancient-egyptians-moved-massive-pyramid-stones-n95171","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"99ee5199b86c25e9"}},{"id":"qg-1","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.1","stufe":1,"question":"Eine Freundin sagt dir: „Ich bin endlich aufgewacht. Wer das alles noch glaubt, schläft einfach noch.“ Du widersprichst mit einem Gegenbeleg, sie antwortet: „Genau so reden Schlafschafe.“ Was ist an ihrer Argumentation das Kernproblem?","options":["Sie beruft sich auf ihr Erleben: Weil sie sich nun endlich wach fühlt, gilt ihr die eigene Sicht schon als bestätigt.","Sie greift dich als Person an: Statt auf deinen Gegenbeleg einzugehen, zählt sie dich zu den „Schlafschafen“.","Sie sortiert die Gegenseite vorab: Dein Widerspruch gilt als Beweis des Schlafs, so kann kein Beleg mehr zählen.","Sie entzieht sich der Beweislast: Für ihre eigene Sicht bringt sie keinen Beleg, nur das Wort „aufgewacht“."],"correctIndex":2,"explanation":"Die Freundin teilt die Welt in zwei Lager: Wer „wach“ ist, sieht die Wahrheit, wer widerspricht, „schläft“. Damit wird jeder Einwand schon vor der Prüfung entwertet, denn er gilt nicht als Argument, sondern als Symptom. Eine Behauptung, die durch kein denkbares Gegenargument mehr erschüttert werden kann, ist nicht prüfbar (unfalsifizierbar). Zugleich wird die Gegenseite zu fügsamen „Schafen“ herabgesetzt, sodass ein Gespräch über die Sache kaum noch möglich ist. Eine sinnvolle Reaktion: nicht darüber streiten, wer wach ist, sondern fragen, welcher Beleg sie überzeugen würde und welcher nicht.","coreRule":"⚡ Wenn Widerspruch selbst als Beweis gegen den Widersprechenden gilt, ist die Aussage gegen Prüfung abgeschirmt.","quote":"Jede Kritik von außen kann daher ignoriert werden; sie kommt ja nur von einem Schlafenden, der die wahre Realität nicht wahrnehmen kann.","quoteLabel":"Merksatz:","scenario":"","kurz":"Sie macht jeden Widerspruch zum Beweis dafür, dass der andere „schläft“. So kann kein Einwand mehr zählen und ihre Sicht ist nicht mehr prüfbar. Die Abwertung als „Schlafschaf“ verstärkt das, ist aber nicht der Kern.","prueffrage":"Worauf ging die Freundin in ihrer Antwort ein: auf den Inhalt deines Gegenbelegs oder auf etwas anderes?","rueckmeldung":[{"option":0,"text":"Dass sie sich wach fühlt, ist ihr Anlass, mehr aber nicht: Ein Gefühl von Klarheit ist kein Beleg. Das eigentliche Problem liegt in ihrer Reaktion auf deinen Gegenbeleg, den sie als Zeichen des Schlafs wertet."},{"option":1,"text":"Die Abwertung als „Schlafschafe“ trifft zu und erschwert das Gespräch. Sie ist aber nur die Begleiterscheinung: Das Kernproblem ist, dass dein Einwand schon vor der Prüfung nichts mehr zählt."},{"option":3,"text":"Ein Beleg für ihre Sicht fehlt tatsächlich. Selbst mit Belegen bliebe das Muster aber bestehen, solange jeder Widerspruch als Symptom des Schlafs gilt und deshalb nichts sie mehr erschüttern kann."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"65f489570dde89be"}},{"id":"qg-2","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.2","stufe":2,"question":"Woran erkennst du am ehesten, dass diese Aufforderung eher Gefolgschaft als echte Prüfung meint?","options":["Daran, dass die Aufforderung Unabhängigkeit verspricht, die „Recherche“ aber nur Beiträge aus der eigenen Echokammer wiederholt.","Daran, dass er Experten pauschal ablehnt, obwohl Fachleute auf ihrem Gebiet meist mehr wissen als jemand, der selbst sucht.","Daran, dass er dich zur eigenen Recherche auffordert, obwohl man als Laie eine Fachfrage kaum allein beurteilen kann.","Daran, dass alle vier Videos zum selben Schluss kommen, obwohl bei ehrlicher Prüfung die Quellen einander auch widersprechen müssten."],"correctIndex":0,"explanation":"Ein Aufruf zum Selbstdenken ist nur dann echte Prüfung, wenn er ergebnisoffen ist und auch die stärksten Gegenargumente einbezieht. Hier führen alle „eigenen“ Quellen aus demselben Umfeld zum selben vorgegebenen Ergebnis. Das ist Bestätigungssuche und Anpassung an die Gruppe, getarnt als Unabhängigkeit. Ein Hinweis darauf: In einer US-Panelbefragung sank bei Befragten, die „eigene Recherche ist so viel wert wie Expertenwissen“ stärker zustimmten, binnen drei Monaten eher das Vertrauen in die Wissenschaft, und sie hielten mehr Falsches über COVID-19 für wahr. Der Zusammenhang war schwach, und die Autoren deuten ihn eher als Haltung gegen Experten als als Bekenntnis zu sorgfältiger Prüfung. Eine gute Gegenfrage lautet daher: „Wie stellst du sicher, dass du nicht nur Bestätigung suchst? Wo hast du aktiv nach den stärksten Argumenten gegen deine Position gesucht?“","coreRule":"⚡ Scheinbare Autonomie: Wer „selbst recherchiert“, aber nur Bestätigung aus der eigenen Echokammer sammelt, prüft nicht ergebnisoffen.","quote":"","quoteLabel":"","scenario":"Ein Bekannter hält dir entgegen: „Glaub nicht den Experten, recherchier lieber selbst!“ Er schickt dir vier Videos aus seinem Lieblingskanal, die alle denselben Schluss ziehen.","kurz":"Echte Prüfung ist ergebnisoffen und sucht auch die stärksten Gegenargumente. Hier kommen alle „eigenen“ Quellen aus demselben Umfeld und führen zum vorgegebenen Schluss: Das ist Bestätigungssuche, die als Unabhängigkeit auftritt.","prueffrage":"Wer hat ausgewählt, was du dir ansehen sollst, und was davon hast du selbst gefunden?","rueckmeldung":[{"option":1,"text":"Dass Fachleute auf ihrem Gebiet meist mehr wissen, stimmt. Doch auch eine Ablehnung von Experten sagt noch nicht, ob jemand prüft oder nur folgt: Entscheidend ist, ob die Suche ergebnisoffen verläuft."},{"option":2,"text":"Bei Fachfragen stoßen Laien tatsächlich schnell an Grenzen. Das spricht aber gegen eigene Recherche überhaupt und zeigt nicht, ob hier Prüfung oder Gefolgschaft gemeint ist."},{"option":3,"text":"Vier gleichlautende Videos sind ein Warnsignal, aber nicht der Kern. Auch gut belegte Aussagen können von mehreren Quellen gleich beurteilt werden. Entscheidend ist, dass alle Beiträge aus demselben Umfeld stammen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d9d2e68db643a412"}},{"id":"qg-3","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.3","stufe":2,"question":"Welche Wirkung hat schon das Wort „Schulmedizin“ in diesem Satz?","options":["Das Wort lässt die wissenschaftliche Medizin wie eine unter mehreren gleichrangigen Lehrmeinungen erscheinen und rückt die unbelegte Methode auf Augenhöhe.","Das Wort stellt die wissenschaftliche Medizin als starr und verschult hin, als lerne man dort nur Lehrbuchwissen, statt auf den einzelnen Menschen zu schauen.","Das Wort beschreibt neutral, wer Medizin lehrt und wo sie gelehrt wird, und enthält deshalb keine Wertung über die Qualität der einzelnen Verfahren.","Das Wort stellt die wissenschaftliche Medizin als herrschende Mehrheitsmeinung dar und lässt die eigene Methode als mutige Gegenstimme dazu erscheinen."],"correctIndex":0,"explanation":"Das Wort meint eigentlich die an Universitäten gelehrte Medizin und ist allgemein gebräuchlich. In diesem Satz wirkt es aber als Kampfbegriff: „Nur eine von mehreren Schulen“ macht die wissenschaftliche Medizin zu einer Lehrmeinung unter vielen und unterstellt zwei gleichwertige Lager, eine falsche Symmetrie. Tatsächlich unterscheidet man Methoden danach, ob ihre Wirksamkeit nach wissenschaftlichen Standards nachgewiesen ist; das ist keine Frage der Schulzugehörigkeit, sondern von Belegen. So verschiebt der Satz die Frage „Wirkt es?“ zu „Welche Schule bevorzugst du?“. Eine bessere Rückfrage lautet: „Meinst du die wissenschaftsbasierte Medizin, die sich durch Testung und Überprüfung ständig selbst korrigiert?“","coreRule":"⚡ Falsche Symmetrie: Es gibt keine zwei Schulen – es gibt Evidenz oder keine Evidenz.","quote":"","quoteLabel":"","scenario":"Ein Heilpraktiker wirbt für eine Methode, deren Wirksamkeit in Studien nicht belegt ist. Im Gespräch sagt er: „Die Schulmedizin ist nur eine von mehreren Schulen, wir bieten eine gleichwertige Alternative.“","beleg":"Werkstück G.2.3, Abschnitte 2 und 4 (Strohmann, falsche Symmetrie, Aktivierungs-Frage); keine Fußnoten-ID; Kurzquelle: Buchtext","kurz":"Das Wort „Schulmedizin“ macht die wissenschaftliche Medizin zu einer Lehrmeinung unter vielen und täuscht zwei gleichwertige Lager vor. Tatsächlich entscheidet nicht die Schulzugehörigkeit, sondern ob die Wirksamkeit belegt ist.","prueffrage":"Was erfährst du über die Wirksamkeit eines Verfahrens, wenn du nur hörst, zu welcher „Schule“ es gehört?","rueckmeldung":[{"option":1,"text":"Das Wort wird tatsächlich oft mit Starrheit und Lehrbuchwissen verbunden. In diesem Satz geht es aber um „eine von mehreren Schulen“, also um Gleichrangigkeit, nicht um fehlenden Blick auf den einzelnen Menschen."},{"option":2,"text":"Eigentlich meint das Wort schlicht die an Universitäten gelehrte Medizin und ist allgemein gebräuchlich. In diesem Satz ist es aber nicht wertungsfrei, sondern wird als Kampfbegriff eingesetzt, um zwei gleichwertige Lager zu behaupten."},{"option":3,"text":"Eine Gegenstimme zur Mehrheit setzt voraus, dass es um Mehrheit und Minderheit geht. Der Satz behauptet aber Gleichwertigkeit zweier Schulen, und ob eine Methode wirkt, hängt von Belegen ab, nicht davon, wie viele sie vertreten."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Koehler, D. J. (2016): Can journalistic “false balance” distort public perception of consensus in expert opinion? J Exp Psychol Appl 22(1), 24–38 (Abstract auf PubMed)","oeffentlich":true,"doi":"10.1037/xap0000073","url":"https://pubmed.ncbi.nlm.nih.gov/26752513/","abruf":"2026-10-12"},{"typ":"url","kurz":"Haufe: Schulmedizinklausel § 4 Abs. 6 MB/KK 94 ist wirksam (Kommentar)","oeffentlich":true,"url":"https://www.haufe.de/id/kommentar/schulmedizinklausel-4-abs-6-mbkk-94-ist-wirksam-HI947826.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Heissmann, N.; Weymayr, C. (2012): Die Homöopathie-Lüge, Teil 5","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6ce3573ab7c6326d"}},{"id":"qg-4","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.3","stufe":2,"question":"Was ist an diesem Argument fehlerhaft?","options":["Sie schließt aus dem Schmerz des Streits mit ihren Bekannten auf die Wahrheit ihrer „Erkenntnis“, obwohl auch Irrtümer und Ideologien Freundschaften kosten.","Sie hält an ihrer „Erkenntnis“ fest, weil sie dafür schon Freundschaften geopfert hat, obwohl dieser Verlust allein kein Grund ist, weiter daran zu glauben.","Sie wertet den Widerspruch ihrer Bekannten als Zeichen, dass diese sich der Wahrheit verschließen, obwohl Widerspruch auch aus guten eigenen Gründen kommen kann.","Sie wirft ihren Bekannten vor, sich zu verschließen, obwohl sie selbst deren Einwände nun nicht mehr anhört und sich damit genauso verschließt wie diese."],"correctIndex":0,"explanation":"Das Argument macht aus dem Leiden einen Beweis: Weil der Streit wehtut, soll die Überzeugung stimmen. Das ist ein Fehlschluss, denn die Kosten einer Überzeugung sagen nichts darüber, ob sie wahr ist. Auch Irrtümer und Ideologien können Freundschaften kosten, und richtige Einsichten kommen manchmal ganz ohne Streit aus. Entscheidend sind die Gründe für eine Überzeugung, nicht der Preis, den sie fordert. Eine hilfreiche Gegenfrage lautet: Woran würdest du merken, dass du dich irrst?","coreRule":"⚡ Leiden ist kein Beweis: Ein hoher Preis sagt nichts über Wahrheit. Welche Methode prüft die Überzeugung?","quote":"Die rote Pille verspricht die schmerzhafte Wahrheit. Dies rechtfertigt die sozialen Kosten (Konflikte mit Freunden), die mit dem Glauben verbunden sind.","quoteLabel":"Merksatz:","scenario":"Eine Freundin hat sich in den letzten Monaten einer „alternativen“ Sicht auf die Welt zugewandt und spricht von ihrem „Aufwachen“. Zu mehreren Bekannten hat sie den Kontakt abgebrochen, weil die sich ihrer „Erkenntnis“ verschließen. Dir gegenüber begründet sie das so: „Wer die Wahrheit sieht, muss Streit aushalten. Dass es wehtut, zeigt, dass ich auf dem richtigen Weg bin.“","beleg":"Werkstück G.1.3: „Die rote Pille nehmen“ (Red Pilling). Abschnitt „Kontext & Tiefe“ (Validierung des Leidens) sowie „Das Härten im Feuer“ (Aktivierungs-Frage). Keine Fußnote im Buchtext vorhanden.","kurz":"Aus dem Schmerz des Streits folgt nichts über die Wahrheit ihrer Überzeugung, denn auch Irrtümer und Ideologien kosten Freundschaften. Der Fehler: den Preis einer Überzeugung für einen Beleg zu halten, statt nach ihren Gründen zu fragen.","prueffrage":"Welchen Grund außer dem Schmerz nennt die Freundin dafür, dass ihre Erkenntnis stimmt?","rueckmeldung":[{"option":1,"text":"Dass bereits Geopfertes kein Grund zum Glauben ist, stimmt. Ihr Argument ist aber ein anderes: Sie nimmt den Schmerz des Streits selbst als Zeichen, auf dem richtigen Weg zu sein, und macht so aus dem Leiden einen Beweis."},{"option":2,"text":"Dass Widerspruch gute eigene Gründe haben kann, ist richtig. Der zitierte Satz setzt aber an anderer Stelle an: Er macht den Schmerz des Streits zum Zeichen der Wahrheit, und genau dieser Schluss trägt nicht."},{"option":3,"text":"Davon, dass sie Einwände nicht mehr anhört, steht im Szenario nichts. Sie begründet mit dem Schmerz des Streits, nicht mit Zuhören oder Nichtzuhören; der Fehler liegt im Schluss vom Schmerz auf die Wahrheit."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"18","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a2f2640c9cd5089b"}},{"id":"qg-5","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.4","stufe":4,"question":"Welche Erwiderung führt die Diskussion an dieser Stelle am besten weiter?","options":["„Du hast recht, es ist dein Körper; aber schau dir die Daten trotzdem an, denn sie betreffen auch dein eigenes Erkrankungsrisiko.“","„Du hast recht, niemand darf dich zwingen; aber bei Ansteckung trifft deine Wahl auch die Unversehrtheit der Risikogruppen.“","„Du hast unrecht, denn wer sich in einer Gesundheitsfrage auf seine Freiheit beruft, weicht den vorgelegten Daten nur aus.“","„Du hast recht, das ist allein deine Entscheidung; lassen wir die Daten kurz beiseite und sprechen erst über deine Gründe.“"],"correctIndex":1,"explanation":"Körperliche Selbstbestimmung schützt vor Zwang und ist ein Fundament freier Gesellschaften; eine gute Erwiderung stimmt dem Recht deshalb zuerst zu. Problematisch wird der Slogan, wenn das Recht als grenzenlos gilt und die vorhersehbare Gefährdung anderer, hier durch Ansteckung, als belanglos abgetan wird, wie es der Satz „spielt keine Rolle“ tut. Dann stehen zwei Rechte gegeneinander: die Selbstbestimmung des Einen und die körperliche Unversehrtheit der Anderen. Ein Slogan, der diesen Konflikt für nicht existent erklärt, beendet die Diskussion; die Erwiderung, die das Recht anerkennt und den Konflikt benennt, führt sie weiter. Wer jede Berufung auf Freiheit als Ausweichen abtut, übersieht, dass etwa die Ablehnung einer empfohlenen Operation für sich legitim ist, weil die Folgen vor allem die Person selbst trägt; entscheidend ist, ob Dritte vorhersehbar betroffen sind und ob das ausgeblendet wird.","coreRule":"⚡ Stimm dem Recht zu und zeig den Konflikt: Zwei Rechte stehen gegeneinander.","quote":"Es ist die Verwechslung von „Freiheit von Zwang“ (legitim) mit „Freiheit, andere zu gefährden“ (ein systemisches Problem).","quoteLabel":"Merksatz:","scenario":"In einer Debatte über eine Impfempfehlung legt jemand Daten zu Ansteckung und Risikogruppen vor. Eine andere Person antwortet: „Das mag alles sein. Aber mein Körper, meine Wahl. Wie sich das auf andere auswirkt, spielt keine Rolle.“ Du moderierst und willst das Gespräch wieder in Gang bringen, statt es eskalieren zu lassen.","beleg":"Werkstück G.1.4, Abschnitte „Der Kipppunkt“, „Red Flags“, „Das Adaptive Talent“ und „Das Anti-Denkmuster (Skript 1)“; keine Fußnoten","kurz":"Das Recht auf Selbstbestimmung schützt vor Zwang, und das sollte man zuerst anerkennen. Der Slogan kippt, wenn er die Gefährdung anderer für belanglos erklärt: Dann stehen zwei Rechte gegeneinander, und genau diesen Konflikt benennt die Erwiderung.","prueffrage":"Wer trägt die Folgen dieser Entscheidung, und wären davon auch Menschen betroffen, die gar nicht mitentschieden haben?","rueckmeldung":[{"option":0,"text":"Die Zustimmung zum Recht ist gut, und das eigene Risiko mag durchaus eine Rolle spielen. Behauptet wurde aber, die Wirkung auf andere sei egal; dieser Punkt bleibt hier unberührt, der Konflikt wird nicht benannt."},{"option":2,"text":"Hier steckt etwas Berechtigtes: Die Auswirkung auf andere wird tatsächlich ausgeblendet. Freiheit zu beanspruchen ist aber nicht grundsätzlich Ausweichen, und ohne Anerkennung des Rechts wirkt der Satz wie ein Angriff, der das Gespräch eher abbricht."},{"option":3,"text":"Nach den Gründen zu fragen kann ein Gespräch öffnen. Die Entscheidung gilt aber nur dann als „allein“ die eigene, wenn Dritte nicht vorhersehbar betroffen sind. Bei Ansteckung bleibt dieser Punkt unbesprochen."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Grundgesetz Art. 2 (freie Entfaltung, soweit Rechte anderer nicht verletzt; Recht auf körperliche Unversehrtheit)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_2.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"743bcaaf7095ff28"}},{"id":"qg-6","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.1","stufe":2,"question":"Welche Antwort erklärt am besten, warum sich eine Behauptung wie „Die Eliten steuern alles“ kaum widerlegen lässt?","options":["Der Sprecher behauptet eine umfassende Steuerung, deshalb kann ein einzelner entlasteter Politiker eine so weit gefasste Aussage höchstens ein wenig ankratzen.","Der Sprecher lässt offen, wer „die Eliten“ sind, deshalb lässt sich der entlastete Politiker als Marionette einer noch tiefer verborgenen Elite umdeuten.","Der Sprecher ist von seiner Sicht fest überzeugt, deshalb lässt er sich auch von deinem genauen Nachweis über den Politiker nicht mehr umstimmen.","Dein Nachweis betrifft nur die Abstimmung, deshalb bleibt offen, ob der Politiker den Beschluss nicht auf anderem Weg im Hintergrund beeinflusst hat."],"correctIndex":1,"explanation":"Die Behauptung nennt nie genau, wer gemeint ist. Dadurch kann sie jeden Gegenbeweis auffangen: Wird ein Beschuldigter entlastet, war er eben „nur eine Marionette“. Eine Behauptung, die durch keine denkbare Beobachtung widerlegt werden kann, sagt in Wahrheit nichts Prüfbares mehr. Wirksam ist deshalb die Frage nach Spezifität: Wer genau gehört dazu? Welcher überprüfbare Beleg zeigt, dass sich diese Personen abgesprochen haben, um dieses konkrete Ziel zu erreichen? Vage Begriffe wie „die Eliten“ bedeuten niemanden und zugleich jeden und sind deshalb unangreifbar und beliebig einsetzbar.","coreRule":"⚡ Bestehe auf Spezifität: Wer genau, welcher Beleg, welches Ziel?","quote":"","quoteLabel":"","scenario":"In einer Diskussion sagt jemand: „Die Eliten steuern alles.“ Du weist nach, dass der Politiker, den er als Drahtzieher genannt hat, bei dem fraglichen Beschluss gar nicht mitgestimmt hat. Die Antwort kommt prompt: „Der war doch nur eine Marionette. Die wahren Eliten sitzen dahinter.“","kurz":"Die Behauptung sagt nie, wer genau gemeint ist, und kann so jeden Gegenbeweis auffangen: Wer entlastet wird, war eben „nur eine Marionette“. Eine Aussage, die keine denkbare Beobachtung widerlegen kann, sagt nichts Prüfbares mehr.","prueffrage":"Wen genau nennt dein Gegenüber als Drahtzieher, nachdem der Politiker entlastet ist?","rueckmeldung":[{"option":0,"text":"Die Behauptung ist tatsächlich umfassend. Das macht sie aber nicht „ein wenig angekratzt“, sondern gar nicht angreifbar: Es liegt nicht an ihrer Weite, sondern daran, dass offen bleibt, wer gemeint ist, und sich daher jeder Fall umdeuten lässt."},{"option":2,"text":"Dass jemand an seiner Sicht festhält, kommt vor, erklärt aber nicht, warum die Aussage selbst unwiderlegbar ist. Selbst bei einem offenen Gegenüber ließe sich eine so unscharfe Behauptung jederzeit anpassen. Der Kern liegt in der Behauptung, nicht in der Haltung des Sprechers."},{"option":3,"text":"Richtig ist, dass ein Nachweis über die Abstimmung verdeckten Einfluss nicht ausschließt. Doch das wäre ein neues Argument, das der Sprecher belegen müsste. Der eigentliche Grund liegt tiefer: Weil „die Eliten“ niemanden festlegen, lässt sich jede Entlastung umdeuten."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7e7a8f3cd0c9859a"}},{"id":"qg-7","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.2","stufe":2,"question":"In einer Diskussion sagt jemand: „Dass die Zeitung diesen Bericht gebracht hat, beweist nur wieder, dass die Lügenpresse lügt. Auf die glaubt man nichts mehr.“ Du fragst, welcher Artikel denn welche Falschaussage enthalten habe. Die Antwort lautet: „Das ist ja gerade das Problem: Die sagen alle dasselbe.“ Was ist an dieser Argumentation das Kernproblem?","options":["Die Person erklärt die Zeitung samt ihren Berichten vorab für unglaubwürdig, ohne einen Fehler zu nennen, sodass nichts ihr Weltbild mehr erschüttern kann.","Die Person stützt sich darauf, dass man der Zeitung allgemein nichts mehr glaubt, sodass die Verbreitung einer Meinung den fehlenden Beleg ersetzen soll.","Die Person schließt von diesem einen Bericht auf die Zeitung insgesamt, sodass ein möglicher Fehler in einem einzelnen Artikel zum Urteil über die ganze Presse wird.","Die Person greift die Zeitung mit einem abwertenden Schlagwort an, sodass sie die Redaktion herabsetzt, statt sich mit dem Inhalt des Berichts zu befassen."],"correctIndex":0,"explanation":"Der Pauschalvorwurf nennt keinen konkreten Fehler, sondern erklärt jede unbequeme Information im Voraus für unglaubwürdig. So lässt sich jede Gegeninformation als weiterer „Beweis“ umdeuten, und nichts kann das eigene Weltbild mehr erschüttern: Es ist nicht geprüft, sondern abgeschottet. Auch „Die sagen alle dasselbe“ ist nur ein Etikett, das „die Medien“ zu einer einzigen Stimme macht, obwohl Zeitungen mit gegensätzlicher Ausrichtung einander oft widersprechen; wer das behauptet, müsste es an einem konkreten Fall belegen. Zudem ist „Lügenpresse“ ein historisch belasteter Begriff, der spätestens im Ersten Weltkrieg zum nationalistischen Kampfbegriff wurde und den die NS-Propaganda antisemitisch zuspitzte. Wer ihn benutzt, knüpft an diese Vorgeschichte an, ob bewusst oder nicht.","coreRule":"⚡ Wer jede Gegeninformation vorab für unglaubwürdig erklärt, hat nichts geprüft. Frag nach dem konkreten Artikel: Welche überprüfbare Falschaussage, wann, und wurde sie korrigiert?","quote":"Lasst uns über Beweise reden, nicht über pauschale Etiketten.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück G.2.2, Abschnitte 2 (Versiegelung der Echokammer, Strohmann, historische Anknüpfung), 3 (Ad Hominem, Bestätigungsfehler), 4 (Aktivierungs-Frage); Fußnote gl-g-1","kurz":"Wer eine Zeitung pauschal für unglaubwürdig erklärt und keinen konkreten Fehler nennt, entwertet jede Gegeninformation im Voraus. Das Weltbild wird so nicht geprüft, sondern abgeschottet, und „Die sagen alle dasselbe“ ist nur ein Etikett dafür.","prueffrage":"Welchen Artikel und welche Falschaussage nennt die Person, nachdem du ausdrücklich danach gefragt hast?","rueckmeldung":[{"option":1,"text":"Dass „Die sagen alle dasselbe“ unbelegt bleibt, stimmt. Die Person beruft sich aber nicht auf eine verbreitete Meinung, sondern entwertet alle Berichte vorab. Das Kernproblem ist diese Abschottung gegen jede Prüfung."},{"option":2,"text":"Ein Schluss vom Einzelfall aufs Ganze setzt einen Fehler im Einzelfall voraus. Hier wird aber gar kein Fehler im Bericht genannt: Der Vorwurf gilt von Anfang an pauschal und braucht keinen Anlass."},{"option":3,"text":"„Lügenpresse“ ist tatsächlich ein abwertender, historisch belasteter Begriff, und das ist ein Mangel. Das Kernproblem liegt aber tiefer: Ohne konkreten Fehler wird jede Information vorab entwertet und das eigene Weltbild abgeschottet."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schmitz-Berning, C. (2007): Vokabular des Nationalsozialismus. 2. Aufl. Berlin, New York: de Gruyter, s. v. „Journaille“","oeffentlich":false,"seite":"327"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7f4c790d85b3a913"}},{"id":"qg-8","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.4","stufe":4,"question":"Welcher Einwand trifft den Kern des Problems am besten?","options":["Ein unterstelltes Motiv wird wie ein Beleg behandelt, und aus dem Gewinninteresse der Firmen wird ohne weiteren Nachweis auf eine böse Absicht geschlossen.","Medikamente werden pauschal als „Gifte“ bezeichnet, und dabei wird übersehen, dass dieselben Mittel vielen Kranken helfen und manchen sogar das Leben retten.","Viele konkurrierende Unternehmen werden zu einem Akteur mit gemeinsamem Plan erklärt, und Studien werden pauschal verworfen, statt ihre Methodik zu prüfen.","Die Kritik an industriefinanzierten Studien wird zu Recht erhoben, und nur die zugespitzte Sprache des Sprechers schadet hier seiner im Kern berechtigten Sache."],"correctIndex":2,"explanation":"Kritik an der Pharmaindustrie kann berechtigt sein, denn es gibt nachgewiesenes Fehlverhalten einzelner Unternehmen, etwa bei Preisgestaltung oder Marketing. Der Fehler liegt woanders: Viele konkurrierende Firmen werden pauschal zu einem einzigen böswilligen Akteur mit gemeinsamem Plan erklärt. Zudem wird jede industriefinanzierte Studie allein wegen ihrer Herkunft verworfen, ohne Methodik und Ergebnisse zu prüfen; die Finanzierung ist ein Grund, genauer hinzusehen, ersetzt aber nicht die Prüfung. Wer so argumentiert, kann aus Misstrauen am Ende auch lebensrettende Behandlungen ablehnen. Ein gutes Gegenargument fragt nach der Adresse der Kritik: Welches Unternehmen, welche Praxis, welcher Beleg?","coreRule":"⚡ Kritik braucht eine Adresse: Welcher Konzern, welche Praxis, welcher Beleg?","quote":"","quoteLabel":"","scenario":"In einer Diskussion über Arzneimittelpreise sagt jemand: „Big Pharma will uns alle krank halten, um uns ihre Gifte zu verkaufen. Jede Studie, die von der Industrie bezahlt wurde, kannst du vergessen.“","kurz":"Viele konkurrierende Firmen werden zu einem Akteur mit gemeinsamem Plan gemacht, und Studien fallen allein wegen ihrer Herkunft durch. Berechtigt ist Kritik an einzelnen Praktiken; die Finanzierung verlangt genaueres Hinsehen, ersetzt aber nicht die Prüfung.","prueffrage":"Welche Firma, welche Praxis und welcher Beleg sind in der Aussage konkret gemeint?","rueckmeldung":[{"option":0,"text":"Ein unbelegtes Motiv ist tatsächlich schwach. Es ist aber nur ein Teil des Problems: Der Kern liegt darin, dass viele konkurrierende Firmen zu einem Akteur mit gemeinsamem Plan zusammengefasst und Studien pauschal verworfen werden."},{"option":1,"text":"Dass Medikamente vielen helfen, stimmt, und „Gifte“ ist pauschal. Das ist aber eher eine Folge als der Kern: Der Fehler liegt in der Gleichsetzung aller Firmen und im Verwerfen von Studien allein nach ihrer Herkunft."},{"option":3,"text":"Kritik an industriefinanzierten Studien kann berechtigt sein, und Finanzierung ist ein Grund, genauer hinzusehen. Hier wird aber nicht genauer hingesehen, sondern jede Studie verworfen. Das Problem liegt also im Schluss und nicht nur im Ton."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8132492/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Krumholz, H. M.; Ross, J. S.; Presler, A. H.; Egilman, D. S. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"1e7e618c442a23c3"}},{"id":"qg-9","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"2d208b9fa7b495ba","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"clusterId":"G","werkstueckRef":"G.3.1","stufe":1,"question":"Eine Saftkur wird mit dem Versprechen beworben, „Schlacken“ und „Toxine“ auszuleiten. Welche Rückfrage prüft dieses Versprechen am besten?","options":["Welches Unternehmen steht hinter der Werbung für die Saftkur, wer hat sie bezahlt, und verdient es an jedem verkauften Kurpaket mit?","Welcher einzelne Stoff unter den „Toxinen“ soll die Saftkur ausleiten, und wie wurde seine Menge vor und nach der Kur gemessen?","Wie wurden die zufriedenen Kundinnen und Kunden der Saftkur ausgewählt, und wie viele von ihnen haben auf die Umfrage geantwortet?","Welche Menge Saft muss man an den Tagen der Kur täglich trinken, und ist diese Menge für Menschen mit Vorerkrankungen unbedenklich?"],"correctIndex":1,"explanation":"Ein Versprechen wie „Ausleiten von Toxinen“ lässt sich nur prüfen, wenn klar ist, was ausgeleitet werden soll. Deshalb hilft die Frage nach einem benannten Stoff und nach einer Messung vor und nach der Kur: Ohne diese Angaben gibt es nichts, was sich überprüfen oder widerlegen ließe. Dazu kommt: Der Körper hat mit Leber und Nieren eigene Organe, die schädliche Substanzen abbauen und ausscheiden. Ein Angebot müsste also erklären, warum diese Organe bei einem bestimmten Stoff versagen. Eine Übersichtsarbeit von Klein und Kiat (2015) fand keine randomisierten kontrollierten Studien zu kommerziellen Detox-Diäten beim Menschen und sah keine überzeugenden Belege für Detox-Diäten zur Giftausleitung. Die Frage nach dem Anbieter klingt nach gesunder Skepsis, sagt aber nichts darüber, ob überhaupt etwas ausgeleitet wird. Die Frage nach der Auswahl zufriedener Kundschaft prüft, wie zufrieden sie ist, nicht, ob ein Stoff verschwindet. Die Frage nach Trinkmenge und Verträglichkeit betrifft die Sicherheit der Kur, nicht ihre behauptete Wirkung.","coreRule":"⚡ Wer „Gift“ sagt, muss den Stoff benennen und die Messung zeigen.","quote":"Nenne mir ein einziges. Wie heißt es chemisch? Wie hat man seine Konzentration in deinem Körper vor und nach der Kur gemessen?","quoteLabel":"Prüffrage:","scenario":"In der Werbung heißt es, die Kur reinige den Körper von „Schlacken“ und „Toxinen“, die sich durch Umwelt und Ernährung angesammelt hätten. Welche Stoffe das genau sind, steht dort nicht.","beleg":"Werkstück G.3.1, Fußnote gl-g-detox: Klein & Kiat (2015), J Hum Nutr Diet 28(6), 675–686; Rückfrage des Biochemikers aus der Einleitung des Werkstücks.","kurz":"Ein Versprechen wie „Toxine ausleiten“ ist nur prüfbar, wenn ein benannter Stoff und eine Messung davor und danach vorliegen. Ohne das bleibt der Begriff ein dehnbares Wort, das sich nie widerlegen lässt, und genau darauf beruht seine Wirkung.","prueffrage":"Angenommen, die Kur leitet gar nichts aus: Bei welcher Auskunft des Anbieters würdest du das bemerken?","rueckmeldung":[{"option":0,"text":"Ein Geschäftsinteresse ist ein berechtigter Grund zur Vorsicht, sagt aber nichts über die Wirkung: Auch ein Anbieter, der verdient, könnte etwas Wirksames verkaufen. Ob überhaupt etwas ausgeleitet wird, zeigt nur die Prüfung der Behauptung selbst."},{"option":2,"text":"Wie die zufriedenen Kunden ausgewählt wurden, ist eine gute Frage an Erfahrungsberichte. Sie klärt aber nur, wie verlässlich die Zufriedenheit ist, nicht, ob ein Stoff verschwindet. Dafür bräuchte es einen benannten Stoff und eine Messung."},{"option":3,"text":"Trinkmenge und Verträglichkeit betreffen die Sicherheit der Kur und sind wichtig, gerade bei Vorerkrankungen. Sie sagen aber nichts darüber, ob die behauptete Wirkung eintritt, und prüfen das Versprechen damit nicht."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"},{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (NIH): Detoxes and Cleanses: What You Need To Know (Stand März 2025)","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2d208b9fa7b495ba"}},{"id":"qg-10","status":"entwurf","clusterId":"G","werkstueckRef":"G.3.2","stufe":3,"question":"Eine Homöopathin sagt: „Mein Mittel ist so stark verdünnt, dass kein Wirkstoffmolekül mehr enthalten ist. Aber das Wasser behält die ‚Information‘ der Ursubstanz. Und beim Verschütteln werden alle früheren Informationen des Wassers gelöscht, nur diese eine bleibt.“ Welche Rückfrage setzt am schwächsten Punkt an und nutzt die Beweislast?","options":["Durch welchen Versuch ist belegt, dass Verschütteln alle früheren Informationen löscht und nur die eine speichert?","Wie oft muss man das Wasser verschütteln, damit die Information des Mittels darin dauerhaft erhalten bleibt?","Wie viele Verdünnungsschritte sind nötig, bis sich kein einziges Wirkstoffmolekül mehr in der Lösung befindet?","Warum vertrauen so viele Patienten diesen Mitteln, wenn das Verfahren den Gesetzen der Chemie widerspricht?"],"correctIndex":0,"explanation":"Die Aussage, Schütteln lösche alle alten Informationen und speichere nur die eine neue, ist eine zusätzliche Hilfsannahme, die gerade den offensichtlichen Einwand abwehren soll: Wasser hat im Lauf seiner Geschichte unzählige Stoffe berührt, warum sollte es sich ausgerechnet an die letzte Ursubstanz erinnern? Die Beweislast liegt bei dem, der die Annahme einführt. Er muss zeigen, dass genau dieser Vorgang diese Eigenschaft hat, etwa in einem verblindeten Versuch. Dass solche Behauptungen oft nicht standhalten, zeigt der Fall Benveniste: Sein 1988 gemeldeter Effekt hochverdünnter Antikörper verschwand bei verblindeter Auswertung. Die Frage, wie oft man schütteln muss, setzt die Annahme schon voraus, statt sie zu prüfen. Wie viele Verdünnungsschritte nötig sind, lässt sich ausrechnen und ist ohnehin zugestanden, denn die Rednerin räumt selbst ein, dass kein Molekül mehr enthalten ist. Und warum Patienten vertrauen, ist eine Frage der Psychologie, nicht des Belegs für die Behauptung.","coreRule":"⚡ Wer eine Hilfsannahme einführt, schuldet den Test für genau diese Annahme.","quote":"Wie nützlich wäre dieser USB-Stick?","quoteLabel":"Prüffrage:","scenario":"","beleg":"Werkstück G.3.2, Abschnitt „Die Schmiede-Übung“ sowie Fußnote gl-g-4: Davenas u. a. (1988), Nature 333, S. 816–818; Maddox/Randi/Stewart (1988), Nature 334, S. 287–290.","kurz":"Die Hilfsannahme, Verschütteln lösche alles Frühere und behalte nur die eine Information, soll den Einwand abwehren. Die Beweislast liegt bei der Rednerin, deshalb setzt die Frage nach dem Versuch dort an, wo sie etwas zeigen müsste.","prueffrage":"Für welche Teile ihrer Behauptung nennt die Homöopathin einen Beleg, und welche setzt sie einfach voraus?","rueckmeldung":[{"option":1,"text":"Die Schüttelzahl wirkt wie eine kritische, präzise Frage. Sie setzt aber schon voraus, dass das Wasser die Information überhaupt behält, und prüft die Annahme nicht, sondern übernimmt sie."},{"option":2,"text":"Die Zahl der Schritte lässt sich ausrechnen, und die Rednerin räumt selbst ein, dass kein Molekül mehr enthalten ist. Die Frage trifft also einen zugestandenen Punkt und nicht die Behauptung, die Belege braucht."},{"option":3,"text":"Dass sich das Verfahren schwer mit der Chemie verträgt, ist ein berechtigter Gedanke. Warum Patienten vertrauen, ist aber eine Frage der Psychologie und liefert keinen Beleg dafür oder dagegen, dass Wasser Information speichert."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Maddox, J.; Randi, J.; Stewart, W. W. (1988): „High-dilution“ experiments a delusion. Nature 334, 287–290","oeffentlich":false,"doi":"10.1038/334287a0"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7324f06082f85899"}},{"id":"qg-11","status":"entwurf","clusterId":"G","werkstueckRef":"G.3.3","stufe":2,"question":"Welche Rückfrage prüft diese Behauptung am besten?","options":["Wie viele sind nach einer Infektion tatsächlich geschützt, und wie viele erleiden auf diesem Weg einen schweren Verlauf oder sterben daran?","Wie lange hält der Schutz nach einer überstandenen Infektion an, und ist er dann stärker oder schwächer als der Schutz nach einer Impfung?","Wie zuverlässig entsteht nach einer Infektion ein Schutz, und lässt er sich bei den Genesenen anschließend im Blut auch nachweisen?","Schützt eine überstandene Infektion auch dann noch, wenn sich der Erreger verändert, und wie oft kommt es danach zu einer erneuten Ansteckung?"],"correctIndex":0,"explanation":"Die Behauptung vergleicht zwei Wege zum selben Ziel, nennt aber nur das Ziel: den Schutz. Die Frage nach Schutzquote und Sterblichkeit holt den Preis des Weges zurück auf den Tisch. Eine überstandene Krankheit hinterlässt zwar oft einen robusten Schutz, doch der Weg dorthin kann tödlich sein oder bleibende Schäden hinterlassen. Der Hinweis auf „Millionen Jahre“ wirbt mit dem Wort „natürlich“, statt etwas über Nutzen und Risiko zu zeigen. Außerdem ist „natürliche Immunität“ nicht bei jeder Krankheit besser: Bei Tetanus hinterlässt die Infektion keine Immunität, die Impfung schon. Bei HPV ist die Impfantwort stärker und verlässlicher als nach einer Infektion. Wer prüfen will, ob ein Weg der bessere ist, vergleicht beide samt ihren Risiken und nicht nur das Ergebnis.","coreRule":"⚡ Vergleiche die Wege samt ihren Risiken, nicht nur das Ergebnis.","quote":"Wir vergleichen hier nicht zwei gleichwertige Ergebnisse.","quoteLabel":"Merksatz:","scenario":"In einer Diskussion über Impfungen sagt jemand: „Ich setze auf natürliche Immunität, die ist seit Millionen Jahren erprobt. Ich brauche keine Impfung.“","beleg":"Werkstück G.3.3, Abschnitt „Das Härten im Feuer“, Aktivierungs-Frage; Abschnitte „Kernidee“ und „Kontext & Tiefe“; Fußnoten gl-g-2 (Tetanus, CDC Pink Book), gl-g-3 (HPV, Ghilencea u. a. 2026) und gl-g-reinfektion (COVID-19 Forecasting Team 2023, The Lancet)","kurz":"Die Behauptung nennt nur das Ziel, den Schutz, und verschweigt den Preis des Weges. Wer fragt, wie viele nach einer Infektion geschützt sind und wie viele schwer erkranken oder sterben, vergleicht beide Wege samt Risiko, statt dem Wort „natürlich“ zu vertrauen.","prueffrage":"Welche zwei Wege zum Schutz stehen sich hier gegenüber, und was erfährst du über jeden der beiden?","rueckmeldung":[{"option":1,"text":"Die Schutzdauer ist ein sinnvoller Vergleichspunkt, denn auch eine überstandene Infektion schützt oft lange. Die Frage bleibt aber beim Ergebnis und lässt offen, was der Weg dorthin kostet: schwere Verläufe, Todesfälle, bleibende Schäden."},{"option":2,"text":"Wie zuverlässig und nachweisbar der Schutz entsteht, ist wissenswert, betrifft aber wieder nur das Ergebnis. Ein guter Antikörperwert im Blut sagt nichts darüber, wie viele auf dem Weg dorthin schwer erkrankt oder gestorben sind."},{"option":3,"text":"Dass sich ein Erreger verändern und Schutz nachlassen kann, ist ein berechtigter Punkt. Er betrifft aber wieder nur, wie gut der Schutz hält, und nicht, was die Infektion als Weg dorthin kostet. Das erst erlaubt einen fairen Vergleich beider Wege."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV: A Comparative Review of Antibody Response and Cancer Prevention. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a2b904b27b98204c"}},{"id":"qh-1","status":"entwurf","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Eine Forscherin behauptet: Wer kurz an den eigenen Tod erinnert wird, urteilt über Normbrecher deutlich härter. Als Beleg nennt sie ein Experiment mit 22 Richtern: Die Kontrollgruppe setzte im Schnitt 50 Dollar Kaution fest, die Gruppe, die zuvor Fragen zur eigenen Sterblichkeit beantwortet hatte, 455 Dollar. Wie sicher darfst du aus diesem Experiment allein auf den behaupteten Zusammenhang schließen?","options":["Nur vorläufig: Ein Einzelexperiment mit 22 Richtern ist ein erster Hinweis auf den Zusammenhang, aber noch kein ausreichender Beleg dafür.","Mit Einschränkung: Für Richter gilt der Zusammenhang als belegt, denn ein Unterschied von 50 zu 455 Dollar ist zu groß, um bei 22 Personen auf Zufall zu beruhen.","Mit Einschränkung: Der Zusammenhang gilt als belegt, solange die Deutung der Forscherin hält, denn sie erklärt den Unterschied von 50 zu 455 Dollar schlüssig.","Nur eingeschränkt: Aus 22 Richtern eines Berufs folgt für andere Menschen nichts, deshalb taugt der Befund auch nicht als erster Hinweis auf den Zusammenhang."],"correctIndex":0,"explanation":"Der Befund stammt aus einem einzelnen, kleinen Experiment mit nur 22 Richtern. Die Forscher deuten ihn so, dass die Erinnerung an den Tod ein Bedürfnis weckt, die eigene Weltanschauung zu verteidigen, und Normbrecher deshalb als Bedrohung wirken. Das ist aber eine Deutung und kein Beweis. Mehrere große Replikationsversuche zur Todeserinnerung sind seither gescheitert. Many Labs 4 wiederholte dabei allerdings nicht das Richter-Experiment, sondern einen anderen klassischen Befund derselben Richtung. Das Richter-Experiment ist deshalb die Gründungsgeschichte der Theorie, kein gesicherter Befund. Die vernünftige Haltung: als Hinweis ernst nehmen, aber nicht zur Schlagzeile machen. Ein großer Unterschied klingt überzeugend, doch bei nur 22 Personen kann er durch Zufall oder einzelne Ausreißer entstehen, auch wenn man ihn auf Richter beschränkt. Eine schlüssige Deutung klingt nach Belastbarkeit, ersetzt aber keine Wiederholung des Versuchs. Der Schluss, der Befund tauge nicht einmal als Hinweis, ist ebenso übertrieben, denn ein einzelnes Experiment ist schwache, aber nicht wertlose Evidenz.","coreRule":"⚡ Je kleiner die Stichprobe und je spektakulärer das Ergebnis, desto mehr braucht es unabhängige Wiederholung, bevor man ihm traut.","quote":"","quoteLabel":"","scenario":"Ein Artikel greift das Ergebnis auf und titelt: „Todesangst macht Menschen gnadenlos.“ Du sollst einschätzen, wie viel die Datenlage hergibt.","kurz":"Ein Einzelexperiment mit 22 Richtern ist ein Hinweis, kein Beleg. Der Fehler liegt darin, einen großen Unterschied oder eine schlüssige Deutung für Beweiskraft zu halten, obwohl bei so wenigen Personen auch Zufall oder Ausreißer dahinterstecken können.","prueffrage":"Wie viele Richter saßen in jeder Gruppe, und wie stark könnte ein einzelner Richter mit einer sehr hohen Kaution den Durchschnitt verschieben?","rueckmeldung":[{"option":1,"text":"Der Unterschied von 50 zu 455 Dollar ist tatsächlich groß und auffällig. Bei nur 22 Personen können aber schon einzelne Ausreißer oder der Zufall so große Abstände erzeugen, auch wenn man sich auf Richter beschränkt."},{"option":2,"text":"Die Deutung ist stimmig und erklärt den Unterschied plausibel. Eine schlüssige Erklärung zeigt aber nur, dass der Befund verständlich wäre, nicht dass er stimmt. Dafür braucht es Wiederholungen des Versuchs."},{"option":3,"text":"Von 22 Richtern lässt sich tatsächlich nicht einfach auf alle Menschen schließen. Daraus folgt aber nicht, dass der Befund wertlos ist: Ein einzelnes Experiment ist schwache, aber nicht wertlose Evidenz und gibt einen Hinweis, dem man nachgehen kann."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false},{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? A set of failed replications of the mortality salience effects of Terror Management Theory. PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4b62c1e76edd8c3d"}},{"id":"qh-2","status":"entwurf","clusterId":"H","werkstueckRef":"H.1.1","stufe":2,"question":"Was ist an Toms Reaktion das eigentliche Denkproblem?","options":["Tom reagiert zu laut und zu schnell, statt sich erst zu beruhigen und danach sachlich zu antworten.","Tom geht auf die Annahme zum Wachstum gar nicht ein und lässt so die Sachfrage in der Rechnung offen.","Tom wirft Lena vor, es auf ihn abgesehen zu haben, und macht ihre Absicht statt ihres Einwands zum Thema.","Tom hält Kritik an seiner Annahme für einen Angriff auf sich selbst und verteidigt sich deshalb."],"correctIndex":3,"explanation":"Lenas Einwand betrifft eine Annahme in der Rechnung, Tom hört darin ein Urteil über sich als Person. Wer seinen Selbstwert an eine Idee hängt, erlebt jede Kritik daran als Angriff und verteidigt dann die Identität statt die Wahrheit. Damit wird auch die Prüfung unmöglich, ob die Annahme wirklich fehlerhaft ist: Man kann eine Hypothese nur ernsthaft prüfen und notfalls fallen lassen, wenn ihr Scheitern nicht den eigenen Wert zerstört. Hilfreich ist die Unterscheidung: Eine Idee ist etwas, das man hat, nicht etwas, das man ist. Dann ist ein gefundener Fehler eine nützliche Information, kein persönliches Versagen.","coreRule":"⚡ Trenne dein Selbstwertgefühl von deiner Hypothese: Wer Kritik an der Idee als Angriff auf die Person erlebt, kann sie nicht mehr prüfen.","quote":"","quoteLabel":"","scenario":"Lena zu ihrem Kollegen Tom: „Deine Berechnung hat einen Fehler in der Annahme zum Wachstum.“ Tom wird laut: „Du hast es schon immer auf mich abgesehen! Ich lasse mir von dir nicht sagen, dass ich nichts kann.“","kurz":"Tom hört in Lenas Hinweis auf eine Annahme ein Urteil über sich als Person und verteidigt deshalb seine Identität statt seine Rechnung. Wer Idee und Selbstwert verknüpft, kann die Annahme nicht mehr offen prüfen.","prueffrage":"Was erfährt man aus Toms Antwort darüber, ob die Annahme zum Wachstum stimmt?","rueckmeldung":[{"option":0,"text":"Ruhe würde dem Gespräch sicher helfen. Der Ton ist aber nicht die Wurzel: Auch leise würde Tom Lenas Einwand als Urteil über sich hören und sich verteidigen, statt die Annahme anzusehen."},{"option":1,"text":"Tatsächlich bleibt die Sachfrage unbeantwortet. Das ist aber die Folge eines tieferen Problems: Tom lässt den Einwand nicht liegen, weil er ihn als Angriff auf sich erlebt, nicht aus bloßer Unaufmerksamkeit."},{"option":2,"text":"Mit der Unterstellung lenkt Tom wirklich vom Einwand ab. Sie ist aber ein Symptom: Dahinter steht, dass er die Kritik an der Annahme als Urteil über sich als Person hört und deshalb seine Identität verteidigt."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2), 180–198 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"aedfe9ae3fb923b4"}},{"id":"qh-3","status":"entwurf","clusterId":"H","werkstueckRef":"H.1.6","stufe":3,"question":"Wie reagierst du in dieser Situation am hilfreichsten?","options":["Du beendest das Telefonat und meldest dich erst wieder, wenn sie die Überzeugung vom vergifteten Trinkwasser aufgegeben hat, damit du dich selbst schützt.","Du erkennst, welche Angst vor dem vergifteten Trinkwasser sie antreibt, nimmst ihr Gefühl ernst und bleibst selbst ruhig, sodass du ihr einen Anker bietest.","Du legst ihr die Messwerte des Wasserwerks und Gutachten zum Trinkwasser vor, damit sie anhand der Zahlen erkennt, dass die Angst unbegründet ist.","Du fühlst ihre Angst vor dem vergifteten Trinkwasser voll mit, teilst ihre Sorge und bleibst am Telefon, bis sie sich beruhigt hat, auch wenn dich das auslaugt."],"correctIndex":1,"explanation":"Wer die Panik des anderen voll mitfühlt, schwingt mit ihr mit und wird leicht selbst handlungsunfähig; bei Ärzten, Pflegenden und Angehörigen gilt dieser „empathische Stress“ als Risikofaktor für Erschöpfung und Burnout. Tragfähig ist die Kombination aus Verstehen und Fürsorge: Du erkennst, warum die Person so denkt und fühlt, nimmst ihre Angst ernst und bleibst selbst ruhig, und so kannst du ihr einen stabilen Anker bieten. Die Trainingsstudie von Klimecki, Singer u. a. (2014) stützt das: Empathie-Training verstärkte Aktivität in Arealen für Schmerz und negativen Affekt, während Mitgefühls-Training die Aktivierung in Areale des Belohnungs- und Zugehörigkeitssystems verschob.","coreRule":"⚡ Fühle FÜR die Person, nicht MIT ihrer Panik.","quote":"Man ertrinkt mit dem Ertrinkenden, anstatt ihm den Rettungsring zuzuwerfen.","quoteLabel":"Merksatz:","scenario":"Deine Tante ruft dich panisch an: Sie ist überzeugt, dass „die da oben“ das Trinkwasser vergiften, und redet sich immer weiter in Angst hinein. Du merkst, wie ihre Panik auf dich überspringt. Du willst ihr helfen, ohne dich dabei selbst auszulaugen und ohne sie zu verlieren.","beleg":"Werkstück H.1.6, Fußnote gl-h-empathie (Singer/Klimecki 2014; Klimecki et al. 2014)","kurz":"Hilfreich ist, die Angst deiner Tante zu verstehen und ernst zu nehmen und dabei selbst ruhig zu bleiben. So wirst du für sie ein Anker. Wer die Panik voll mitfühlt, schwingt leicht mit ihr mit und kann ihr dann kaum noch Halt geben.","prueffrage":"Was macht ihre Panik gerade mit dir, und woran würde deine Tante merken, dass du ihr wirklich zuhörst?","rueckmeldung":[{"option":0,"text":"Sich zu schützen ist berechtigt, und eine Pause kann sinnvoll sein. Der Rückzug unter der Bedingung, dass sie ihre Überzeugung aufgibt, lässt sie mit der Angst allein und kostet genau die Beziehung, die du erhalten willst."},{"option":2,"text":"Messwerte und Gutachten sind eine gute Grundlage, und später können sie durchaus helfen. Einen Menschen in Panik erreichen Zahlen aber kaum, solange sein Gefühl nicht gehört wurde; sie kommen dann leicht als Abwehr der Sorge an."},{"option":3,"text":"Volles Mitfühlen wirkt zugewandt und ist gut gemeint. Weil du dabei ihre Panik übernimmst, schwingst du leicht mit ihr mit und laugst aus, statt ihr Halt zu geben. Dein Dranbleiben ist dabei nicht das Problem, sondern das Mitschwingen."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8c0530cdef8f2040"}},{"id":"qh-4","status":"entwurf","clusterId":"H","werkstueckRef":"H.2.2","stufe":2,"question":"Dein Kollege sagt: „Ich bin zu 95 % sicher, dass Heilkristalle Krankheiten heilen. Meine Kopfschmerzen sind nach einem Rosenquarz verschwunden.“ Du willst ihn nicht überrumpeln, sondern ihn dazu bringen, selbst zu prüfen, wie verlässlich sein Weg zu dieser Sicherheit ist. Welche Frage hilft dabei am meisten?","options":["Wie könntest du selbst prüfen, ob wirklich dein Rosenquarz die Kopfschmerzen beseitigt hat, und wie verlässlich ist ein solcher Weg zu deinen 95 % Sicherheit?","Haben auch andere Menschen in deinem Umfeld nach dem Tragen eines Rosenquarzes über verschwundene Kopfschmerzen berichtet, und wie sicher sind sie sich dabei?","Welcher Vorgang im Körper soll erklären, dass ein Rosenquarz Kopfschmerzen lindert, und gibt es dafür eine anerkannte Theorie, auf die du dich stützt?","Hat dir der Rosenquarz auch schon bei anderen Beschwerden geholfen, und hast du mit ihm dabei ähnlich gute Erfahrungen gemacht wie bei den Kopfschmerzen?"],"correctIndex":0,"explanation":"Wer eine Überzeugung direkt angreift, löst meist eine defensive Reaktion aus, und das Gespräch ist beendet. Wirksamer ist es, das Verfahren zu untersuchen, das zur Überzeugung geführt hat. Hier ist es die persönliche Erfahrung: Die Kopfschmerzen sind nach dem Rosenquarz verschwunden. Diese Methode kann täuschen, denn die Ursache könnte auch der Placebo-Effekt sein, oder die Kopfschmerzen wären von allein weggegangen. Die Frage lädt dazu ein, solche Alternativen zu bedenken und nach einem verlässlicheren Test zu suchen, ohne dass jemand „falsch“ gesagt bekommt.","coreRule":"⚡ Untersuche das Verfahren, nicht die Schlussfolgerung: Frag, wie jemand etwas weiß und ob dieser Weg verlässlich ist.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück H.2.2, Geschichte (Ansatz A/B), Struktur der Methode Schritte 4 und 5; Fußnote gl-h-4 (Boghossian 2013)","kurz":"Hier geht es darum, wie der Kollege zu seiner Sicherheit kam: durch eine einzelne Erfahrung, die auch Placebo oder von selbst vergehende Kopfschmerzen erklären könnten. Die Frage lässt ihn das Verfahren selbst prüfen, statt ihm zu widersprechen.","prueffrage":"Worauf stützt dein Kollege seine Sicherheit: auf Studien, auf das Urteil von Fachleuten oder auf ein eigenes Erlebnis?","rueckmeldung":[{"option":1,"text":"Mehr Berichte aus dem Umfeld wirken wie zusätzliche Belege. Es bleiben aber Einzelerfahrungen derselben Art, die dieselben Alternativen offenlassen, etwa Placebo oder Kopfschmerzen, die von allein vergehen. Die Methode wird so nicht geprüft, sondern nur vervielfacht."},{"option":2,"text":"Nach einem Wirkmechanismus zu fragen ist berechtigt, ein fehlender wäre ein Warnsignal. Die Frage zielt aber auf die Überzeugung selbst, nicht auf den Weg dorthin. Sie verlangt eine Rechtfertigung und löst eher Verteidigung aus, als dass sie zum eigenen Prüfen einlädt."},{"option":3,"text":"Weitere Erfolgserlebnisse würden den Eindruck des Kollegen eher festigen. Sie bleiben Erfahrungsberichte derselben Art und klären nicht, ob Placebo oder ein von selbst endender Verlauf die Besserung erklärt. So bleibt das Verfahren selbst unhinterfragt."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b486dad2ebc08fa6"}}]`);export{t as n,n as t};